const TERMS_DATA = [{"id": 1, "term": "JIS", "summary": "・日本の産業やIT製品・サービスの品質やサイズを統一する国家ルール。\n・試験ではISOとの関係や、セキュリティ・個人情報保護基準がよく問われる。", "keywords": "・国家規格\n・互換性の確保\n・品質の統一\n・ISOとの違い", "analogy": "「国が定めたルールをクリアした、みんなが共通で使える安心な基準」です。\n例えば、どこのメーカーの単3電池も同じサイズで使えるのはJIS規格のおかげです。ITの身近な例では「JIS配列キーボード」など。", "details": "日本国内の製品、データ、サービスの品質、性能、寸法、試験方法などを統一する国家規格。\n互換性の確保、品質の維持・向上、生産効率の増進が目的。IT分野では文字コードやセキュリティの基準などを定める。", "etymology": "Japanese Industrial Standards の略。\n直訳すると「日本の産業の標準規格」。かつては「日本工業規格」だったが、現在はITやサービス業を含めるため「日本産業規格」に改称されている。", "exam": "主に「標準化活動」の分野で出題されます。\n・国際規格のISO等との違いや関係性。\n・「JIS Q 15001（Pマークの基準）」「JIS Q 27001（ISMSの基準）」は頻出。", "def30": "製品やサービスの品質・互換性を統一するための日本の国家規格。（30文字）"}, {"id": 2, "term": "アムダールの法則\n(Amdahl's law)", "summary": "・複数のプロセッサで並列処理を行っても、並列化できない処理の割合によって全体の高速化に限界があるという法則。\n・プロセッサ数を増やすだけでは際限なく速くはならないことを示し、計算問題としてよく問われる。", "keywords": "・並列処理\n・高速化の限界（上限）\n・プロセッサ数\n・逐次処理（並列化できない処理）の割合", "analogy": "「10人で引っ越し作業をする」イメージ。\n荷物を運ぶ作業は10人で手分けすれば10倍速いですが、「トラックで移動する時間」は人数が増えても変わりません。この移動時間がある限り、全体の作業時間はゼロには近づかないという限界を示します。", "details": "コンピュータのプログラムを「並列化（複数のプロセッサで手分け）」して高速化する際、並列化できない部分の割合によって、システム全体の性能向上の限界が決まるという法則。", "etymology": "提唱者であるコンピュータ・アーキテクトの「ジーン・アムダール (Gene Amdahl)」の名前に由来する法則（Law）。", "exam": "システムアーキテクチャ（性能評価）の分野で頻出。\n「並列化できない部分が20%ある場合、プロセッサ数を無限に増やしても最大何倍までしか速くならないか？（答え：5倍）」といった計算問題が出ます。", "def30": "並列処理できない部分の割合で、全体の高速化の限界が決まる法則。（31文字）"}, {"id": 3, "term": "相補演算", "summary": "・元の論理演算や集合演算の結果を反転（否定・補集合）させる演算のこと。\n・NANDやNORなどの論理回路の構成や、2の補数を用いた加算による引き算（減算）の基礎となる。", "keywords": "・NOT演算（否定）\n・NAND演算 / NOR演算\n・補集合（Complement）\n・ド・モルガンの法則\n・2の補数（加算器による減算）", "analogy": "「『〇〇以外』を選ぶ反転スイッチ」です。\n「ラーメンと餃子を【両方頼んだ（AND）】」の裏返し（相補）は「【両方頼んではいない（NAND）】」となり、条件をまるごと反転して判定・計算する仕組みです。", "details": "ある演算結果の否定（補）となる値を求める演算。論理回路においては、NANDやNORなどの相補演算素子のみを組み合わせることで、あらゆる論理回路を構築できる（完全性）。また、コンピュータ内部で引き算を加算回路で処理するための「補数計算（2の補数等）」の根幹をなす。", "etymology": "Complementary Operation。Complementary（お互いに補い合う、全体の補集合の） ＋ Operation（演算）。", "exam": "テクノロジ系（基礎理論・論理回路）で頻出！\n・ド・モルガンの法則による論理式の変形問題\n・NAND素子やNOR素子のみを用いた論理回路の構成問題\n・2の補数表現を用いたビット演算・加減算問題", "def30": "元の演算結果の否定や補集合を求める演算。NAND等に利用。（30文字）"}, {"id": 4, "term": "待ち行列モデル\n(M/M/1モデル)", "summary": "・窓口が1つ、先着順（FCFS）で処理され、客の到着と処理時間がランダム（指数分布）な混雑計算モデル。\n・平均利用率 ρ ＝ λ / μ 、平均待ち時間、平均系内数などの計算問題が午前・午後ともに頻出。", "keywords": "・ポアソン到着（到着間隔が指数分布）\n・指数分布（サービス時間）\n・窓口数1（シングルサーバー）\n・先着順（FCFS：First-Come, First-Served）\n・平均利用率（ρ ＝ λ / μ）\n・平均待ち時間（Wq ＝ ρ / (μ(1 - ρ))）\n・平均系内数（L ＝ ρ / (1 - ρ)）", "analogy": "「先着順で並ぶ1人オペレーターのラーメン屋の行列」です。\nお客さんがいつ来るかもランダム（M）、ラーメンを作る時間もランダム（M）、店員は1人（1）で、到着した先着順（FCFS）に処理します。", "details": "オペレーションズ・リサーチ（OR）における待ち行列理論の最も基本的なモデル。第1のMは「到着間隔がマルコフ的（指数分布/ポアソン到着）」、第2のMは「サービス時間がマルコフ的（指数分布）」、最後の1は「窓口数が1」を意味する。サービス規律は割り込みのない「先着順（FCFS）」を前提とする。", "etymology": "M/M/1 Queueing Model。\nM は Markovian（マルコフ的：ランダムで無記憶な確率過程）。1 は 1つのサーバー（窓口）。規律は FCFS (First-Come, First-Served)。", "exam": "計算問題の超頻出項目！\n・前提条件：先着順（FCFS: First-Come, First-Served）\n・平均利用率 ρ ＝ 到着率 λ / サービス率 μ\n・平均待ち時間 Wq ＝ (ρ / (1 - ρ)) × 平均サービス時間\n「利用率が一定値を超えた場合に待ち時間が急増する現象」や具体的な時間計算が出題されます。", "def30": "窓口1つ・先着順で到着と処理がランダムな場合の待ち行列モデル。（32文字）"}, {"id": 5, "term": "稼働率・MTBF・MTTR", "summary": "・システムの壊れにくさと直りやすさを示す指標。稼働率の計算に使われる。\n・MTBF（平均故障間隔：稼働時間）とMTTR（平均修復時間：修理時間）。", "keywords": "・MTBF（稼働時間）\n・MTTR（修理時間）\n・直列システムの稼働率\n・並列システムの稼働率\n・バスタブ曲線", "analogy": "「家電の寿命と修理時間」です。\nMTBFは「何時間連続で使えるか（寿命）」、MTTRは「壊れたら修理に何時間かかるか」を表します。", "details": "システムの信頼性・可用性の指標。MTBFは故障から次の故障までの平均時間（稼働時間の平均）。MTTRは故障から復旧までの平均時間。稼働率 = MTBF / (MTBF + MTTR)。", "etymology": "Mean Time Between Failures / Mean Time To Repair。", "exam": "計算問題の超定番！直列（Aの稼働率 × Bの稼働率）と並列（1 - (1-A)(1-B)）の計算式は絶対に暗記してください。", "def30": "故障までの平均時間(MTBF)と修理の平均時間(MTTR)の指標。（33文字）"}, {"id": 6, "term": "RASIS", "summary": "・コンピュータシステムが持つべき「信頼性・可用性・保守性・保全性・安全性」の5要素。\n・システム評価の基本指標となる。", "keywords": "・Reliability（信頼性）\n・Availability（可用性）\n・Serviceability（保守性）\n・Integrity（保全性）\n・Security（安全性）", "analogy": "「優秀な車の条件」です。\n壊れない（信頼）、いつでも乗れる（可用）、修理しやすい（保守）、荷物が傷まない（保全）、盗まれない（安全）。", "details": "システムを総合的に評価する指標。信頼性(MTBF)、可用性(稼働率)、保守性(MTTR)、保全性(データ破壊がないか)、安全性(情報漏洩がないか)の頭文字。", "etymology": "Reliability, Availability, Serviceability, Integrity, Securityの頭文字。", "exam": "それぞれの意味を問う問題が頻出。「保守性（修理のしやすさ）＝MTTRが短いこと」といった関連付けが重要です。", "def30": "コンピュータシステムの評価指標となる5つの特性の頭文字。（28文字）"}, {"id": 7, "term": "フォン・ノイマン・ボトルネック", "summary": "・プログラム内蔵方式のコンピュータで、CPUと主記憶（メモリ）間のデータ転送速度がボトルネックとなり全体の処理が制限される現象。", "keywords": "・プログラム内蔵方式（ノイマン型）\n・CPUとメモリ間のバス帯域\n・データ転送速度の遅延\n・キャッシュメモリでの緩和", "analogy": "「超高速な料理人と、狭くて遅い料理運び用の小窓」です。\n料理人（CPU）は一瞬で調理できますが、小窓（バス）から料理（データ）を渡す速度が追いつかず、待ち時間が発生してしまいます。", "details": "プログラムとデータを同じ主記憶に置いて順次読み出すノイマン型コンピュータにおいて、CPUの処理速度に比べバスのデータ転送速度が遅いために生じる性能上の限界。", "etymology": "John von Neumann（提唱者の数学者）＋ Bottleneck（ボトルの首・狭窄部）。", "exam": "計算機構造の根本知識。「CPUと主記憶間のバス転送速度が障害となる＝ノイマンボトルネック」「これを緩和する対策＝キャッシュメモリの搭載、バスの広帯域化」。", "def30": "CPUとメモリ間の転送速度が限界となり全体の処理を制約する現象。（32文字）"}, {"id": 8, "term": "キャッシュメモリ\n(ヒット率・実効アクセス時間)", "summary": "・CPUと主記憶の速度差を埋める高速なメモリ。ヒット率が高いほど処理が高速になる。\n・「実効アクセス時間 ＝ キャッシュ時間 × ヒット率 ＋ 主記憶時間 × (1 - ヒット率)」は計算超頻出。", "keywords": "・ヒット率\n・主記憶\n・実効アクセス時間\n・ライトスルー\n・ライトバック", "analogy": "「デスクの上の手の届く棚（キャッシュ）」と「図書室の棚（主記憶）」のイメージ。\nよく使う書類をデスクの上に置いておくと探しに行く時間を短縮できます。デスク上に書類がある確率が「ヒット率」です。", "details": "CPUと主記憶（メインメモリ）の間に配置される高速・小容量のメモリ。アクセス頻度の高いデータを一時保持し、処理の高速化を図る。", "etymology": "Cache（隠し場所、一時保管場所）＋ Memory。\nよく使うデータをすぐ出せる手元の一時保管場所に格納しておくメモリのこと。", "exam": "計算問題の超頻出項目。「実効アクセス時間」の計算式を丸暗記して当てはめる問題が出ます。また、書き込み方式（ライトスルー＝主記憶も同時に更新／ライトバック＝キャッシュのみ更新し後で反映）の違いも問われます。", "def30": "CPUと主記憶のアクセス速度差を埋める高速な小型メモリ。（28文字）"}, {"id": 9, "term": "ダイレクトマップ方式\n(キャッシュ割り当て)", "summary": "・キャッシュメモリの割り当て方式の一つ。\n・主記憶のアドレスによって格納されるキャッシュ上の場所が「1箇所に一意に決まる」方式。構造が簡単で高速。", "keywords": "・フルアソシアティブ\n・セットアソシアティブ\n・ヒット率\n・ライン指定\n・競合ノイズ", "analogy": "「コインロッカーの番号固定指定」です。\n「105番の荷物は絶対に105番ロッカーに入れる」と決めておくため、探すのは一瞬ですが、同じロッカーを別の荷物が使うと競合が起きます。", "details": "主記憶のブロックがキャッシュメモリのどのラインに格納されるかがアドレス計算によって一義的に決まる方式。回路が単純でアクセスが最速だが、同一ラインへの競合が起きやすい。", "etymology": "Direct Mapped（直接割り振られた）。", "exam": "キャッシュメモリ構造で出題。「割り当て場所が一意に決まる＝ダイレクトマップ」「どこでも格納可能＝フルアソシアティブ」「中間＝セットアソシアティブ」の違いを理解。", "def30": "主記憶のアドレスからキャッシュの格納場所が一意に決まる割り当て方式。（34文字）"}, {"id": 10, "term": "パイプラインハザード", "summary": "・CPUのパイプライン処理で、命令のスムーズな並列実行が阻害され命令待ちが発生する現象。\n・構造ハザード、データハザード、制御ハザードの3種。", "keywords": "・構造ハザード（資源競合）\n・データハザード（依存関係）\n・制御ハザード（分岐命令）\n・分岐予測\n・バイパシング", "analogy": "「ベルトコンベアの目詰まり」です。\n前のパーツの塗装が終わるまで次の組み立てができない（データハザード）ように、前の処理待ちでラインがストップしてしまいます。", "details": "パイプライン処理において、次の命令を実行できない状態。\n・構造ハザード：ハードウェア資源の競合。\n・データハザード：先行命令の結果未確定。\n・制御ハザード：分岐命令による先行フェッチの無駄。", "etymology": "Pipeline Hazard（パイプライン上の危険・障害）。", "exam": "アーキテクチャ分野で頻出！「分岐命令によって生じるハザードは何か＝制御ハザード」「制御ハザードの対策＝分岐予測、投機実行」が問われます。", "def30": "パイプライン処理で命令の連続実行が阻害され遅延が生じる現象。（30文字）"}, {"id": 11, "term": "VLIW\n(超長命令語)", "summary": "・1つの極めて長い命令語の中に複数の独立した演算命令を埋め込み、CPUで同時に実行させるコンパイラ依存の高速化技術。", "keywords": "・Very Long Instruction Word\n・コンパイラ最適化\n・超長命令\n・命令レベル並列性\n・スーパスカラとの対比", "analogy": "「1枚の特大指示書に全員分の命令を書く」方式です。\nCPU側で命令の重なりを判断する（スーパスカラ）のではなく、事前にコンパイラ（ソフト）が特大指示書（VLIW）にまとめておきます。", "details": "1つの非常に長い命令の中に複数の命令（演算、メモリアクセス等）をパックし、複数の演算器で同時に実行させるプロセッサ技術。命令の依存関係の解析と最適化をハードではなく「コンパイラ」が行う。", "etymology": "Very Long Instruction Word（非常に長い命令語）。", "exam": "アーキテクチャ分野で出題。「複数命令を1つの長い命令にまとめて並列実行する」「並列実行の判断をコンパイラが行う＝VLIW（スーパスカラはハードウェアが行う）」の違い。", "def30": "1つの長い命令に複数の処理を埋め込みコンパイラ主導で並列実行する技術。（35文字）"}, {"id": 12, "term": "ジョブ・プロセス・スレッド", "summary": "・OSが管理する処理の実行単位の違い。\n・ジョブ（利用者の作業単位） ＞ プロセス（OSのメモリ空間単位） ＞ スレッド（プロセス内の最小実行単位）。", "keywords": "・ジョブ（利用者単位）\n・プロセス（メモリ空間分離）\n・スレッド（軽量・メモリ共有）\n・マルチスレッド\n・タスク", "analogy": "「会社におけるプロジェクトと社員」です。\nジョブは『新商品開発（全体）』、プロセスは『営業部や開発部（部署ごとの部屋）』、スレッドは『部屋の中で動く個々の社員（作業員）』です。", "details": "OSにおける処理の段階的単位。\n・ジョブ：ユーザーから見たひとまとまりの作業。\n・プロセス：OSがメモリやリソースを割り当てる独立した実行単位。\n・スレッド：プロセス内でCPU時間を割り当てる最小の実行単位。", "etymology": "Job / Process / Thread（細い糸、連続した処理）。", "exam": "基本情報・応用情報の定番問題！「メモリ空間を共有し、文脈切替（コンテキストスイッチ）のオーバーヘッドが最も小さい実行単位はどれか（答え：スレッド）」が出ます。", "def30": "利用者単位(ジョブ)、メモリ単位(プロセス)、CPU割り当て最小単位(スレッド)。（41文字）"}, {"id": 13, "term": "UNIX・Linux", "summary": "・オープンで移植性の高いマルチユーザー・マルチタスクOS。\n・LinuxはUNIX互換のオープンソースOSで、サーバーや組み込みで広く採用。", "keywords": "・UNIX\n・Linux\n・オープンソース\n・カーネル\n・シェル\n・POSIX\n・ディストリビューション", "analogy": "「パソコンやサーバーを動かす本格派の土台OS」です。\nWindowsやMacの親戚のような存在で、世界中のWebサーバーやスーパーコンピュータの大部分を支えています。", "details": "POSIX規格に準拠したマルチユーザー・マルチタスクの基本OS。Linuxはリーナス・トーバルズ氏が開発したUNIX互換のカーネルであり、サーバーやAndroid等に広く利用されている。", "etymology": "UNIX（ユニックス） / Linux（Linus's UNIX）。", "exam": "OSの基礎知識。「マルチユーザー・マルチタスクである」「カーネル（核心）とシェル（命令解釈）から構成される」「LinuxはGPLライセンスで配布されている」がポイントです。", "def30": "マルチユーザー対応の基本OS。LinuxはUNIX互換のOSS。（32文字）"}, {"id": 14, "term": "ディストリビュータ", "summary": "・Linuxカーネルに、基本コマンド、シェル、アプリケーション、パッケージ管理ツール等を組み合わせて扱いやすい「配布パッケージ」として提供する企業・団体。", "keywords": "・Linuxディストリビューション\n・Red Hat\n・Ubuntu\n・Debian\n・パッケージ管理（yum/apt）\n・カーネル＋周辺ツール", "analogy": "「ハウスメーカーの建売住宅」です。\n単体では住めない土台（Linuxカーネル）に、壁や家具・電気（基本ソフトや便利ツール）をセットにして『Ubuntu』や『Red Hat』として売り出す会社です。", "details": "オープンソースのLinuxカーネルを中心に、ライブラリ、各種コマンド、インストーラ、パッケージ管理システム等をまとめ、一つのOSとして利用できるようにパッケージ化（ディストリビューション）して提供する事業者。", "etymology": "Distributor（配布者、販売代理店）。", "exam": "OS・Linux分野で出題。「Linuxカーネルに各種ツールやインストーラを組み合わせて配布する提供者＝ディストリビュータ（Red HatやCanonical等）」。", "def30": "Linuxカーネルと各種ツールを組み合わせてOSパッケージとして提供する事業者。（40文字）"}, {"id": 15, "term": "マイクロカーネルアーキテクチャ", "summary": "・OSのカーネル機能を「メモリ管理やプロセス間通信などの最小限」に絞り、他をユーザー空間で動かす設計。\n・モノリシックカーネルより安全性が高い。", "keywords": "・最小限の機能\n・ユーザー空間\n・プロセス間通信\n・モノリシックカーネル（Linux等）との対比\n・障害局所化", "analogy": "「必要最低限のスタッフしかいない司令部」です。\n司令部（カーネル）は連絡係（通信）だけを担当し、ファイルの管理などは外部の専門部署（ユーザー空間）に任せることで、一部が倒れても司令部は無事です。", "details": "OSのコアであるカーネルに、メモリ管理、スレッド管理、IPC（プロセス間通信）等の最小限機能のみを搭載する設計。ファイルシステムやデバイスドライバをユーザーモードで動作させ耐障害性を高める。", "etymology": "Micro（極小の） Kernel（カーネル・核心）。", "exam": "OSの構造問題で出題。「カーネル機能を最小限にして安全性を高める＝マイクロカーネル（MacのMach等）」「全機能をカーネル空間に持つ＝モノリシックカーネル（Linux等）」の違い。", "def30": "カーネル機能を最小限に抑え、耐障害性と拡張性を高めたOS構造。（31文字）"}, {"id": 16, "term": "CMOS", "summary": "・P型とN型のMOS FETを組み合わせた半導体素子構造。\n・消費電力が極めて小さく、PCのBIOS設定値（時計や構成情報）をバックアップ保持するメモリ部分にも使われる。", "keywords": "・相補型金属酸化膜半導体\n・低消費電力\n・BIOS設定保持\n・ボタン電池\n・半導体素子", "analogy": "「PCの内部時計と設定を保存する小さなメモリ」です。\nパソコンのコンセントを抜いても時計や起動設定が消えないのは、ボタン電池から極小の電力（CMOS）でデータを守っているからです。", "details": "・CMOS (Complementary Metal Oxide Semiconductor)：消費電力が非常に少ない半導体回路の構造。\n・PCにおいては、マザーボード上で時刻やBIOSの設定情報を保存している不揮発的運用メモリ（ボタン電池でバックアップ）を指す用語としても使われる。", "etymology": "Complementary Metal Oxide Semiconductor（相補型MOS）。", "exam": "ハードウェア分野で出題。「消費電力が小さく、PCの時計やBIOS設定情報を保持する半導体記憶領域＝CMOS」。", "def30": "消費電力が非常に小さく、PCの時計やBIOS設定情報を保持する半導体。（35文字）"}, {"id": 17, "term": "シリアルATA / ATAPI", "summary": "・PCとHDD/SSDや光学ドライブを接続するストレージ通信規格。\n・SATAはシリアル転送で高速・薄いケーブル、ATAPIはCD/DVD用拡張規格。", "keywords": "・SATA（シリアル転送）\n・PATA（パラレル転送）\n・AHCI\n・NVMe\n・ATAPI（CD/DVD用拡張）", "analogy": "「1車線の高速道路（SATA）」です。\n昔の太いリボンケーブル（PATA・多車線）は信号のズレ調整が大変でしたが、1車線（シリアル）でクロックを爆上げした方が圧倒的に速くなりました。", "details": "・SATA (Serial ATA)：データ信号を1本（シリアル）で高速転送するディスク接続規格。熱や配線の問題を解決した。\n・ATAPI：旧ATA規格にCD-ROM等の光学ドライブを接続できるよう拡張した規格。", "etymology": "Serial Advanced Technology Attachment (SATA) / ATA Packet Interface (ATAPI)。", "exam": "ハードウェア規格で出題。「シリアル転送方式を採用し、従来のパラレルATAより高速化したストレージ規格＝SATA」を押さえましょう。", "def30": "HDDやSSDとPCを1本線で高速接続するシリアル転送規格。（30文字）"}, {"id": 18, "term": "耐タンパ性\n(Tamper Resistance)", "summary": "・スマートカード（ICカード）や暗号ハードウェアが、外部からの物理的解析やデータ解読に耐える性質。", "keywords": "・Tamper（不法改ざん）\n・ICカード\n・物理的解析耐性\n・サイドチャネル攻撃対策\n・環境検知での消去", "analogy": "「無理に開けようとすると自爆する金庫」です。\nICカードのチップを顕微鏡で覗こうとしたり、電圧を変化させて内部の暗号鍵を盗もうとすると、自らデータを消去してガードします。", "details": "ハードウェアの内部構造や保持している機密情報（暗号鍵等）が、外部からの物理的・電気的な解析や不当な改ざん（タンパー）に対してどれだけ耐性を持っているかを示す概念。", "etymology": "Tamper（改ざんする、いじる） ＋ Resistance（耐性）。", "exam": "情報セキュリティ・ハードウェアで出題。「ICカード等で内部の機密情報を不正解析から保護する性質＝耐タンパ性」「電圧解析などのサイドチャネル攻撃に耐える性質」が出ます。", "def30": "内部の暗号鍵等の機密情報を外部の物理的解析や改ざんから保護する性質。（34文字）"}, {"id": 19, "term": "主記憶・補助記憶装置・仮想記憶", "summary": "・記憶装置の階層構造。\n・主記憶（CPUが直接アクセス・高速・揮発性）、補助記憶（HDD/SSD・大容量・非揮発性）、仮想記憶（補助記憶で主記憶を擬似拡大）。", "keywords": "・主記憶（RAM/揮発性）\n・補助記憶（SSD/HDD/非揮発性）\n・仮想記憶\n・記憶階層\n・レジスタ", "analogy": "「学習机の引き出し構造」です。\n主記憶＝「机の上の広さ（作業スペース）」\n補助記憶＝「引き出しの本棚（保管場所）」\n仮想記憶＝「本棚の一部を机の延長として使う仕組み」", "details": "・主記憶：CPUが直接プログラムを読み書きする高速なメモリ（RAM）。\n・補助記憶：データを永続保持するストレージ（HDD, SSD）。\n・仮想記憶：主記憶不足時、補助記憶の一部をアドレス空間として活用する技術。", "etymology": "Main Memory / Auxiliary Storage / Virtual Memory。", "exam": "計算機基本構造で出題。「CPUが直接参照できるのは主記憶（メモリ）のみ」「補助記憶のプログラムは一度主記憶に読み込んでから実行する」という基本原則が問われます。", "def30": "CPUが直接アクセスする主記憶と、永続保持する補助記憶と仮想記憶の階層。（36文字）"}, {"id": 20, "term": "セグメンテーション方式・ページング方式", "summary": "・主記憶の仮想記憶管理方式。\n・ページングは固定長（ページ）で分割し、セグメンテーションはプログラムの論理構造（可変長）で分割する。", "keywords": "・ページング（固定長・ページフォールト）\n・セグメンテーション（可変長・論理構造）\n・仮想記憶\n・アドレス変換", "analogy": "「ノートの区切り方」です。\nページング＝「マス目の決まった方眼紙（固定長）」で機械的に区切る。\nセグメンテーション＝「章や節の切れ目（可変長）」で内容ごとに区切る。", "details": "仮想記憶におけるメモリ割り当て方式。\n・ページング方式：メモリを固定長（4KB等）の領域（ページ）に分割して管理。外部フラグメンテーションが起きない。\n・セグメンテーション方式：プログラムやデータを論理的な可変長の単位（セグメント）に分割して管理。", "etymology": "Paging / Segmentation（区画・線引き）。", "exam": "OSのメモリ管理で超頻出！「固定長に分割しページフォールトが発生する＝ページング」「可変長に論理分割する＝セグメンテーション」の違いが問われます。", "def30": "主記憶を固定長で管理するページングと可変長で管理する方式。（29文字）"}, {"id": 21, "term": "スラッシング\n(Thrashing)", "summary": "・仮想メモリ環境で主記憶容量が不足し、ページイン/ページアウト（ページ換装）が多発して処理が極端に遅くなる現象。\n・対策は「主記憶（メモリ）を増設する」こと。", "keywords": "・仮想メモリ\n・ページフォールト\n・ページチェンジ多発\n・主記憶容量不足\n・オーバヘッド", "analogy": "「狭い机で勉強していて、テキストの出し入ればかりして勉強が進まない状態」です。\n机（主記憶）が狭すぎて本棚（仮想記憶）と本を何度も入れ替える作業に追われ、本来の勉強（CPU処理）が完全にストップしてしまいます。", "details": "仮想記憶システムにおいて、主記憶容量が不足しているためにページの置換（ページイン/ページアウト）が頻発し、CPUがその処理に追われてシステムの処理能力が著しく低下する現象。", "etymology": "Thrash（激しく動かす、のたうち回る）。\nページを激しく出し入れしすぎて、システムがのたうち回って動かなくなっている状態を表す。", "exam": "OS・オペレーティングシステムの分野で出題。\n「仮想記憶でページフォールトが頻発し、システム性能が著しく低下する現象は何か」と問われます。根本対策として「主記憶容量を増やす」ことを選ばせる問題も多いです。", "def30": "主記憶不足によりページの出し入れが多発し処理が激減する現象。（30文字）"}, {"id": 22, "term": "スワッピング", "summary": "・主記憶（メモリ）容量が不足した際、優先度の低いプロセスをまるごと補助記憶（ディスク）に退避（スワップアウト）させて主記憶を開ける仕組み。", "keywords": "・スワップイン / スワップアウト\n・プロセス単位の退避\n・主記憶領域確保\n・ページングとの違い（プロセス全体）", "analogy": "「狭い部屋での作業員の退避」です。\n作業部屋（メモリ）が人（プロセス）でいっぱいになったら、一度休憩室（ディスク）に丸ごと移動してもらい（スワップアウト）、自分の順番が来たら部屋に戻します（スワップイン）。", "details": "OSのメモリ管理機能の一つ。主記憶領域が不足した場合、実行中断中などの優先度の低いプロセス全体を一時的に補助記憶装置（スワップ領域）に退避させ（スワップアウト）、必要な時に戻す（スワップイン）処理。", "etymology": "Swapping（交換すること）。プロセスとディスク領域の交換のイメージ。", "exam": "メモリ管理で出題。「主記憶と補助記憶間で【ページ単位】で出し入れする＝ページング」「【プロセス全体】を丸ごと出し入れする＝スワッピング」の違いをしっかり区別！", "def30": "主記憶不足時にプロセス単位で補助記憶へ退避(アウト)・復元(イン)する処理。（38文字）"}, {"id": 23, "term": "オーバーヘッド", "summary": "・システムの目的処理そのものではなく、管理や制御・準備のために余分にかかる時間や負荷・処理量のこと。", "keywords": "・システム制御負荷\n・タスク切り替え（コンテキストスイッチ）\n・通信ヘッダー\n・余分なコスト", "analogy": "「会議の前の会場設営時間」です。\n本題の話し合い（主処理）をするために、机の移動やマイク設定（オーバーヘッド）に15分消費してしまうような余計な手間のことです。", "details": "コンピュータで特定の処理を行う際、その本質的な処理以外に付随して発生する間接的な負荷や時間、メモリ消費のこと。OSのコンテキストスイッチや通信のヘッダー付与などが該当する。", "etymology": "Overhead（頭上の経費、諸経費）。", "exam": "IT全般で使われる重要単語。「コンテキストスイッチのオーバーヘッド」「プロトコルのオーバーヘッド」など、「管理・制御のための余分なコスト」という意味で出題されます。", "def30": "本来の処理以外にシステムの管理や制御のために消費される付加的負荷。（33文字）"}, {"id": 24, "term": "バッファキャッシュ", "summary": "・OSがディスク（ストレージ）と主記憶の間のアクセス速度差を埋めるため、主記憶上に作成する読み書きデータの一時保管（キャッシュ）領域。", "keywords": "・主記憶領域\n・ディスクI/O削減\n・遅延書き込み（ライトバック）\n・キャッシュヒット\n・アクセス高速化", "analogy": "「デスクの端に置いた一時書類置き場」です。\n頻繁に使うファイルを毎回遠くのファイル保管庫（HDD）まで取りに行かず、デスク（メモリ）の上に一時保存して超高速に取り出します。", "details": "OSのカーネルがハードディスク等のストレージデバイスに対する入出力（I/O）パフォーマンスを向上させるため、主記憶（RAM）の一部を利用してディスク上のデータを一時的に保持するキャッシュ領域。", "etymology": "Buffer（緩衝領域） ＋ Cache（一時保管庫）。", "exam": "OSの性能向上機能で出題。「ディスクI/O（読み書き）を減らしパフォーマンスを向上させるため、主記憶上に設けるデータ一時保管領域＝バッファキャッシュ」。", "def30": "ストレージの読み書き速度差を緩和するため主記憶上に置くデータ一時保管領域。（37文字）"}, {"id": 25, "term": "ウェアレベリング\n(Wear Leveling)", "summary": "・SSDやフラッシュメモリにおいて、特定ブロックの書き換え集中を防ぎ、全ブロックの書き換え回数を均等化して寿命を延ばす技術。", "keywords": "・フラッシュメモリ\n・SSD\n・書き換え寿命（P/Eサイクル）\n・ブロック平滑化\n・コントローラ制御", "analogy": "「靴の底を均等に使う工夫」です。\nかかとばかり使っているとすぐ靴がダメになるので、足全体を均等に使って長持ちさせる（書き込み場所を均等にする）仕組みです。", "details": "フラッシュメモリ（SSD等）の消去・書き込み回数に制限がある特性に対応するため、コントローラがデータの書き込み位置を分散させ、特定の物理ブロックだけが劣化するのを防ぐ平滑化技術。", "etymology": "Wear（磨耗、劣化） ＋ Leveling（平坦化する）。", "exam": "ストレージ分野で出題。「SSD等のフラッシュメモリで、特定のブロックに書き込みが集中しないよう分散させて寿命を延ばす技術＝ウェアレベリング」が正解。", "def30": "SSD等の書き換え回数を均等化し、特定ブロックの劣化を防ぎ長寿命化する技術。（38文字）"}, {"id": 26, "term": "ファイル領域割り当て方式", "summary": "・OSがディスク（ストレージ）にファイルを保存する際の領域管理法。\n・連続割り当て、不連続（リスト・FAT）割り当て、インデックス割り当て等がある。", "keywords": "・FAT（ファイル割り当て表）\n・iノード\n・連続割り当て\n・インデックス割り当て\n・フラグメンテーション", "analogy": "「本棚の本の置き方」です。\n連続＝本を順番に並べて置く（早いけど隙間ができる）。リスト＝バラバラに置いて『次の巻は〇〇棚にある』と紙に書く（無駄がない）。", "details": "ファイルシステムがストレージ上のセクタ/クラスタをファイルに割り当てる手法。\n・連続割当：高速だが空き領域の断片化が起きる。\n・鎖（リスト）割当：FAT等で次領域のポインタを保持。\n・インデックス割当：UNIXのiノード等で全ブロックアドレスを一括管理する。", "etymology": "File Allocation Method（ファイル領域割り当て）。", "exam": "ファイルシステム分野で出題。「UNIXで用いられる、ファイル属性やデータブロックのアドレスをインデックス保持する仕組み＝iノード（インデックス割当）」。", "def30": "ストレージ上でファイルデータを保存するクラスタ領域の管理・割り当て手法。（36文字）"}, {"id": 27, "term": "LANの制御方式\n(CSMA/CD・CSMA/CA)", "summary": "・有線/無線LANで複数の端末が同じ通信媒体を共有する際のアクセス制御方式。\n・CSMA/CD（有線・衝突検知）、CSMA/CA（無線・衝突回避）。", "keywords": "・CSMA/CD（有線LAN/衝突検出・ランダム時間再送）\n・CSMA/CA（無線LAN/ACK確認・衝突回避/キャリアセンス）\n・IEEE 802.3/802.11", "analogy": "「話し合いのルール」です。\n・CD（有線）：同時に喋って声がぶつかったら（衝突）、一度黙ってランダムな時間待ってから話す。\n・CA（無線）：誰かが喋っていないか確認し、誰もいなければ『喋ります』と宣言してから話す（回避）。", "details": "・CSMA/CD：有線LAN（IEEE 802.3）のアクセス制御。搬送波を感知し、送信中の衝突（Collision）を検知すると破棄し、ランダム時間待機後に再送する。\n・CSMA/CA：無線LAN（IEEE 802.11）のアクセス制御。送信前に一定時間搬送波の非検知を確認し、衝突を予防的に回避する。", "etymology": "Carrier Sense Multiple Access with Collision Detection / Collision Avoidance。", "exam": "ネットワーク層の超頻出基礎知識！「有線LANで衝突を検知してランダム時間待機＝CSMA/CD」「無線LANで電波の衝突を回避＝CSMA/CA」は必須です。", "def30": "有線LANでの衝突検知(CD)と、無線LANでの衝突回避(CA)によるアクセス制御。（42文字）"}, {"id": 28, "term": "TDMA方式\n(時分割多重接続)", "summary": "・同じ周波数帯の電波を極めて短い「時間（タイムスロット）」で細かく分割し、複数の端末で交互に通信を行う無線多重化方式。", "keywords": "・時分割多重\n・タイムスロット\n・FDMA（周波数分割）\n・CDMA（符号分割）\n・携帯電話通信規格", "analogy": "「マイクの持ち回りトーク」です。\n同じマイク（周波数）を、0.1秒ずつ順番に「Aさん→Bさん→Cさん」と超高速で交代して使うことで、全員が同時に話しているように見せます。", "details": "同一周波数の通信回線を非常に短い時間単位（タイムスロット）に分割し、複数の通信チャネルに割り当てることで、1つの周波数で複数端末の同時通信を実現するマルチアクセス方式。", "etymology": "Time Division Multiple Access（時間分割多元接続）。", "exam": "通信方式で出題。「同一周波数を時間軸で分割して複数の通信を多重化する＝TDMA」「周波数を分けて多重化する＝FDMA」「符号（コード）で分ける＝CDMA」の違い。", "def30": "同一周波数の通信回線を極小の時間単位に分割して複数通信を行う多元接続方式。（37文字）"}, {"id": 29, "term": "パケット交換方式 vs ATM交換方式", "summary": "・通信データの伝送方式。\n・パケット交換はデータを可変長の小包（パケット）に分けて送る。\n・ATM方式は53バイトの固定長セル（セル交換）で送る。", "keywords": "・パケット交換（可変長・ヘッダー付加）\n・ATM交換（53バイト固定長セル・QoS保証）\n・回線交換との対比", "analogy": "「手紙（パケット）」と「同じ大きさのコインロッカー（ATM）」です。\nパケットは好きな長さの手紙で送り、ATM方式は全データをぴったり53バイトの小箱（セル）に切り揃えて爆速で流します。", "details": "・パケット交換：データを可変長のパケットに分割し、宛先アドレスを付けてネットワークに流す方式（現在のIPの主流）。\n・ATM方式 (Asynchronous Transfer Mode)：53バイト（ヘッダー5＋データ48）の固定長「セル」を用いて高速交換を行う通信方式。", "etymology": "Packet Switching / Asynchronous Transfer Mode（非同期転送モード）。", "exam": "通信方式の分類で出題。「データを53バイトの固定長セルに分割して送る＝ATM（セル交換）方式」「可変長パケットを送る＝パケット交換」という相違点。", "def30": "可変長パケットを送る方式と、53バイト固定長セルで送るATM方式の比較。（36文字）"}, {"id": 30, "term": "MACアドレス・IPアドレス・ポート番号", "summary": "・通信の宛先を示す3要素。\n・MACは「隣の機器」、IPは「最終目的地」、ポート番号は「どのアプリか」を示す。", "keywords": "・MACアドレス（物理/第2層）\n・IPアドレス（論理/第3層）\n・ポート番号（アプリ識別/第4層）\n・ウェルノウンポート（80/443等）", "analogy": "「マンションへの配達」です。\nIPアドレスが「マンションの住所」、MACアドレスが「道案内の標識」、ポート番号が「何号室（どのアプリ）の人か」を表します。", "details": "・MAC：NIC（LANカード）に固有の物理アドレス（隣接機器の特定）。\n・IP：ネットワーク上の論理アドレス（最終目的地の特定）。\n・ポート：TCP/UDP通信でアプリケーションを識別する番号。", "etymology": "Media Access Control / Internet Protocol / Port（港、出入り口）。", "exam": "OSI参照モデルとの階層対応が頻出。MAC=L2、IP=L3、ポート=L4。また、HTTPは80、HTTPSは443といったウェルノウンポート番号も問われます。", "def30": "通信において、物理機器・最終目的地・アプリを特定する3つの番号。（32文字）"}, {"id": 31, "term": "イーサネット", "summary": "・世界中で最も広く普及している、有線LANの通信規格（IEEE 802.3）。\n・物理的なケーブルの規格や、MACアドレスを使った通信手順を定めている。", "keywords": "・LANの標準規格\n・IEEE 802.3\n・MACアドレス\n・CSMA/CD方式", "analogy": "Wi-Fiが「無線のルール」なら、イーサネットは「有線のルール」。みんながこのルール（IEEE 802.3）を守っているから、違うメーカーのPCとルーターでもLANケーブルを挿すだけで繋がります。", "details": "オフィスや家庭などのLAN（構内情報通信網）で最も普及している有線通信の標準規格。\nOSI基本参照モデルの第1層（物理層）と第2層（データリンク層）の仕様を定め、MACアドレスを使った通信方法を規定している。", "etymology": "Ether（エーテル：昔、光を伝達すると考えられていた架空の物質）＋ net（ネットワーク）。\n「どこにでも存在してデータを伝えてくれる網」という意味合い。", "exam": "ネットワーク分野の基礎として出題。\n規格名である「IEEE 802.3」が頻出。初期のアクセス制御方式「CSMA/CD方式（衝突検知）」と関連付けて問われることが多い。", "def30": "MACアドレスを用いて通信する、最も普及している有線LAN規格。（32文字）"}, {"id": 32, "term": "ARP / RARP", "summary": "・IPアドレスとMACアドレスを相互変換するプロトコル。\n・IPからMACを特定する手法と、機器固有のMACからIPを取得する逆引き手法がある。", "keywords": "・ARP（IP→MAC）\n・RARP（MAC→IP）\n・ブロードキャストで問い合わせ\n・ARPキャッシュ", "analogy": "「電話帳検索と逆引き」です。\nARPは「名前（IP）は分かるけど、電話番号（MAC）教えて！」と周囲に大声（ブロードキャスト）で聞く仕組みです。RARPはその逆です。", "details": "・ARP (Address Resolution Protocol)：通信相手のIPアドレスから、物理的なMACアドレスを解決（取得）するプロトコル。\n・RARP (Reverse ARP)：機器固有のMACアドレスから自身のIPアドレスを取得するプロトコル。", "etymology": "Address Resolution Protocol（アドレス解決プロトコル）。", "exam": "午前問題で超頻出。「IPアドレスからMACアドレスを求めるプロトコルはどれか」というシンプルな問いが出ます。A（IP→MAC）とR（Reverse/逆）を区別しましょう。", "def30": "IPアドレスからMACアドレスを（RARPはその逆を）取得する規格。（34文字）"}, {"id": 33, "term": "DHCP", "summary": "・PCやスマホがネットワークに繋がった際、IPアドレスなどの設定を自動的に割り当てるプロトコル。\n・手動設定の手間を省く。", "keywords": "・IPアドレスの自動割り当て\n・サブネットマスク\n・デフォルトゲートウェイ\n・UDPポート", "analogy": "「ホテルのルームキー自動発券機」です。\nホテル（ネットワーク）に入ったお客さん（PC）に、空いている部屋番号（IPアドレス）を自動的に貸し出してくれます。", "details": "ネットワークに接続するノードに対し、IPアドレス、サブネットマスク、デフォルトゲートウェイ、DNSサーバーのIPアドレスなどの情報を動的かつ自動的に割り当てるプロトコル。", "etymology": "Dynamic Host Configuration Protocol（動的ホスト設定プロトコル）。", "exam": "ネットワーク分野で頻出。「IPアドレスを動的に割り当てる」「設定の手間を省き管理を容易にする」という役割が問われます。", "def30": "PC接続時にIPアドレス等の通信設定を自動で割り当てるプロトコル。（33文字）"}, {"id": 34, "term": "DNS\n(Domain Name System)", "summary": "・ドメイン名（URL等）とIPアドレス（数値）を相互に変換（名前解決）するシステム。\n・偽のIPを覚え込ませる攻撃（キャッシュポイズニング）やその対策も頻出。", "keywords": "・名前解決\n・ドメイン名\n・IPアドレス\n・UDP/53\n・DNSキャッシュポイズニング", "analogy": "「インターネットの電話帳（アドレス帳）」です。\n「google.com」という人間がわかりやすい名前（ドメイン）を、コンピュータが理解できる「142.250.xxx.xxx」という電話番号（IPアドレス）に変換して接続してくれます。", "details": "インターネット上で、人間が理解しやすいドメイン名（例: example.com）と、コンピュータが識別するIPアドレス（例: 192.0.2.1）を対応付ける（名前解決する）システム。", "etymology": "Domain Name（領域の名前）＋ System（仕組み）。\nインターネット上の区画（ドメイン）の名前を統一管理する仕組みのこと。", "exam": "ネットワーク分野およびセキュリティ分野で超頻出。\n「名前解決」というキーワードが出たらDNS。また、嘘のIPアドレスを覚え込ませる「DNSキャッシュポイズニング攻撃」やその対策「DNSSEC」も頻出です。", "def30": "ドメイン名とIPアドレスを相互に変換する名前解決システム。（29文字）"}, {"id": 35, "term": "ダイナミックDNS\n(DDNS)", "summary": "・プロバイダ等から動的（ダイナミック）に割り当て直されるIPアドレスが変わっても、ドメイン名との対応付けを自動更新して維持するサービス。", "keywords": "・動的IPアドレス\n・ドメイン名固定\n・自宅サーバー公開\n・IP変更追従\n・名前解決更新", "analogy": "「転居届の自動提出サービス」です。\n家の住所（IPアドレス）がコロコロ変わっても、郵便局（DDNS）に自動で連絡がいき、「〇〇さんの家」という名前でいつでも手紙が届くようにします。", "details": "家庭用ブロードバンド等でIPアドレスが定期的に変更される環境において、IPアドレスの変更を検知してDNSサーバーのレコードを動的に自動更新し、常に固定のドメイン名でアクセスを可能にする仕組み。", "etymology": "Dynamic Domain Name System（動的なDNS）。", "exam": "ネットワークで出題。「動的に割り振られる可変IPアドレス環境において、ドメイン名によるアクセスを可能にするサービス＝ダイナミックDNS（DDNS）」。", "def30": "IPアドレスが変化しても固定のドメイン名でアクセスできるよう更新する技術。（37文字）"}, {"id": 36, "term": "ルーティングプロトコル\n(OSPF / BGP)", "summary": "・ルータ同士が経路情報を交換し、最適な通信ルートを決定する通信手順。\n・内部向け（IGP）のOSPFやRIP、外部向け（EGP）のBGPがある。", "keywords": "・経路制御\n・ダイナミックルーティング\n・RIP（ディスタンスベクタ）\n・OSPF（リンクステート）\n・BGP（パスベクタ/AS間）", "analogy": "「カーナビの渋滞情報共有」です。\nルータたちが「こっちの道は混んでるぞ」「こっちは最短だ」という情報をお互いに教え合い、常に最速のルートを計算します。", "details": "パケットを目的地に届けるための経路情報（ルーティングテーブル）を、ルータ間で動的に交換・更新するプロトコル。OSPFはリンクの状態（帯域幅等）を基に最短経路を計算する。", "etymology": "Routing Protocol。経路（Route）を決める手順。", "exam": "ネットワーク層の頻出項目。プロトコルの分類が問われます。組織内の経路制御＝「RIP」「OSPF」。インターネット上の組織間（AS間）の経路制御＝「BGP」。", "def30": "ルータ間で経路情報を交換し、宛先への最適な通信ルートを決める手順。（33文字）"}, {"id": 37, "term": "VRRP", "summary": "・ネットワークのデフォルトゲートウェイ（ルータ）を冗長化し、主系ルータの故障時に自動で待機系へ切り替える（仮想IPを継承する）プロトコル。", "keywords": "・デフォルトゲートウェイ冗長化\n・仮想IPアドレス\n・仮想MACアドレス\n・マスターとバックアップ\n・フェイルオーバー", "analogy": "「ルータの影武者（替え玉）システム」です。\n普段は本物（マスター）が『192.168.1.1（仮想IP）』として働きますが、倒れた瞬間、影武者（バックアップ）がその看板をそのまま引き継いで仕事を継続します。", "details": "ルータを冗長化するための標準プロトコル。複数の物理ルータで1つの「仮想ルータ（仮想IP・仮想MAC）」を共有し、通常稼働するマスター障害時にバックアップルータが自動的に仮想IPを引き継いで通信障害を防ぐ。", "etymology": "Virtual Router Redundancy Protocol（仮想ルータ冗長化プロトコル）。", "exam": "ネットワーク冗長化で超頻出！「デフォルトゲートウェイを冗長化し、仮想IPアドレスを引き継ぐことでダウンを防ぐプロトコル＝VRRP」が正解キーワード。", "def30": "デフォルトゲートウェイのルータを冗長化し仮想IPを引き継ぎ自動切替する規格。（38文字）"}, {"id": 38, "term": "RSVP\n(リソース予約プロトコル)", "summary": "・ネットワーク上でIP電話や動画などのQoS（通信品質）を確保するため、通信経路上のルータに対して帯域予約を行うプロトコル。", "keywords": "・QoS（サービス品質）保証\n・帯域予約\n・リアルタイム通信\n・インテグレーテッドサービス（IntServ）", "analogy": "「道路の優先レーン予約」です。\n救急車（リアルタイム通信）が通る前に、経路上の交差点（ルータ）に「これから通るから、帯域（レーン）を1本空けておいて！」とあらかじめ予約します。", "details": "IPネットワークにおいて、音声や動画などのリアルタイム通信の品質（QoS）を保証するため、送信元から宛先までの経路上の各ルータに対し、必要な帯域幅や遅延上限などのネットワーク資源（リソース）をあらかじめ予約するプロトコル。", "etymology": "Resource Reservation Protocol（リソース予約プロトコル）。", "exam": "ネットワーク層・QoS技術で出題。「リアルタイム通信の帯域幅をあらかじめルータに予約して品質（QoS）を保つプロトコル＝RSVP」がポイント。", "def30": "リアルタイム通信のために経路上のルータへ帯域幅をあらかじめ予約する規格。（36文字）"}, {"id": 39, "term": "PPP\n(Point-to-Point Protocol)", "summary": "・電話回線やシリアル線など、2点間（1対1）を接続してデータ通信を行うためのデータリンク層（L2）プロトコル。\n・認証（PAP/CHAP）や暗号化機能を持つ。", "keywords": "・2点間直結\n・データリンク層（L2）\n・CHAP/PAP（認証）\n・PPPoE（イーサネット上でのPPP）\n・ダイヤルアップ接続", "analogy": "「1対1の専用の電話線」です。\n1本の通信線で向こう側のサーバーと私を直接繋ぎ、「ユーザー名とパスワード（CHAP）」を確かめてから通信を開始します。", "details": "Point-to-Point（1対1）の通信線上でパケットを転送するためのプロトコル。認証機能（PAP/CHAP）や圧縮機能を持つ。LAN（イーサネット）上でPPPを実現した規格がPPPoE。", "etymology": "Point-to-Point Protocol（点と点を繋ぐプロトコル）。", "exam": "ネットワーク層の基礎問題。「1対1の通信接続を行い、CHAPなどの認証手順を持つデータリンク層プロトコル＝PPP」「これを有線LAN上で動作させる＝PPPoE」。", "def30": "1対1の通信線上で認証や暗号化を行い通信を接続するデータリンク層プロトコル。（38文字）"}, {"id": 40, "term": "SNMP", "summary": "・ネットワーク上の機器（ルータ、スイッチ、サーバー等）の動作状態やトラフィック情報を、遠隔から監視・制御するためのUDPプロトコル。", "keywords": "・マネージャとエージェント\n・MIB（管理情報データベース）\n・UDP 161/162\n・トラフィック監視\n・ネットワーク管理", "analogy": "「校内放送と学級委員」です。\n職員室の先生（マネージャ）が各クラスの委員（エージェント）に「欠席者は何人か？（MIB）」と尋ね、機器の状態を一括で集めます。", "details": "アプリケーション層（L7）で動作するネットワーク管理プロトコル。管理側（SNMPマネージャ）が、被管理機器に常駐するプログラム（SNMPエージェント）と通信し、「MIB」と呼ばれる管理情報を収集・設定する。", "etymology": "Simple Network Management Protocol（簡単なネットワーク管理プロトコル）。", "exam": "ネットワーク管理分野で超超頻出！「ネットワーク機器の状態やトラフィックを遠隔監視するプロトコル＝SNMP」「機器側の保持する管理情報データベース＝MIB」という組み合わせが出ます。", "def30": "ネットワーク機器の稼働状態や管理情報(MIB)を遠隔で収集・監視するプロトコル。（40文字）"}, {"id": 41, "term": "POP3・APOP・POP3S", "summary": "・メールサーバーから自分の端末に電子メールをダウンロードして受信するプロトコル群。\n・APOPはパスワードを暗号化、POP3Sは通信全体をSSL/TLSで暗号化。", "keywords": "・メール受信プロトコル\n・メールダウンロード\n・Port 110 (POP3) / Port 995 (POP3S)\n・通信暗号化\n・APOP（パスワードのみ暗号化）", "analogy": "「郵便ポストからの手紙受取り」です。\nPOP3＝鍵なしポストから受け取る（平文）。APOP＝合言葉だけ暗号化して受け取る。POP3S＝鍵付きの防犯トランクに入れて受け取る（全体暗号化）。", "details": "電子メールを受信するプロトコル。\n・POP3：ポート110を利用。パスワードや本文が平文で流れる。\n・APOP：チャレンジレスポンスを用いて認証時のパスワードのみを暗号化する。\n・POP3S：ポート995を利用。SSL/TLSを用いて認証からメール本文まで通信全体を暗号化する。", "etymology": "Post Office Protocol Version 3 / Authenticated POP / POP3 over TLS/SSL。", "exam": "ネットワーク・セキュリティで頻出！「POP3は平文」「APOPはパスワードのみ暗号化」「POP3S（ポート995）は通信全体をSSL/TLSで暗号化する」の違いが問われます。", "def30": "メールを受信する規格。パスワード暗号化のAPOPと全体暗号化のPOP3Sがある。（40文字）"}, {"id": 42, "term": "IMAP4・IMAPS", "summary": "・メールを端末に落とさず、メールサーバー上で管理・閲覧する受信プロトコル。\n・複数端末で状態（既読等）を同期できる。IMAPSはSSL/TLSで暗号化。", "keywords": "・サーバー上でのメール管理\n・複数端末同期（スマホ/PC）\n・Port 143 (IMAP4) / Port 993 (IMAPS)\n・既読状態同期", "analogy": "「Web上のメールボックス」です。\nPOP3のように手元のPCに手紙を持ち帰るのではなく、サーバーの私書箱（IMAP）を開いて閲覧するため、スマホでもPCでも同じ状態で読めます。", "details": "メールサーバー上の電子メールを閲覧・管理するプロトコル。ローカルにメールをダウンロードするPOP3と異なり、サーバー上でフォルダ分けや既読状態が保持されるため複数端末での利用に適す。IMAPS（ポート993）はSSL/TLSで通信を保護。", "etymology": "Internet Message Access Protocol Version 4 / IMAP4 over TLS/SSL。", "exam": "POP3との比較で頻出！「メールを端末にダウンロードせずサーバー上で一元管理し、複数端末で既読等の状態を同期する＝IMAP4」「ポート993で通信全体を暗号化＝IMAPS」。", "def30": "メールをサーバー上で閲覧・一元管理し、複数端末で状態を同期する受信規格。（36文字）"}, {"id": 43, "term": "MIME / S/MIME", "summary": "・電子メールでテキスト以外の画像・音声・添付ファイルを扱う拡張規格。\n・公開鍵暗号とデジタル署名を組み合わせ、メールの暗号化と改ざん防止を行う。", "keywords": "・電子メール拡張\n・添付ファイル対応（MIME）\n・電子メールの暗号化・デジタル署名（S/MIME）\n・改ざん防止\n・送信者認証", "analogy": "「手紙に写真を同封するルール（MIME）」と「その封筒を暗号鍵と電子ハンコで保護するルール（S/MIME）」です。\nメールで安全に画像を添付して送ることができます。", "details": "・MIME (Multipurpose Internet Mail Extensions)：英数字のテキストしか送れなかった電子メールで、日本語などの多言語テキストや画像・音声等のバイナリデータを送受信できるようにした拡張規格。\n・S/MIME：MIME形式の電子メールに対し、PKI（公開鍵暗号やデジタル署名）を適用して、通信の暗号化と改ざん検知・送信者認証を実現するセキュリティ規格。", "etymology": "Multipurpose Internet Mail Extensions / Secure MIME。", "exam": "メールセキュリティで超超頻出！「メールで画像等の添付ファイルを扱う規格＝MIME」「公開鍵暗号とデジタル署名を用いてメールの暗号化と改ざん検知を行う＝S/MIME」。", "def30": "メールでの添付ファイル送信規格(MIME)と、それを暗号・署名化するS/MIME。（41文字）"}, {"id": 44, "term": "DBMS\n(データベース管理システム)", "summary": "・大量のデータを安全かつ効率的に保存・検索・更新するための管理ソフトウェア。\n・複数人での同時アクセス時の矛盾防止（排他制御）や、障害時のデータ復旧を担う。", "keywords": "・トランザクション処理\n・ACID特性\n・同時実行制御\n・排他制御\n・障害回復機能（ロールバック・ロールフォワード）", "analogy": "「超優秀な図書館の司書さん」です。\n大量の本から一瞬で目当ての本を探し出し、2人の人が同時に同じ本を借りようとしたら順番待ちをさせ（排他制御）、火事（障害）が起きてもコピーから本棚を完璧に復元してくれます。", "details": "大量のデータを安全かつ効率的に保存・検索・更新するためのソフトウェア。\n複数人での同時アクセスによる矛盾を防いだり（排他制御）、システム障害時にデータを復旧（障害回復）させたりする役割を持つ。", "etymology": "Database Management System の略。\n「大量のデータ（Database）を、矛盾なく安全に管理（Management）するシステム（System）」。", "exam": "データベース分野の全体に絡む超重要用語。\n特に、複数の処理が同時に走った際の矛盾を防ぐ「排他制御」や、処理失敗時に元の状態に戻す「ロールバック」、バックアップから復元する「ロールフォワード」などの障害回復機能がよく問われる。", "def30": "データの共有や保護、障害回復を行い、DBを管理するシステム。（30文字）"}, {"id": 45, "term": "DBMSのデーモン\n(Daemon)", "summary": "・バックグラウンドで常時待機・稼働し、データベースの監視やログ書き込み、接続要求の受付を行うバックグラウンドプロセス。", "keywords": "・バックグラウンドプロセス\n・常時稼働\n・リスナー\n・バックグラウンド処理\n・UNIX/Linux", "analogy": "「見えないところで働く裏方スタッフ」です。\n表画面には登場せず、裏側でじっと待機して、ユーザーからのアクセス受付やログの書き込みを自動で行っています。", "details": "UNIXやLinux等で、ユーザーの操作なしにバックグラウンドで常時実行されているプログラム（プロセス）。DBMSにおいては、クライアントからの接続待ち受け（リスナー）やログのディスク書き出し等を担当する。", "etymology": "Daemon（守護神、裏方精霊）。悪魔(Demon)ではなくギリシャ神話の守護霊が語源。", "exam": "OS・DB管理で出題。「OS起動時に自動開始し、バックグラウンドで要求を待機・処理する常駐プログラム＝デーモン（末尾にdが付くことが多い。例: mysqld, httpd）」。", "def30": "バックグラウンドで常時稼働し、接続要求や内部処理を担う常駐プログラム。（35文字）"}, {"id": 46, "term": "関係データベース\n(RDB)", "summary": "・データを2次元の「行（レコード）」と「列（カラム）」からなるテーブル（表）の形式で管理し、複数の表をリレーション（関係）で結びつけるデータベース。", "keywords": "・行（レコード/タプル）\n・列（属性/属性値）\n・主キー・外部キー\n・リレーション\n・SQL操作\n・主キー制約・参照整合性制約", "analogy": "「エクセルの表同士を紐付けたデータベース」です。\n『社員表』と『部署表』を、共通の『部署コード』という線（関係）で繋ぐことで、データの重複なく綺麗に管理します。", "details": "E.F.コッド氏が提唱した、データを2次元の表（リレーション）として表現するデータベース構造。行（タプル）と列（属性）で構成され、主キーや外部キーを用いて表間の関係を定義し、SQLによって柔軟なデータ操作を行う。", "etymology": "Relational Database（関係性を持つデータベース）。", "exam": "データベースの最も基本用語。「データを行と列からなる2次元の表形式で管理する＝関係データベース（RDB）」「主キーと外部キーで関係を定義する」。", "def30": "データを2次元の行と列の表形式で管理し、表同士の関連を定義するDB構造。（36文字）"}, {"id": 47, "term": "表の正規化\n（第1〜第3）", "summary": "・データの重複や更新時の矛盾を防ぐため、表を適切な単位に分割する設計手法。\n・第1は「繰り返し」、第2は「部分関数従属」、第3は「推移的関数従属」の排除。", "keywords": "・冗長性排除\n・更新異常の防止\n・第1：繰り返し排除\n・第2：部分関数従属\n・第3：推移的関数従属", "analogy": "「注文伝票」を整理するイメージ。\n第1：1マスに複数商品を入れず1行1商品にする。\n第2：キーが「注文番号＋商品番号」の時、商品番号だけで決まる商品名等を「商品表」に分ける。\n第3：顧客番号で決まる顧客名等を「顧客表」に分ける。", "details": "データの重複をなくし、更新時の矛盾を防ぐために表を分割する。\n第1：繰り返し項目をなくす\n第2：主キーの一部だけで決まる項目（部分関数従属）を別表に\n第3：主キー以外の項目で決まる項目（推移的関数従属）を別表に", "etymology": "Database Normalization（データベースの正規化）。\nNormal（正規・標準・普通）な状態にすること。データに無駄や矛盾が生じない「あるべき綺麗な形」に整えること。", "exam": "DB分野の超頻出項目。「この表を第3正規形にしたものはどれか」という表の分割問題や、「部分関数従属」「推移的関数従属」といった専門用語と第何正規形かの対応が問われる。", "def30": "データの重複や矛盾を防ぐため、表を適切な単位に分割する手法。（30文字）"}, {"id": 48, "term": "E-R図\n(実体関連図)", "summary": "・データベース設計で、対象領域の「実体（エンティティ）」と「関連（リレーションシップ）」を図示したもの。\n・概念設計の段階で作られ、主キーや「1対多」などの多重度を表現する。", "keywords": "・エンティティ（実体）\n・リレーションシップ（関連）\n・概念設計\n・多重度（1対多）\n・主キー", "analogy": "「登場人物と相関関係を図にした家系図」です。\n「顧客（実体）」と「注文（実体）」という登場人物を四角で囲み、その間を「注文する（関連）」という線で結んで、「1人の顧客は複数の注文（1対多）を持つ」と表します。", "details": "データベースの概念設計において、管理対象となるデータ（実体/エンティティ）と、データ同士の関係（関連/リレーションシップ）を図式化する手法。", "etymology": "Entity-Relationship Diagram の略。\nEntity（実体）と Relationship（関係）を示す Diagram（図）。", "exam": "データベースの設計分野で超頻出。\n「概念設計の段階で作成される」「1対多や多対多などの多重度を表す」という特徴が問われます。午後試験のデータベース選択問題では、E-R図穴埋めが必須で出ます。", "def30": "実体とデータ間の関連を図示し、DBの概念構造を表す設計図。（29文字）"}, {"id": 49, "term": "メタデータ\n(Metadata)", "summary": "・「データそのもの」ではなく、作成日時や作成者などの「データに関する属性情報」。\n・データベースではデータディクショナリに格納され、検索や管理を効率化する。", "keywords": "・データに関するデータ\n・属性情報\n・データディクショナリ\n・スキーマ", "analogy": "本（データ）に対する「背表紙や目次、図書館の検索カード（メタデータ）」です。\n「本文（データ）」とは別に、「作者は誰か、発行日はいつか、何ページあるか」といった情報を管理しておくことで、中身を全部読まなくても探したい本がすぐに見つかるようになります。", "details": "データを管理・検索・分類しやすくするために付与される「属性情報」。\nデータベースにおいては、テーブルの構造や制約などの定義情報（スキーマ）を指し、データディクショナリ（データ辞書）に格納される。", "etymology": "Meta（高次の、超越した、〜についての）＋ Data（データ）。\n直訳すると「データについてのデータ」。本体のデータそのものではなく、そのデータを説明する情報のこと。", "exam": "データベース分野で出題。\n「データディクショナリ（データ辞書）」に格納される情報として問われます。「データに関するデータ」「データの意味や構造を定義したもの」という説明があればメタデータが正解です。", "def30": "データの作成日時や構造など、データを説明するための属性情報。（30文字）"}, {"id": 50, "term": "ACID特性", "summary": "・DBMSのトランザクション処理が満たすべき4つの性質（Atomicity, Consistency, Isolation, Durability）。\n・特に「Isolation（独立性）」と「Durability（永続性）」の定義がよく問われる。", "keywords": "・トランザクション\n・Atomicity（原子性）\n・Consistency（一貫性）\n・Isolation（独立性・隔離性）\n・Durability（永続性）", "analogy": "「銀行の振り込み処理の絶対に守るべき4ルール」です。\n・原子性：振り込みは成功か全キャンセルの2択\n・一貫性：整合性が崩れない\n・独立性：他の人と同時に振り込んでも混ざらない\n・永続性：完了したら停電しても消えない", "details": "データベースのトランザクション処理において担保されるべき4つの信頼性要素。\n・A（原子性）：全実行か全消去か\n・C（一貫性）：矛盾がないか\n・I（独立性）：他から干渉されないか\n・D（永続性）：結果が永久に保存されるか", "etymology": "4つの頭文字。\nAtomicity（原子）、Consistency（一貫性）、Isolation（孤立）、Durability（耐久性）の英単語の略。", "exam": "データベース分野で毎回のように出題。\n「全実行か全取り消しかのどちらか（原子性）」「完了した結果は障害が起きても失われない（永続性）」のように、各英単語と役割の対応を問う選択肢問題が頻出です。", "def30": "DBのトランザクション処理が満たすべき信頼性の4つの基本特性。（31文字）"}, {"id": 51, "term": "共有ロック / 排他ロック", "summary": "・DBの同時アクセス時の矛盾を防ぐロック手法。\n・「参照用（他人も同時に読める）」と「更新用（他人の参照・更新を拒否する）」の2種類がある。", "keywords": "・同時実行制御\n・トランザクション\n・共有ロック（読込）\n・排他ロック（更新）\n・ロックの競合", "analogy": "「図書館の図鑑の利用ルール」です。\n共有ロック＝その場で「読む」だけなので複数人で覗き込める。排他ロック＝ペンで「書き込む（更新）」ため、他の人は覗くこともできません。", "details": "トランザクションの直列化可能性を保証する手法。\n・共有ロック（読込ロック）：他のトランザクションも共有ロックをかけられるが排他ロックは拒否。\n・排他ロック（書込ロック）：他のいかなるロックも拒否する。", "etymology": "Shared Lock / Exclusive Lock。", "exam": "データベースの排他制御で頻出。「共有ロック中のデータには別の共有ロックはかけられるが、排他ロックはかけられない（待ちになる）」というマトリクス関係が問われます。", "def30": "DBの同時更新を防ぐための、読込用（共有）と書込用（排他）の施錠。（33文字）"}, {"id": 52, "term": "チェックポイント\n(Checkpoint)", "summary": "・メモリ上の変更内容をディスクに書き込み、データの状態を同期・確定させる処理。\n・障害発生時にログを遡る量（ロールフォワードする量）を減らし、復旧時間を短縮する。", "keywords": "・障害回復時間の短縮\n・メモリからディスクへの書き込み（同期）\n・ロールフォワードの起点", "analogy": "「日記をノートに清書するタイミング」です。\n頭の中（メモリ）で考えたことを定期的にノート（ディスク）に書いておかないと、停電が起きた時、頭の中の記憶が消えて最初から全部思い出す（ロールフォワードする）ハメになります。", "details": "DBMSにおいて、メモリ（バッファ）上の更新データを定期的にハードディスクなどの物理ディスクに書き込む（同期する）処理。", "etymology": "Checkpoint（通過点、確認地点）。\nメモリ上での変更内容を、定期的にディスクに確定させるポイントのこと。", "exam": "「障害回復にかかる時間を短縮する」または「バッファ（メモリ）の内容をディスクに書き出す」という文言があれば、100%チェックポイントが正解です。", "def30": "メモリ上の更新をディスクに書き込み、障害回復を早める処理。（29文字）"}, {"id": 53, "term": "ロールバック\n(Rollback)", "summary": "・処理の途中で障害が起きた際、データを処理開始前の状態に「巻き戻す」機能。\n・未完了（コミット前）の処理に対して、「更新前ログ」を用いて復旧を行う。", "keywords": "・コミット前の障害\n・ジャーナルファイル（更新前ログ）\n・取り消し処理\n・トランザクション開始時点に戻す", "analogy": "「書類の書き損じで、新しい白紙からやり直す」イメージです。\n「Aの口座から1万引いてBに1万足す（コミット）」処理の途中で停電した場合、Aの1万円が消えないよう、ログを見て「Aから引く前の状態」に巻き戻します。", "details": "トランザクション（一連の処理）の途中で障害が発生したり、処理がキャンセルされたりした際、「更新前ログ（ジャーナル）」を使って、そのトランザクションが始まる前の状態にデータを復旧する処理。", "etymology": "Roll back（巻き戻す）。\nビデオを巻き戻すように、データベースの状態を「処理が始まる前の状態」に戻すこと。", "exam": "障害回復機能として頻出。\n「コミットされていない（未完了の）トランザクション」に対して行われるのがロールバックです。使用するログが「更新前ログ」である点もよく問われます。", "def30": "更新前ログを用いて、処理開始前の状態にデータを復旧する処理。（30文字）"}, {"id": 54, "term": "ロールフォワード\n(Roll forward)", "summary": "・ディスク故障などの際、バックアップデータから障害直前の状態まで「早送り」して復旧する機能。\n・完了済み（コミット後）の処理に対して、バックアップと「更新後ログ」を用いる。", "keywords": "・コミット後のハードウェア障害（媒体障害）\n・バックアップファイル ＋ ジャーナルファイル（更新後ログ）\n・チェックポイントからの再実行", "analogy": "「セーブデータからのゲームやり直し」です。\nゲーム機が壊れてデータが飛んだ場合、最後にセーブした時点のデータをロードし、そこから「クリアしたという記録（更新後ログ）」を見ながら、壊れる直前の状態まで自動でゲームを進めて（早送りして）復旧させます。", "details": "ディスクの故障（媒体障害）などでデータが物理的に失われた際、「最新のフルバックアップ」を復元し、そこから「更新後ログ（ジャーナル）」を使って完了済みの処理を再実行し、障害直前の状態までデータを復旧する処理。", "etymology": "Roll forward（早送りする、前へ進める）。\n過去のバックアップデータをスタート地点にして、ビデオを早送りするように「障害発生直前の状態」まで処理を進めること。", "exam": "「チェックポイント（セーブポイント）」との関係が超頻出です。\n「コミット済み（完了済み）のトランザクション」に対して行われるのがロールフォワードです。バックアップと「更新後ログ」の2つが必要になる点がポイントです。", "def30": "バックアップと更新後ログを用いて、障害直前の状態に復旧する処理。（32文字）"}, {"id": 55, "term": "セーブポイント\n(Savepoint)", "summary": "・トランザクション（一連の処理）内に設ける一時的な目印（しおり）。\n・エラー時に最初からやり直すのではなく、その目印まで部分的に取り消すことができる。", "keywords": "・トランザクション内の任意の位置\n・部分的なロールバック\n・部分取り消し", "analogy": "「長いダンジョンの中間セーブポイント」です。\nボスの前でセーブポイントを作っておけば、もし全滅（エラー）しても、ダンジョンの入り口（トランザクションの最初）からではなく、ボスの前から部分的にやり直せます。", "details": "1つのトランザクションの中で任意に設定できる一時的な目印。エラー発生時にトランザクション全体を無効にするのではなく、この目印まで部分的にロールバック（取り消し）できる。", "etymology": "Savepoint（保存地点）。\n長いトランザクション（処理）の途中に設定する「しおり」のようなもの。", "exam": "チェックポイントと混同させる「ダミー選択肢」として登場することが多いです。\n正解になる場合は、必ず「トランザクション内の任意の位置」「部分的に取り消す（ロールバックする）」という説明がセットになります。", "def30": "一連の処理内に設定し、部分的なロールバックを可能にする目印。（30文字）"}, {"id": 56, "term": "ストアドプロシージャ / トリガ", "summary": "・ストアドはDB側に保存・コンパイルされた一連のSQLプログラム。\n・トリガはデータ変更時等に「自動的」に実行される仕組み。", "keywords": "・DBサーバー側での実行\n・ネットワーク負荷軽減\n・パフォーマンス向上\n・トリガ（自動発火）\n・ストアドプロシージャ", "analogy": "「自販機の中の全自動プログラム」です。\nお金に入れてボタンを押すだけで、裏で「在庫を減らす」「お釣りを計算する」という一連の作業（ストアド）をDB側が全部やってくれます。", "details": "・ストアドプロシージャ：複数のSQL文をまとめ、DBサーバー上に保存・事前コンパイルしたもの。通信量削減と高速化に寄与。\n・トリガ：INSERTやUPDATEなどの操作を引き金（トリガ）として自動実行される処理。", "etymology": "Stored（保存された） Procedure（手順） / Trigger（引き金）。", "exam": "DBの性能向上策として出題。「一連のSQLをサーバー側に保存し、ネットワークの通信量を減らして処理を高速化する＝ストアドプロシージャ」が定番の解答です。", "def30": "複数のSQL文をDB側に保存し、通信量削減や高速化を図る仕組み。（32文字）"}, {"id": 57, "term": "レプリケーション\n(DB複製)", "summary": "・データベースの内容をリアルタイムまたは定期的に別のDBサーバーへ完全複製し、可用性向上や負荷分散を図る技術。", "keywords": "・主DB（マスター）\n・副DB（スレーブ/レプリカ）\n・同期・非同期複製\n・可用性（HA）\n・読込負荷分散", "analogy": "「ノートの自動リアルタイムコピー」です。\nメインのノート（マスター）に文字を書いた瞬間、裏でアシスタントが別のノート（レプリカ）に全く同じ内容をコピーしてバックアップを作ります。", "details": "オリジナルのデータベース（マスター）の更新内容を、リアルタイムまたは非同期で別のデータベース（レプリカ）に自動複製する技術。マスター障害時の即時切り替え（容認）や参照負荷分散に利用。", "etymology": "Replication（複製、コピー）。", "exam": "データベース・可用性向上で超頻出。「データベースの更新内容を別のDBにリアルタイム複製し、障害発生時に切り替える＝レプリケーション」が定番の正解。", "def30": "DBの更新内容を別のDBへリアルタイム複製し可用性や性能を高める技術。（35文字）"}, {"id": 58, "term": "データウェアハウス / データマイニング", "summary": "・DWHは企業の様々なデータを時系列に大量蓄積した「巨大なデータの倉庫」。\n・データマイニングはその倉庫から「隠れた法則」を発掘する技術。", "keywords": "・DWH（データの倉庫）\n・時系列データ\n・意思決定支援\n・データマイニング（法則発見）\n・ビッグデータ\n・データマート", "analogy": "「巨大なレシート保管庫（DWH）と、すご腕の分析官（マイニング）」です。\n10年分のレシートから、「おむつを買う人はビールもよく買う」という隠れた法則を発掘します。", "details": "・データウェアハウス(DWH)：企業の基幹システムからデータを抽出し、目的別に再構成して時系列に蓄積した統合データベース。\n・データマイニング：統計学やAIを用い、大量のデータから相関関係やパターンを採掘する技術。", "etymology": "Data Warehouse（データの倉庫） / Data Mining（データの採掘）。", "exam": "ストラテジ・データベース分野で頻出。「意思決定支援のために時系列に蓄積された統合データ＝DWH」「大量データから有用なパターンや法則を見つけ出す＝マイニング」。", "def30": "時系列に蓄積した巨大なデータ群（DWH）から有用な法則を発掘する。（33文字）"}, {"term": "ETL\n(Extract, Transform, Load)", "summary": "・複数のシステムからデータを抽出（Extract）し、分析用に加工（Transform）して、DWH等に書き出す（Load）一連のデータ処理技術。\n・データウェアハウス（DWH）構築の要となるバッチ処理ツール。", "keywords": "・DWH（データウェアハウス）へのデータ統合\n・Extract（抽出） / Transform（加工・変換） / Load（送込）\n・バッチ処理\n・クレンジング（表記揺れ修正）", "analogy": "「大量の野菜を集めて、切って調理し、大きなバイキング台（DWH）に並べる工程」です。\n各農家（基幹システム）から野菜を回収（Extract）し、洗ってサイズを揃え（Transform）、バイキングの容器に詰める（Load）作業を一括で行います。", "details": "企業の基幹系データベース等から必要なデータを抽出し、データ型や表記揺れの変換（データクレンジング）、集計などの加工を行った上で、分析用データベース（DWHやデータマート）へ一括ロードするデータ統合プロセス。", "etymology": "Extract（抽出する）＋ Transform（変換・加工する）＋ Load（積み込む・書出す）の頭文字。\n「データを抜き出し、整えて、目的地に格納する」という手順そのまま。", "exam": "データベース・ビッグデータ分析分野で出題されます。\n・DWH（データウェアハウス）に前処理されたデータを蓄積する際の基幹技術であること\n・Extract, Transform, Load それぞれの役割の理解", "def30": "データを抽出・加工・変換しDWH等へ一括書き出しする技術。（29文字）", "id": 59}, {"id": 60, "term": "フォワードプロキシ vs リバースプロキシ", "summary": "・プロキシ（代理）の配置と役割。\n・フォワードは「クライアント側（社内）」に立ちWeb閲覧を仲介。\n・リバースは「サーバー側」に立ち負荷分散やセキュリティ保護を行う。", "keywords": "・フォワードプロキシ（クライアント代理/Web制限）\n・リバースプロキシ（サーバー代理/負荷分散/SSLオフロード）\n・キャッシュ", "analogy": "「社の受付（フォワード）」と「ホテルのコンシェルジュ（リバース）」です。\nフォワードは社員が外へ行くのをチェック（社内代理）、リバースは外部客を適切な部屋へ案内（サーバー代理）します。", "details": "・フォワードプロキシ：クライアント（内部ネットワーク）側に配置され、インターネットへのアクセスを代理実行し、キャッシュやWebフィルタリングを行う。\n・リバースプロキシ：Webサーバー側に配置され、外部からの要求を受け取って複数サーバーへ振り分け（負荷分散）やSSL暗号化処理（SSLオフロード）を代理する。", "etymology": "Forward Proxy（前方代理） / Reverse Proxy（逆方向代理）。", "exam": "セキュリティ・ネットワークで超超頻出！「社内から外部へのWebアクセスを制限・ログ記録＝フォワード」「Webサーバーの前段に置かれ外部アクセスを分散・保護＝リバースプロキシ」を完全に識別。", "def30": "クライアント側でアクセス仲介(フォワード)と、サーバー側で負荷分散(リバース)。（40文字）"}, {"id": 61, "term": "デュアルシステム vs デュプレックスシステム", "summary": "・高可用性システムの構成。\n・デュアルは「2台で同じ処理を同時に行い照合」。\n・デュプレックスは「主系が処理を行い、副系は待機（ホット/コールドスタンバイ）」。", "keywords": "・デュアルシステム（2台同時実行・クロスチェック）\n・デュプレックスシステム（主系と待機系・ホット/コールド）\n・信頼性・高可用性", "analogy": "「2人のパイロットと予備のパイロット」です。\n・デュアルシステム：2人のパイロットが同時に操縦桿を握り、お互いの操作を常にチェック（超高信頼・コスト高）。\n・デュプレックス：メインのパイロットが操縦し、副パイロットは横で待機（一般的）。", "details": "・デュアルシステム：2系統のシステムが常に同じ処理を並行して実行し、処理結果を照合しながら稼働。故障時は切り離して継続。信頼性最高。\n・デュプレックスシステム：主系（オンライン）と副系（待機系）に分かれ、主系障害時に副系へ切り替える（ホット/ウォーム/コールド）。", "etymology": "Dual（二重の） System / Duplex（複合の） System。", "exam": "システム構成で超頻出！「2台のコンピュータが常に同じ処理を実行して結果を相互に照合する＝デュアルシステム」「主系と待機系に分ける＝デュプレックスシステム」を絶対に区別！", "def30": "2台で同時処理し照合するデュアルと、主系と待機系に分けるデュプレックス。（36文字）"}, {"id": 62, "term": "クラスタ構成・HA\n(高可用性)", "summary": "・複数台のサーバーを束ねて1台のシステムとして運用し、停止時間を極小化する（HA：High Availability）構成技術。\n・アクティブ-スタンバイ等がある。", "keywords": "・HA（高可用性クラスタ）\n・フェイルオーバー（自動切り替え）\n・心拍確認（ハートビート）\n・共有ストレージ\n・ロードバランシング", "analogy": "「リレー走者のバトンタッチ」です。\nメインの走者（主サーバー）が倒れた時、すぐに控えの走者（待機サーバー）がバトン（データ）を受け取って走り続け、観客（ユーザー）には停止を見せません。", "details": "複数台のサーバーを専用ネットワークで相互接続して1つの高信頼システムに見せる構成。主サーバー故障時に即座に待機サーバーへ処理を引き継ぐ「フェイルオーバー」機能により高可用性（HA）を実現する。", "etymology": "Cluster（房、集団） ＋ High Availability（高可用性）。", "exam": "サーバー可用性問題で出題。「複数台のサーバーを統合し、故障時にフェイルオーバーして無停止運用を図るシステム＝HAクラスタ」「サーバー間でお互いの生存確認を行う信号＝ハートビート」。", "def30": "複数サーバーを統合し、故障時に自動切替して高可用性(HA)を実現する構成。（37文字）"}, {"id": 63, "term": "コンテナ型仮想化\n(Docker・Kubernetes)", "summary": "・OS全体ではなく、アプリの実行環境だけを「コンテナ」として切り出して動かす技術。\n・軽量で起動が速い。Kubernetesで統合管理する。", "keywords": "・Docker\n・Kubernetes（K8s）\n・コンテナオーケストレーション\n・ゲストOS不要\n・軽量・高速\n・ポータビリティ", "analogy": "「貨物船のコンテナ」です。\n中身（アプリや設定）をひとまとめにしておけば、どんな船（サーバー）にもそのまま積んで同じように動かせます。", "details": "ホストOSのカーネルを共有し、アプリケーションとその実行に必要なライブラリ群を「コンテナ」として隔離して実行する仮想化技術。ゲストOSが不要なため高速。", "etymology": "Container（容器）。アプリを独立した容器に入れて動かすイメージ。", "exam": "クラウドや最新インフラ技術で超頻出。「ゲストOSを含まないため軽量で起動が速い」「複数のコンテナを統合管理するツールがKubernetes」がポイント。", "def30": "アプリとその実行環境をひとまとめにし、軽量に動かす仮想化技術。（31文字）"}, {"id": 64, "term": "ライブマイグレーション\n(Live Migration)", "summary": "・稼働中の仮想マシン（VM）をOSやサービスを「停止させずに」別の物理サーバーへ移動させる技術。\n・物理サーバーのメンテナンス時や負荷分散時に、ダウンタイムなしで移行できる。", "keywords": "・仮想マシン（VM）\n・無停止移行\n・ダウンタイムゼロ\n・メモリ状態の転送\n・ハイパーバイザ\n・メンテナンス", "analogy": "「営業中の店舗ごと新しいビルにお引っ越しする」イメージです。\nお客さん（ユーザー）が買い物（利用）をしている最中でも、サービスを止めずに裏で丸ごと別の建物（物理サーバー）へお引っ越しします。", "details": "仮想化環境（ハイパーバイザ）において、稼働している仮想マシン（VM）のCPU状態やメモリ空間のデータをネットワーク経由で別の物理サーバーへ転送し、サービスの中断なしに移行させる技術。", "etymology": "Live（生の、稼働中の）＋ Migration（移住、引っ越し）。\nシステムが「生きた（動いた）まま」引っ越しすること。", "exam": "仮想化・クラウド分野で頻出。\n「稼働中の仮想マシンを停止させずに別の物理サーバーへ移動する」「物理サーバーの保守・メンテナンス時にもシステムを停止させずに済む（高可用性）」が正解の決め手です。", "def30": "稼働中の仮想マシンを停止させずに別の物理サーバーへ移動する技術。（32文字）"}, {"id": 65, "term": "シンクライアント / VDI", "summary": "・手元の端末（PC）にはデータを持たせず、サーバー側ですべての処理を行う仕組み。\n・情報漏洩対策や運用管理の効率化に有効。", "keywords": "・VDI（仮想デスクトップ基盤）\n・画面転送方式\n・情報漏洩対策\n・端末にデータを残さない\n・一元管理", "analogy": "「モニターとキーボードだけ持ち歩く」イメージです。\n頭脳（CPU）や記憶（HDD）はすべて会社のサーバーにあり、手元の画面にはその映像だけが映る仕組みです。", "details": "クライアント端末には最低限の機能のみを持たせ、OSやアプリケーション、データの処理・保存はすべてサーバー側（VDI等）で行うシステム構成。", "etymology": "Thin（薄い、機能が少ない）＋ Client（端末）。", "exam": "情報漏洩対策（セキュリティ）やテレワークの文脈で頻出。「端末を紛失してもデータが漏洩しない」「VDI（画面転送方式）」がキーワードです。", "def30": "端末にデータを残さず、すべての処理をサーバー側で行う仕組み。（30文字）"}, {"id": 66, "term": "マイクロサービスアーキテクチャ", "summary": "・巨大なシステムを、独立した小さなサービス（機能）の集まりとして構築する設計手法。\n・各サービスはAPI連携し、個別に更新・スケールできる。", "keywords": "・モノリシックとの対比\n・独立したデプロイ\n・API連携\n・コンテナ・DevOpsとの親和性", "analogy": "「お弁当箱ではなく、小鉢の定食」です。\n1つの大きなお弁当（モノリシック）だと一部の変更が大変ですが、小鉢なら「おひたし」だけ別のに簡単に変えられます。", "details": "システムを複数の小さな独立したサービスに分割し、それぞれが独自のDBを持ち、API経由で通信し合うアーキテクチャ。障害の局所化や開発スピード向上が目的。", "etymology": "Micro（小さな）＋ Services（サービス）のArchitecture（構造）。", "exam": "アジャイル開発やDevOpsとセットで出題。「システム全体を停止せずに一部の機能だけを独立してアップデート（デプロイ）できる」のが特徴。", "def30": "システムを独立した小さな機能の集合体として構築する設計手法。（30文字）"}, {"id": 67, "term": "SDN\n(Software Defined Networking)", "summary": "・ネットワークの構成や設定を、物理的な配線を変えずにソフトウェアで集中制御する技術。\n・OpenFlowなどが使われる。", "keywords": "・ソフトウェアによる制御\n・物理構成に依存しない\n・集中管理\n・OpenFlowプロトコル\n・コントロールプレーンとデータプレーンの分離", "analogy": "「魔法の配線盤」です。\n物理的にLANケーブルを抜き差ししなくても、画面上の設定（ソフトウェア）を変えるだけで、ネットワークの繋がり方を自由自在に変更できます。", "details": "ネットワーク機器の「データ転送機能（データプレーン）」と「制御機能（コントロールプレーン）」を分離し、ソフトウェアによってネットワーク全体を動的に集中管理する技術。", "etymology": "Software-Defined（ソフトウェアで定義された） Networking。", "exam": "ネットワーク分野の最新トレンド。「物理的な配線変更なしにソフトウェアでネットワーク構成を動的に変更できる」という記述が正解になります。", "def30": "ネットワーク構成をソフトウェアによって動的に集中管理する技術。（31文字）"}, {"id": 68, "term": "IaC\n(Infrastructure as Code)", "summary": "・サーバーやネットワークなどのインフラ構築・設定を、手作業ではなく設定ファイル（コード）として定義し、ツールで自動構築・管理する手法。", "keywords": "・インフラ構成のコード化\n・Terraform\n・Ansible\n・自動構築\n・バージョン管理（Git）\n・再元性", "analogy": "「サーバーの自動組み立てレシピ」です。\n1台ずつ手作業で画面をクリックして設定するのではなく、「このOS、このメモリ」とレシピ（コード）を書いておけば、ボタン1つで100台のサーバーが自動で作れます。", "details": "サーバーやネットワークの構成情報、ミドルウェアのセットアップ手順などをプログラミングコードとして記述し、TerraformやAnsible等のツールを用いてインフラの構築・変更・管理を自動化する設計運用手法。", "etymology": "Infrastructure as Code（コードとしてのインフラ）。", "exam": "クラウド・DevOpsのトレンド用語。「インフラ構成をコード化し、バージョン管理や自動構築を実現する技術＝IaC（Infrastructure as Code）」。", "def30": "サーバーやネットワークの構成をコードで定義し、自動で構築・管理する手法。（36文字）"}, {"id": 69, "term": "VPN\n(IPsec VPN / SSL VPN)", "summary": "・公衆回線（インターネット等）を、あたかも専用線のように安全に通信する技術。\n・拠点間はIPsec、リモートワーク等はSSL(TLS)が多く使われる。", "keywords": "・仮想閉域網\n・トンネリング\n・暗号化\n・IPsec VPN（ネットワーク層/拠点間接続）\n・SSL VPN（セッション層/リモートアクセス）", "analogy": "「インターネットという公道に引いた、自分専用の地下トンネル」です。\n他の人からはトンネルの中（通信内容）が見えないため、安全に社内と自宅をつなぐことができます。", "details": "インターネット上に仮想的な専用線を構築し、暗号化とトンネリング技術を用いて安全な通信を実現する仕組み。IPsecはL3で拠点間を繋ぎ、SSL VPNはブラウザ等で手軽にリモートアクセスする。", "etymology": "Virtual Private Network（仮想プライベートネットワーク）。", "exam": "テレワーク関連で頻出。拠点間をルータ同士で繋ぐ「IPsec VPN」と、PCからブラウザベースで社内に入る「SSL VPN」の用途の違いがよく問われます。", "def30": "公衆回線上に暗号化された仮想的な専用トンネルを構築する技術。（30文字）"}, {"id": 70, "term": "API", "summary": "・あるソフトウェアのデータや機能を、外部の別のソフトウェアから利用するための接点（規約）。\n・これらを連携させて新しいサービスを構築することを「マッシュアップ」と呼ぶ。", "keywords": "・ソフトウェア間の連携\n・インターフェース\n・Web API\n・マッシュアップ", "analogy": "「レストランのウェイター」です。お客さん（自分のアプリ）が厨房（外部システム）に直接入るのではなく、ウェイター（API）に「メニューをください」と頼むと、必要な料理（データや機能）を席まで持ってきてくれる仕組みです。Googleマップの機能を自社サイトに埋め込むのもAPIのおかげです。", "details": "あるソフトウェア（やWebサービス）の機能やデータを、外部の別のソフトウェアから呼び出して利用できるようにするための規約や窓口。開発効率の向上や、サービス間の連携を可能にする。", "etymology": "Application Programming Interface の略。\n「アプリケーション」の「プログラミング」における「インターフェース（接点・窓口）」という意味。", "exam": "システム開発やWeb技術の分野で出題。\n近年はWeb API（RESTful APIなど）が主流。複数のAPIを組み合わせて新しいサービスを作る「マッシュアップ」という用語とセットで出題されやすい。", "def30": "ソフトウェアの機能やデータを外部のプログラムから利用する規約。（31文字）"}, {"id": 71, "term": "RESTful API", "summary": "・Webの仕組み（HTTPメソッド：GET, POST, PUT, DELETE等）をそのまま活かしたシンプルなWeb APIの設計様式。\n・ステートレス（状態を持たない）であることが大きな特徴。", "keywords": "・HTTPメソッド\n・GET/POST/PUT/DELETE\n・ステートレス\n・URLによるリソース指定\n・JSON", "analogy": "「WebアドレスとHTTPの標準動詞だけで注文できる仕組み」です。\n「/users」というURLに対して「GET（頂戴）」「POST（作って）」「DELETE（消して）」というシンプルな命令を投げるだけで操作できます。", "details": "HTTPプロトコルをベースにしたWeb APIの設計ルール（REST）。\nリソース（データ）をURLで指定し、操作をHTTPメソッド（GET=取得、POST=作成、PUT=更新、DELETE=削除）で明示するシンプルな構成。", "etymology": "REST（Representational State Transfer）に従っている（-ful）APIという意味。状態（State）を遷移させる設計思想のこと。", "exam": "Web技術・システム連携で頻出。\n「HTTPメソッドを用いてリソースを操作する」「ステートレス（サーバーが状態を保持しない）」というキーワードが出たらRESTful API（またはREST）が正解です。", "def30": "HTTPメソッドを使いURLでデータ操作を指定するシンプルなAPI。（34文字）"}, {"id": 72, "term": "マッシュアップ\n(Mashup)", "summary": "・複数の既存Webサービス（API）やデータを組み合わせて、新しいサービスを作る手法。\n・自前でゼロから開発する手間を省き、短期間で付加価値の高いWebサイトを構築できる。", "keywords": "・複数のAPI\n・Webサービスの組み合わせ\n・新しいサービス\n・既存のデータ活用", "analogy": "「ぐるなびの店舗データ（API）」と「Googleマップの地図データ（API）」を混ぜ合わせて、「現在地周辺の美味しいお店が地図上にピンで表示されるアプリ」を作ることです。自分で地図システムや店舗情報を作らなくても、既存のパーツの「いいとこ取り」で新しいサイトが完成します。", "details": "複数の異なる提供元から公開されているWeb APIやデータを組み合わせて、単一の新しいWebサービスやアプリケーションを構築する開発手法。\n自前でゼロからシステムを開発する手間を省き、短期間で付加価値の高いサービスを作ることができる。", "etymology": "Mashup（混ぜ合わせる）。\n元々は音楽用語で「2つ以上の既存の曲を組み合わせて、1つの新しい曲を作る手法」のこと。ITではサービスを混ぜることを指す。", "exam": "システム開発・Web技術分野で出題。\n「API（Application Programming Interface）」という言葉とセットで出題されることが非常に多いです。\n「複数の提供元」「組み合わせて」「新しいサービス」というキーワードが並んだらこの用語が正解です。", "def30": "複数のAPIやWebサービスを組み合わせて新サービスを作る手法。（32文字）"}, {"id": 73, "term": "Ajax", "summary": "・画面全体をリロードせず、裏側で通信してページの一部だけを更新する手法。\n・JavaScriptの非同期通信を利用し、Googleマップのような快適な操作性を実現する。", "keywords": "・非同期通信\n・画面遷移なし（リロードなし）\n・JavaScript\n・XMLHttpRequest", "analogy": "GoogleマップやSNSの「いいね」ボタンです。\n昔のWebは、地図をスクロールするたびに画面全体が真っ白になって再読込されていましたが、Ajaxを使うと、画面は表示したまま裏側で「足りない部分の地図データ」だけを取ってきてスムーズに継ぎ足してくれます。", "details": "Webブラウザ上でJavaScriptを用いてサーバーと非同期通信を行い、ページ全体を再読込（リロード）することなく、ページの一部だけを動的に更新する手法。", "etymology": "Asynchronous JavaScript + XML の略。\nAsynchronous（非同期）に、JavaScriptとXML（現在はJSONが主流）を使って通信する仕組みのこと。", "exam": "Web技術（テクノロジ系）で超頻出。\n「非同期通信」「ページ全体を再読込（リロード）せずに一部だけ更新」というキーワードの組み合わせが出たら、確実にAjaxを指しています。", "def30": "非同期通信により、画面遷移なしでページの一部を更新する技術。（30文字）"}, {"id": 74, "term": "JSON / XML", "summary": "・システム間でデータをやり取りするためのデータ記述形式。\n・独自タグを用いる形式と、キーと値のペアで記述するJavaScript親和性の高い軽量な形式がある。", "keywords": "・データ交換フォーマット\n・Web API連携\n・タグ記述（XML）\n・キーと値（JSON）\n・軽量\n・JavaScript親和性", "analogy": "「荷物の送り状の書き方ルール」です。\nXMLは「<品名>りんご</品名>」としっかり書く形式。JSONは「品名:りんご」とシンプルに書くため、Webの世界で荷物を送るのに適しています。", "details": "・XML：ユーザーが独自のタグを定義できるマークアップ言語。\n・JSON：JavaScriptのオブジェクト記法を用いた軽量なデータフォーマット。現在のWeb API（RESTful API等）の主流。", "etymology": "JavaScript Object Notation / eXtensible Markup Language。", "exam": "Web技術のデータ形式問題で出題。「タグを用いて文書の構造を記述する＝XML」「JavaScriptの記法をベースにした軽量なデータ交換形式＝JSON」という違いが問われます。", "def30": "システム間でデータ連携を行うための記述形式。軽量なJSONが主流。（33文字）"}, {"term": "EAI\n(Enterprise Application Integration)", "summary": "・企業内の複数のシステムやデータを連携・統合し、一元管理する技術や仕組み。\n・データ形式やプロトコルの違いを自動変換し、システム間の1対1接続（スパゲティ化）を防ぐ。", "keywords": "・システム統合 / データ連携\n・ハブ＆スポーク構造\n・アダプタ / フォーマット変換\n・スパゲティ状態（1対1接続の乱立）の解消", "analogy": "「社内システム専用の『万能通訳者』がいる受付」です。\n営業部・経理部・工場で使っている言葉（データ形式）がバラバラでも、中央のEAIが言葉を翻訳してデータを受け渡してくれるため、システム同士が個別に手紙を送り合う必要がなくなります。", "details": "企業内で個別に構築された複数のシステム（ERP、CRM、会計システムなど）において、データ形式や通信手順の違いを吸収する共通基盤。データや業務プロセスのリアルタイム連携を可能にし、開発・運用コストを削減する。", "etymology": "Enterprise（企業全体の）＋ Application（アプリ）＋ Integration（統合・手を取り合うこと）。\n「企業内のシステムアプリ同士を手取りあわせてひとつにまとめる技術」という意味。", "exam": "システム統合・アーキテクチャ分野で出題されます。\n・1対1接続で起きるスパゲティ化をハブ＆スポーク構造で解決する仕組み\n・Webサービス技術を用いた後継のESB（Enterprise Service Bus）やSOAとの関係", "def30": "社内の複数のシステムやデータを連携・統合する技術や仕組み。（29文字）", "id": 75}, {"term": "ESB\n(Enterprise Service Bus)", "summary": "・SOA（サービス指向）を実現するため、企業内の多様なサービスやシステムを接続するバス型の共通通信基盤。\n・EAIより疎結合で柔軟なシステム連携を実現する。", "keywords": "・SOA（サービス指向アーキテクチャ）\n・バス型トポロジ\n・疎結合（ローカル依存の排除）\n・プロトコル変換 / メッセージルーティング", "analogy": "「大都市を巡る共通の地下鉄路線（バス）」です。\n各システムは近くの駅（共通バス）に乗り込むだけで、他のどのシステム（駅）へも自由に移動・データ送信ができます。路線が一本通っているため、個別アクセス線を何本も敷く必要がありません。", "details": "サービス指向アーキテクチャ（SOA）に基づき、標準化されたインターフェースやプロトコルを用いてシステム間のメッセージ仲介、データ変換、ルーティングを行うインフラストラクチャ層のミドルウェア。", "etymology": "Enterprise（企業向けの）＋ Service（サービス）＋ Bus（共通の乗り物・伝送路）。\n「企業内の全サービスが相乗りしてデータを運ぶ共通バス（回線）」という意味。", "exam": "システムアーキテクチャ分野で出題されます。\n・SOAを実現するための基盤ミドルウェアであること\n・ハブ型のEAIに比べてシステム間が「疎結合」に保たれる特徴", "def30": "SOAに基づき各種サービスを疎結合に接続するバス型通信基盤。（30文字）", "id": 76}, {"term": "iPaaS\n(Integration Platform as a Service)", "summary": "・SaaSなどのクラウドサービス間、またはクラウドと社内（オンプレミス）システムをクラウド上で統合・連携するクラウドサービス。\n・API連携やデータ同期をノーコード/ローコードで実現する。", "keywords": "・クラウド型システム統合\n・SaaS連携（Salesforce, Slack等）\n・オンプレミスとクラウドのハイブリッド連携\n・ノーコード / ローコード開発", "analogy": "「クラウド上の万能自動引っ越し業者」です。\n『Googleフォームに回答が来たら、自動でSalesforceに顧客登録し、Slackに通知する』という作業を、プログラミングなしで自動で繋いで作業してくれます。", "details": "複数の異なるクラウドアプリケーション（SaaS/PaaS）やオンプレミスシステム間のデータ・プロセス連携を構築・実行・管理するためのクラウド型プラットフォーム。従来自前で構築していたEAI機能をクラウドで提供する。", "etymology": "Integration（統合）＋ PaaS（クラウド型プラットフォーム）。\n「システム同士を統合・連携するためのクラウドサービス基盤」という意味。", "exam": "最新インフラ・クラウド技術分野で出題されます。\n・クラウド間のAPI連携やデータ同期をノーコード等で効率化する点\n・オンプレミスとクラウドを跨ぐハイブリッド環境の統合基盤としての役割", "def30": "クラウドや社内システム同士をクラウド上で統合・連携する基盤。（30文字）", "id": 77}, {"id": 78, "term": "メディアクエリ\n(Media Queries)", "summary": "・端末の画面サイズ等に応じてCSSを動的に切り替え、表示を最適化する機能（CSS3）。\n・ひとつのHTMLでスマホとPCの両方に対応する「レスポンシブWebデザイン」の基盤技術。", "keywords": "・レスポンシブWebデザイン\n・CSS3\n・画面サイズ（幅）\n・ブレイクポイント\n・@media", "analogy": "「画面の大きさに応じた自動着せ替え機能」です。\n画面の横幅をチェックして、「横幅が600px以下（スマホ）なら1列で文字を大きく表示」「それ以上（PC）なら3列でメニューを横並び表示」という風に、CSSのデザイン指示書を自動で切り替えます。", "details": "Webページを表示する端末の画面サイズ（横幅）や向き、解像度などの条件に応じて、適用するCSS（スタイルシート）を動的に切り替えるCSS3の機能。\n単一のHTMLでPC・スマホ・タブレットそれぞれの画面サイズに最適化したデザインを表示できる。", "etymology": "Media（表示媒体・端末の種類や画面サイズ）＋ Query（問い合わせ・判定）。\n「アクセスしてきた端末の画面幅や性能を問い問い合せる（判定する）」という意味。", "exam": "Web技術・CSS分野で出題。\n「レスポンシブWebデザインを実現するためのCSSの機能」として出題されます。\nCSS内での記述方法である `@media` ルールや、レイアウトが切り替わる境界線「ブレイクポイント」という単語とセットで問われます。", "def30": "画面サイズ等に応じてCSSを切り替え表示を最適化する技術。（29文字）"}, {"id": 79, "term": "Cookie・セッション管理", "summary": "・HTTPの「ステートレス（状態を保持しない）」弱点を補う仕組み。\n・Cookieはブラウザ側、セッションはサーバー側で状態（ログイン情報等）を保持する。", "keywords": "・HTTP（ステートレス）\n・Cookie（クライアント保存）\n・セッション（サーバー保存）\n・セッションハイジャック\n・CookieのSecure属性", "analogy": "「遊園地の再入場スタンプとロッカー鍵」です。\nCookieは手元に押してもらう「再入場スタンプ（ブラウザに保存）」、セッションは「ロッカー番号の鍵だけ持ち、中身は園内（サーバー）に保管する」仕組みです。", "details": "本来は通信の度に状態を忘れるHTTPプロトコルにおいて、ユーザーのログイン状態や買い物カゴ情報を維持するための技術。\nCookieはブラウザ側に保存され、セッションIDなどをやり取りする。", "etymology": "Cookie（クッキー：一口サイズのデータ）。Session（集まり、開会期間：一連の接続期間のこと）。", "exam": "Webセキュリティ分野で超頻出。\nCookieにセキュリティ設定（JavaScriptからの盗難を防ぐ`HttpOnly`属性や、HTTPS時のみ送信する`Secure`属性）を付与する対策や、セッションID奪取（セッションハイジャック）が問われます。", "def30": "Webでログイン状態等の通信状態を維持・管理するための仕組み。（31文字）"}, {"id": 80, "term": "オブジェクトストレージ", "summary": "・データをファイル構造（フォルダ階層）ではなく、固有のIDとメタデータを持つ「オブジェクト」単位で並列管理するストレージ方式。\n・ペタバイト級の拡張性（AWS S3等）。", "keywords": "・フラットな階層構造\n・一意のID\n・メタデータ付与\n・REST APIアクセス\n・高い拡張性（ペタバイト級）\n・AWS S3", "analogy": "「番号札で預かる巨大荷物預かり所」です。\nフォルダの階層（フォルダ → サブフォルダ）で作るのではなく、データに番号札（ID）と詳細タグ（メタデータ）を貼って広い空間にドカンと置いて管理します。", "details": "データを階層構造のファイルシステムやブロック単位ではなく、「データ本体 ＋ メタデータ ＋ 一意の識別子（ID）」を1つのオブジェクトとしてフラットな空間に保存するストレージ構造。REST API（HTTP）経由でアクセスし、ペタバイト規模まで容易に拡張可能。", "etymology": "Object Storage（オブジェクト単位で保持するストレージ）。", "exam": "クラウド・ストレージ技術で出題。「フォルダ階層を持たず一意のIDとメタデータで管理する」「REST API経由でアクセスし非構造化データの保存に適する＝オブジェクトストレージ（AWS S3等）」。", "def30": "データを固有IDとメタデータを持つオブジェクト単位でフラット管理する方式。（37文字）"}, {"id": 81, "term": "ウイルス検知手法", "summary": "・既知のウイルスは「パターンマッチング」、未知のものは「ヒューリスティック」や「ビヘイビア検知」で防御。\n・試験では未知のウイルス対策手法と、改ざん検知（整合性チェック）の違いが問われる。", "keywords": "・パターンマッチング（既知）\n・ヒューリスティック（未知）\n・サンドボックス（仮想環境）\n・ビヘイビア検知（振る舞い）\n・整合性チェック（ハッシュ）", "analogy": "泥棒を防ぐ警察官の検査方法です。\n指名手配写真で探すのが「パターンマッチング」。怪しい服装から勘で疑うのが「ヒューリスティック」。隔離部屋（サンドボックス）に誘導して様子を見るのが「サンドボックス」。街中で暴れだしたら逮捕するのが「ビヘイビア検知（振る舞い検知）」です。", "details": "マルウェアを検出・防御するための技術手法の総称。\n・パターンマッチング：定義ファイルと照合（既知のみ）\n・ヒューリスティック：コード構造から危険性を推測（未知対応）\n・サンドボックス：安全な仮想空間で実際に動かして検証\n・ビヘイビア検知：実行中の怪しい動作（振る舞い）を監視\n・整合性チェック：ハッシュ値でファイルの改ざんを検知", "etymology": "Virus Detection Methods（ウイルス検出手法）。\nVirus（病原体のように自己拡散・害をなすプログラム）を検出・防御するための各種アルゴリズムやアプローチのこと。", "exam": "セキュリティ分野で頻出。\n「パターンマッチング＝既知のみ（未知不可）」「ヒューリスティック/ビヘイビア/サンドボックス＝未知ウイルス対策」という対比や、「改ざん検出＝整合性チェック（ハッシュ値）」の役割の違いが問われます。", "def30": "既知・未知のマルウェアをパターン照合や動作検証で検知する技術。（31文字）"}, {"id": 82, "term": "標的型攻撃\n(APT攻撃)", "summary": "・特定の企業や組織の機密情報を狙い、長期間にわたって巧妙に行われるサイバー攻撃。\n・業務メールを装った添付ファイルなどが使われる。", "keywords": "・特定の組織・個人を狙う\n・APT（Advanced Persistent Threat）\n・やり取り型\n・業務偽装メール\n・潜伏\n・出口対策", "analogy": "「あなただけを狙ったプロの詐欺師」です。\n不特定多数への迷惑メールとは違い、「先日の会議の議事録です」といった本物そっくりのメールを送りつけ、社内PCを乗っ取って機密を盗みます。", "details": "明確な目的（機密情報の窃取等）を持ち、特定の標的（企業や官公庁）に対して、カスタマイズされたマルウェアやソーシャルエンジニアリングを駆使して長期間・執拗に行われる攻撃（APT）。", "etymology": "Targeted Attack / Advanced Persistent Threat（高度で持続的な脅威）。", "exam": "セキュリティの事例問題で頻出。「不特定多数ではなく特定の組織を狙う」「業務連絡を装った巧妙なメールを使う」「内部に潜伏して外部へ通信するため、プロキシ等での『出口対策』が重要」がキーワード。", "def30": "特定の組織の機密情報を狙い、業務メール等を装って巧妙に侵入する攻撃。（34文字）"}, {"id": 83, "term": "パスワードリスト攻撃", "summary": "・他サイトから不正流出したID/PWのリストを使い、別サイトで不正ログインを試みる攻撃。\n・ユーザーの「パスワード使い回し」を悪用するため、アカウントロック回避や防御が難しい。", "keywords": "・パスワードの使い回し\n・リスト型アカウントハッキング\n・他サイトからの流出ID/PW\n・多要素認証（MFA）による防御\n・アカウントロック対策（共通対策）", "analogy": "「拾ったマスター合鍵集で別の家のドアを片っ端から試す」手口です。\nAサイトで漏れたID/パスワードのペアを使って、BサイトやCサイトにそのまま入れてしまう人が多い（使い回し）隙を突きます。", "details": "攻撃者が他サービスから流出したログインIDとパスワードのリストを使用し、標的Webサイトで自動ログインを試みる攻撃。使い回しを行うユーザーを高確率で侵入させ、低頻度試行のためアカウントロックを検知しにくい。", "etymology": "Password List Attack。Credential Stuffing（資格情報の詰め込み）とも呼ばれる。", "exam": "情報セキュリティ分野で超超頻出！\n「パスワードの使い回しをしているユーザーが被害に遭う」「他サイトから漏洩したID/PW群を使う」「防御策：使い回し防止、多要素認証（MFA）」が正解のポイントです。", "def30": "他で流出したIDとパスワードのリストで不正ログインを試みる攻撃。（34文字）"}, {"id": 84, "term": "ブルートフォース攻撃\n(総当たり攻撃)", "summary": "・可能な文字の組み合わせ（全パターン）を片っ端から試してパスワードを解読・試行する攻撃。\n・辞書攻撃やリバースブルートフォースなどの派生型があり、アカウントロックが有効な対策。", "keywords": "・総当たり攻撃（ブルートフォース）\n・辞書攻撃（派生・辞書単語を優先試行）\n・リバースブルートフォース（1つのPWに多数ID）\n・パスワードの桁数・複雑化\n・アカウントロック対策（共通対策）", "analogy": "「ダイヤル錠の番号を『0000』から『9999』まで全部ガチャガチャ回す」手口です。\n力任せ（Brute Force）にすべての組み合わせを自動プログラムで打ち込んで、偶然当たるのを待ちます。", "details": "理論上可能な暗号鍵やパスワードの全組み合わせをコンピュータで片っ端から試行し解読する攻撃。辞書単語を優先する「辞書攻撃」や、1つの定番パスワードに多数のIDを試す「リバースブルートフォース攻撃」等の派生がある。", "etymology": "Brute（獣のような、乱暴な）＋ Force（力）。「力任せ・ゴリ押しの総当たり」という意味。", "exam": "情報セキュリティ分野で頻出！\n「可能な文字の組み合わせをすべて試す＝ブルートフォース攻撃」「対策：アカウントロック（連続失敗でロック）、桁数増大・複雑化」「特定パスワード固定でIDを変える＝リバースブルートフォース」を押さえましょう。", "def30": "可能なすべての文字列の組み合わせを片っ端から試し解読する攻撃。（32文字）"}, {"id": 85, "term": "ソーシャルエンジニアリング", "summary": "・IT技術を使わず、人間の心理的な隙や物理的な手段（肩越しに盗み見など）で機密情報を盗み出す手口の総称。", "keywords": "・人間の心理の隙\n・ショルダーハッキング（盗み見）\n・トラッシュマカク（ゴミあさり）\n・なりすまし電話\n・物理的手段", "analogy": "「古典的なスパイの手口」です。\nパスワードをハッキングで破るのではなく、入力している後ろから盗み見たり（ショルダーハック）、ゴミ箱から機密書類を漁ったり、システム管理者になりすまして電話でパスワードを聞き出します。", "details": "ネットワークやシステムの脆弱性を突くのではなく、人間の心理的な隙（権威への服従や親切心）や物理的なミスを利用して、パスワードなどの機密情報を不正に取得する手法。", "etymology": "Social Engineering（社会的な工学手法）。人間の社会活動・心理を利用すること。", "exam": "セキュリティの脅威分類で出題。「システム管理者と偽って電話でパスワードを聞き出す」「キーボードの入力を背後から盗み見る（ショルダーハッキング）」といった物理的・心理的手段を指します。", "def30": "IT技術を使わず、盗み見や電話などの物理的・心理的手段で情報を盗む手口。（36文字）"}, {"id": 86, "term": "サラミ法・スキャビンジング\n(不正手口)", "summary": "・サラミ法は口座の利息計算などの端数を極小額ずつ大量に盗む手口。\n・スキャビンジングは処理後のゴミ箱や残留データから機密を探し出す手口。", "keywords": "・サラミ法（端数の詐取）\n・スキャビンジング（ゴミあさり/スカベンジング）\n・物理的セキュリティ\n・内部不正", "analogy": "「サラミの薄切り（サラミ法）」と「ゴミあさり（スキャビンジング）」です。\n気づかれないように薄く1枚ずつお肉を削ぎ落とす手口と、捨てられたゴミの中から暗証番号を探す手口です。", "details": "・サラミ法：多数の取引からごく少額（丸め誤差や端数）を詐取する不正手法。\n・スキャビンジング：作業後に残された印刷物、ゴミ箱、メモリの残留領域から情報を探し出す手法。", "etymology": "Salami technique / Scavenging（ゴミ拾い）。", "exam": "セキュリティ脅威の分類で出題。「丸め処理の端数を少しずつ集めて不正取得する＝サラミ法」「廃棄書類やメモリの残存データから機密情報を探す＝スキャビンジング（ソーシャルエンジニアリングの一種）」。", "def30": "微小端数を集めて詐取するサラミ法と廃棄物から探索するスキャビンジング。（35文字）"}, {"id": 87, "term": "エクスプロイトコード", "summary": "・ソフトウェアやOSのセキュリティ脆弱性（バグ）を検証・悪用するために作られた攻撃用プログラムや概念実証（PoC）コード。", "keywords": "・脆弱性の実証\n・攻撃用コード\n・PoC（概念実証）\n・ゼロデイ攻撃\n・ゼロデイエクスプロイト", "analogy": "「実物の『合鍵作り方の見本』」です。\n「この鍵（バグ）はこうやってガチャガチャ動かすと開いちゃうよ」ということを証明（または悪用）するための攻撃スクリプトです。", "details": "ソフトウェアのセキュリティホール（脆弱性）を突いて、不正アクセスや特権昇格、命令の強制実行などを発生させるために記述されたプログラムやコードの断片。サイバー攻撃に悪用される。", "etymology": "Exploit（（脆弱性を）突く、悪用する） ＋ Code。", "exam": "セキュリティ分野で出題。「脆弱性を悪用して不正実行や侵入を行うための攻撃プログラム＝エクスプロイトコード」を押さえておきましょう。", "def30": "システムの脆弱性を突き、不正実行や侵入を引き起こす攻撃プログラム。（33文字）"}, {"id": 88, "term": "DoS攻撃・DDoS攻撃", "summary": "・DoSは1台、DDoSは乗っ取った多数の端末（ボットネット）から、ターゲットのサーバーへ過剰な負荷を与えてサービス停止に追い込む攻撃。", "keywords": "・サービス不可（Denial of Service）\n・ボットネット\n・SYNフラッド\n・UDPフラッド\n・大量アクセス", "analogy": "「お店の嫌がらせ殺到攻撃」です。\n1人でひたすら電話をかけて回線を占領するのがDoS。1000人のゾンビ部隊に指示して一斉に電話をかけさせ、完全にパンクさせるのがDDoSです。", "details": "・DoS攻撃：単一の送信元から標的サーバーへ過剰な処理リクエストや不正パケットを送りつけ、サービスを一時停止させる攻撃。\n・DDoS攻撃：ボットネット等の複数の送信元から一斉に分散して行う大規模攻撃。", "etymology": "Denial of Service (DoS) / Distributed Denial of Service (DDoS)。", "exam": "セキュリティの攻撃手法で超頻出。「単一の送信元からの攻撃＝DoS」「複数のボット端末等から分散して一斉攻撃＝DDoS」の違いを押さえましょう。", "def30": "単一(DoS)または複数端末(DDoS)から大量アクセスを送りサービスを停止させる攻撃。（44文字）"}, {"id": 89, "term": "ダークネット", "summary": "・インターネット上で「到達可能だが、実際にはどのホスト（PCやサーバー）にも割り当てられていない未使用のIPアドレス空間」。\n・マルウェアの無差別攻撃の検知に利用。", "keywords": "・未使用IPアドレス空間\n・ハニーポット\n・マルウェアスキャン検知\n・サイバー攻撃の観測（NICTハニック等）\n・パッシブモニタリング", "analogy": "「誰も住んでいない無人屋敷街」です。\n住人が誰もいないはずの屋敷（未使用IP）にドアを叩く音（通信）が響いたら、それは100%泥棒（マルウェアの無差別スキャン）だと即判定できます。", "details": "インターネット上に存在し、正当なパケットが送信されるはずのない未使用のIPアドレス空間。ここに届く通信を常時モニタリング（パッシブ観測）することで、感染拡大中のマルウェアによる無差別スキャン攻撃等を早期検出できる。", "etymology": "Darknet（暗い、目に見えないネットワーク空間）。", "exam": "セキュリティ観測技術で頻出。「未使用のIPアドレス空間を監視し、マルウェアの無差別走査（スキャン）活動を検知・分析するシステム＝ダークネット（ハニーポット等と連携）」。", "def30": "到達可能だがどの機器にも割り当てられていない未使用IP空間で攻撃を監視する。（38文字）"}, {"id": 90, "term": "SQLインジェクション攻撃", "summary": "・入力フォームから不正なSQL文を「注入」し、DBを不正操作・情報漏えいさせる攻撃。\n・対策はプレースホルダ（バインド機構）の使用や特殊文字のエスケープ処理。", "keywords": "・入力フォーム\n・不正なSQL\n・エスケープ処理\n・プレースホルダ（バインド機構）", "analogy": "ログイン画面のID欄に「 ' OR '1'='1 」のような文字列を入れると、システムが「IDは空、または1=1（常に正しい）」と勘違いし、パスワードなしで不正ログインできてしまうような手口です。", "details": "Webアプリケーションの脆弱性を突き、入力フォーム等を通じてデータベースに不正なSQL文を強制的に組み立てて実行させる攻撃。\n機密データの窃取、改ざん、削除、不正ログインなどを引き起こす。", "etymology": "SQL（データベースを操作する言語）＋ Injection（注入）。\nアプリケーションの入力欄から、悪意のあるSQL文の断片を「注入」して実行させる攻撃。", "exam": "セキュリティ分野の超頻出用語。\n攻撃手口だけでなく「対策」が問われる。\n・根本的対策：「プレースホルダ（バインド機構）の使用」\n・保険的対策：「エスケープ処理」「WAFの導入」", "def30": "入力フォームに不正なSQL文を注入し、DBを不正操作する攻撃。（31文字）"}, {"id": 91, "term": "OSコマンドインジェクション", "summary": "・Webの入力欄にOS（サーバーの根幹）を操作するコマンドを紛れ込ませて不正実行させる攻撃。\n・サーバーの乗っ取りやファイル破壊に繋がる。", "keywords": "・シェルスクリプト\n・サーバー乗っ取り\n・システムコマンド不正実行\n・入力値のサニタイジング\n・権限最小化", "analogy": "「注文書に『ついでに金庫を開けろ』と書き込む」手口です。\nWebサイトの入力フォームを通じて、背後にあるOSに直接「ファイルを全部消せ」という命令（コマンド）を流し込みます。", "details": "Webアプリケーションが、ユーザーの入力データをOSのシェル（コマンドライン）に渡して実行する実装になっている脆弱性を突き、不正なOSコマンドを挿入（インジェクション）して実行させる攻撃。", "etymology": "OS Command Injection（OSへの命令を注入する）。", "exam": "SQLインジェクションとの違いが問われます。「DBを不正操作＝SQLインジェクション」「サーバーのOSコマンドを直接実行＝OSコマンドインジェクション」です。", "def30": "Webの入力欄を通じてサーバーのOSコマンドを不正に実行させる攻撃。（34文字）"}, {"id": 92, "term": "クロスサイトスクリプティング\n(XSS)", "summary": "・Webサイトの脆弱性を突き、悪意のあるJavaScriptを被害者のブラウザ上で実行させる攻撃。\n・Cookie内のセッションID奪取や画面改ざんを引き起こす。対策は「サニタイジング（エスケープ処理）」。", "keywords": "・JavaScript\n・ブラウザ上で実行\n・セッションID盗難\n・サニタイジング（エスケープ処理）\n・HTML特殊文字", "analogy": "「掲示板の投稿に透明な罠スクリプトを仕込む手口」です。\n攻撃者が掲示板に怪しいプログラムを書き込み、それを開いた一般ユーザーのブラウザ上でスクリプトが勝手に動いて、Cookie（ログイン鍵）が盗まれます。", "details": "Webアプリケーションの入力チェック不備を利用し、悪意のあるHTMLやJavaScriptを含む入力をそのままブラウザに出力させる攻撃。被害者の端末上でスクリプトが実行されCookie等が奪われる。", "etymology": "Cross-Site Scripting（サイトを跨いでスクリプトを実行させる）の略。CSSだとスタイルシートと紛らわしいため「XSS」と表記する。", "exam": "セキュリティの超頻出攻撃手法。\n「ブラウザ上でJavaScriptを実行させる」「対策はHTML特殊文字（`<`, `>`, `&`等）のサニタイジング（エスケープ）」という組み合わせが確実に問われます。", "def30": "悪質なJavaScriptを実行させ、Cookie等を取り盗む攻撃。（34文字）"}, {"id": 93, "term": "CSRF\n(クロスサイトリクエストフォージェリ)", "summary": "・ログイン中の被害者を騙し、悪意のあるサイト経由で「本人になりすましたリクエスト（書き込みや購入）」を強制送信させる攻撃。\n・対策は「トークン（乱数）の検証」。", "keywords": "・偽造リクエスト\n・ログイン中のセッション利用\n・意図しない操作の強制\n・対策：トークン（乱数）の検証", "analogy": "「ログイン中のまま勝手に買い物ボタンを押させる罠サイト」です。\n掲示板等にログインした状態のまま攻撃者の罠サイトを開くと、裏で勝手に「掲示板に犯罪予告を書き込む」などのリクエストが自分の名義で送信されてしまいます。", "details": "Webサイトにログイン中のユーザーが、悪意のある罠サイトを閲覧した際、ユーザーのブラウザからターゲットサイトへ意図しないリクエスト（パスワード変更や購入等）を送信させる攻撃手法。", "etymology": "Cross-Site Request Forgery（サイトを跨いでリクエストを偽造する）の略。Forgery＝偽造、捏造という意味。", "exam": "XSSとの違いが超頻出！\n「XSS＝JavaScriptを実行される」「CSRF＝ログイン状態を利用して意図しない勝手なリクエストを送信される」という違いを押さえ、対策の「ワンタイムトークンの検証」とセットで覚えましょう。", "def30": "ログイン中のユーザーに意図しない処理を強制実行させる攻撃。（29文字）"}, {"id": 94, "term": "ディレクトリトラバーサル", "summary": "・「../（親ディレクトリへ移動）」という文字列を入力欄に入れて、公開されていない上位の階層のファイル（パスワードファイル等）を不正に閲覧する攻撃。", "keywords": "・親ディレクトリ指定（../）\n・パストラバーサル\n・非公開ファイルの閲覧\n・/etc/passwd\n・ファイル名指定の脆弱性", "analogy": "「立ち入り禁止の裏口の鍵をこじ開ける」手口です。\nURLに「一個上のフォルダに戻れ（../）」という命令を連続で入れ込み、見せてはいけないシステムの奥底にある重要ファイルを引きずり出します。", "details": "Webアプリケーションのファイル名指定の脆弱性を突き、相対パスの表記（../ など）を用いて、本来アクセスが許可されていないディレクトリ（階層）にあるファイルに不正アクセスする攻撃。", "etymology": "Directory（階層、フォルダ）＋ Traversal（横断、行き来する）。", "exam": "攻撃手法の識別問題で頻出。「上位ディレクトリを指定する文字（../）」「本来アクセスできないファイル（/etc/passwd等）を不正に閲覧する」というキーワードが出たらこれです。", "def30": "相対パス指定（../）を悪用し、非公開のファイルに不正アクセスする攻撃。（36文字）"}, {"id": 95, "term": "レインボーテーブル", "summary": "・ハッシュ値から元の文字列を効率よく逆引き（解読）するための事前計算テーブル。\n・対策としては、パスワードにランダムな文字列（ソルト）を付加してハッシュ化することが有効。", "keywords": "・ハッシュ値の逆引き\n・事前計算\n・パスワードクラック\n・ソルト（塩振り）による防御", "analogy": "「元に戻せないはずの暗号（ハッシュ値）」の解読表です。あらかじめ大量の計算を行って『この暗号値の元の文字列はこれ』というデータを圧縮してリスト化しておき、一瞬でパスワードを突き止めます。", "details": "ハッシュ化されたパスワードから元の文字列を割り出す（逆引きする）ための事前計算テーブル。\n計算時間とメモリ容量のトレードオフを利用し、データ量を極限まで圧縮しつつ高速な解読を可能にする。", "etymology": "Rainbow Table（虹の表）。\nハッシュ関数と縮小関数を交互に繰り返す「チェーン」の構造を、光のスペクトル（虹）に見立てて名付けられた特殊な対照表。", "exam": "セキュリティの「パスワードクラック」分野で出題。\n攻撃手法そのものよりも、防御策である**「ソルト（Salt：塩振り）」**とセットで問われます（ソルトを付加すると事前計算表が使えなくなる）。", "def30": "ハッシュ値から元の文字列を逆引きしパスワードを解読する手法。（30文字）"}, {"id": 96, "term": "暗号方式の鍵\n(共通・公開・秘密)", "summary": "・共通鍵は高速だが鍵配送が課題。公開鍵方式は安全に鍵を共有できるが処理が遅い。\n・秘密に送る時は「受信者の公開鍵」で、本人証明する時は「送信者の秘密鍵」で暗号化する。", "keywords": "・共通鍵：高速・鍵配送困難\n・公開鍵：受信者の公開鍵\n・ディジタル署名：送信者の秘密鍵", "analogy": "・共通鍵は「合鍵」。相手に渡す途中で盗まれると危険。\n・公開鍵は「南京錠」。相手が配った南京錠でロックして送れば、開けられるのは相手（秘密鍵）だけ。\n・署名は「実印」。自分の実印（秘密鍵）を押して送り、相手は印鑑登録証（公開鍵）で本物か確かめる。", "details": "・共通鍵：暗号化と復号に同じ鍵を使う。高速だが鍵配送が困難。\n・公開鍵方式（公開鍵/秘密鍵）：ペアの鍵を使う。秘密鍵は自分だけが持ち、公開鍵は全員に配る。安全だが処理が遅い。", "etymology": "Symmetric（対称＝共通鍵）、Asymmetric（非対称＝公開鍵方式）。\n暗号化と復号に同じ鍵を「対称」に使うか、ペアになる別々の鍵を「非対称」に使うかの違い。", "exam": "セキュリティ分野の超頻出項目。\n「AさんがBさんに秘密のメッセージを送る場合、どの鍵で暗号化するか？」という問題が必ず出ます。\n【暗号化】は「受信者の公開鍵」で、【ディジタル署名】は「送信者の秘密鍵」で行うという法則を絶対暗記。", "def30": "データの秘匿や本人証明を行うため、暗号化や復号に用いるデータ。（31文字）"}, {"id": 97, "term": "RSA暗号", "summary": "・「大きな合成数を素因数分解することの計算の困難性」を安全性の根拠とした、世界で最も広く普及している公開鍵暗号アルゴリズム。", "keywords": "・公開鍵暗号方式\n・素因数分解の困難性\n・大きな素数\n・鍵ペア（公開鍵・秘密鍵）\n・暗号化とデジタル署名", "analogy": "「鍵をかけるのは簡単だが、壊すのは不可能な金庫」です。\n2つの素数を掛け算（掛け算は一瞬）して作った特大の数を使います。その数を元の2つの素数にバラす（素因数分解）には、スーパーコンピュータでも何千年もかかります。", "details": "1977年にRivest、Shamir、Adlemanの3氏が開発した公開鍵暗号アルゴリズム。桁数が非常に大きい2つの素数の積を「素因数分解」することが計算量的に極めて困難であることを安全性の根拠とする。暗号化とデジタル署名の両方に利用可能。", "etymology": "開発者3名の頭文字（Rivest, Shamir, Adleman）。", "exam": "セキュリティの「暗号」分野で超頻出！「公開鍵暗号の代表格」「安全性の根拠＝素因数分解の困難性」というキーワードが絶対の決め手です。", "def30": "大きな素数の素因数分解の困難性を安全性の根拠とする代表的公開鍵暗号方式。（36文字）"}, {"id": 98, "term": "AES暗号", "summary": "・アメリカの標準規格（NIST）として採用されている、暗号化と復号に同じ鍵を使う「共通鍵暗号方式（ブロック暗号）」の標準アルゴリズム。\n・鍵長128/192/256ビット。", "keywords": "・共通鍵暗号方式\n・ブロック暗号\n・NIST標準\n・DESの後継\n・鍵長128/192/256ビット\n・Rijndael（ラインダール）", "analogy": "「最新の最強デジタル合鍵」です。\n旧世代の暗号（DES）が破られそうになったため、世界中の暗号学者から公募して選ばれた、超高速かつ堅牢な共通鍵方式の標準規格です。", "details": "DESに代わる米国標準暗号規格として採用された共通鍵暗号アルゴリズム（ベルギーのRijndaelが採用された）。データを128ビット単位のブロックに区切り、128/192/256ビットの鍵を用いて高速かつ強力に暗号化する。", "etymology": "Advanced Encryption Standard（高度暗号化標準）。", "exam": "セキュリティの暗号問題で超超頻出！「DESの後継として制定された現代の標準的な共通鍵暗号方式（ブロック暗号）＝AES」を押さえましょう。", "def30": "暗号化と復号に同じ鍵を用い、128ビット単位で高速暗号化する米国標準規格。（37文字）"}, {"id": 99, "term": "MAC\n(メッセージ認証コード)", "summary": "・通信の「改ざん」と「なりすまし」を検知するための、共通鍵を使った特殊なコード。\n・当事者間の証明には使えるが、第三者に対する「否認防止（送ってないと言い張ることの防止）」はできない。", "keywords": "・改ざん検知\n・送信者の真正性（なりすまし防止）\n・共通鍵\n・ハッシュ関数\n・※否認防止はできない", "analogy": "荷物（メッセージ）に付ける「差出人と受取人にしか開けられない鍵（共通鍵）付きの特殊な封印シール（MAC）」です。シールが破れていれば途中で誰かが中身をいじった（改ざん）とわかるし、そもそもその鍵でシールを作れたということは、間違いなく差出人本人（なりすましではない）だと証明できます。", "details": "通信において「メッセージが途中で改ざんされていないか（完全性）」と「送信者が本物か（なりすまし防止・真正性）」を確認するための短いデータ。\n送信者と受信者で共有する「共通鍵」と「ハッシュ関数」を使って生成される。", "etymology": "Message Authentication Code の略。\n「メッセージ（通信内容）」の「オーセンティケーション（認証・本物であることの証明）」用「コード（符号）」という意味。", "exam": "セキュリティ分野（暗号技術）で出題。\n「ディジタル署名」との違いが超頻出です。\n・MAC＝「共通鍵」を使うため、当事者間の改ざん・なりすましは防げるが、「送信の否認防止（第三者への証明）」は**できない**。\n・ディジタル署名＝「公開鍵方式」を使うため、否認防止ができる。", "def30": "共通鍵を用いて通信の改ざんやなりすましを検知する認証コード。（30文字）"}, {"id": 100, "term": "ディジタル署名\n(デジタル署名)", "summary": "・「送信者の秘密鍵」で暗号化し、「送信者の公開鍵」で復号することで本人証明を行う技術。\n・通信の「改ざん検知」「なりすまし防止」に加え、MACにはない「否認防止」の機能を持つ。", "keywords": "・送信者の秘密鍵で暗号化\n・送信者の公開鍵で復号\n・改ざん検知\n・否認防止（MACとの違い）", "analogy": "「電子版の実印と印鑑証明書」です。\nデータに、自分しか持っていない実印（送信者の秘密鍵）を押して送ります。受け取った人は印鑑証明書（送信者の公開鍵）と照らし合わせることで、「本人が押した」かつ「改ざんがない」と確認できます。", "details": "電子データに対し「本人が作成したこと」「改ざんされていないこと」「後から『送ってない』と言い逃れできないこと（否認防止）」を証明する技術。\nハッシュ値を送信者の秘密鍵で暗号化する。", "etymology": "Digital（デジタルの）＋ Signature（署名、サイン）。\n現実世界の「紙へのサインや実印」を、デジタルの世界で公開鍵暗号技術を使って実現したもの。", "exam": "セキュリティ分野の超頻出項目。\n「送信者の秘密鍵」で暗号化、「送信者の公開鍵」で復号という組み合わせが絶対問われます。\nまた、「MAC（メッセージ認証コード）」ではできない「否認防止（第三者への証明）」が可能である点が正解の鍵になります。", "def30": "送信者の秘密鍵を利用し、改ざんやなりすまし、否認を防ぐ技術。（30文字）"}, {"id": 101, "term": "PKI\n(公開鍵基盤)", "summary": "・公開鍵暗号技術と「認証局（CA）」を用いて、デジタル証明書を発行・検証し、本人の真正性を証明するインフラ。\n・CRL（失効リスト）やOCSPで証明書の有効性を確認する。", "keywords": "・CA（認証局）\n・デジタル証明書\n・ルート証明書\n・CRL（失効リスト）\n・OCSP\n・本人の真正性", "analogy": "「デジタルの世界のお役所（印鑑証明システム）」です。\n「この公開鍵は本当にAさんのものです」という証明書を信頼できる公的機関（認証局/CA）に発行してもらうことで、ネット上でも安心して取引ができます。", "details": "公開鍵暗号方式をベースに、通信相手が本物であるか（偽物・なりすましでないか）を証明するための社会的インフラ（基盤）。認証局（CA）がデジタル証明書を発行・管理する。", "etymology": "Public Key Infrastructure の略。\nPublic Key（公開鍵）の Infrastructure（社会的基盤・インフラ）という意味。", "exam": "セキュリティ分野で必須知識。\n「認証局（CA）」「デジタル証明書」「CRL（証明書失効リスト）」などの用語が出たらPKIに関連します。WebサイトのHTTPS接続（SSL/TLS）を支える土台です。", "def30": "認証局がデジタル証明書を発行し、公開鍵の所有者を証明する基盤。（31文字）"}, {"id": 102, "term": "TLS/SSL", "summary": "・Web通信（HTTP）などを暗号化し、盗聴・改ざん・なりすましを防ぐ標準プロトコル。\n・通信結果として「HTTPS（ポート443）」になる。", "keywords": "・通信の暗号化\n・HTTPS\n・ハイブリッド暗号\n・ポート443\n・サーバー証明書", "analogy": "「Webサイトとの通信を鍵付きのトンネルで包む仕組み」です。\nクレジットカード番号を入力して送信するとき、途中でハッカーに盗み見られても、暗号化されているため意味不明な文字にしか見えません。", "details": "トランスポート層で通信データを暗号化する標準プロトコル。共通鍵暗号（通信の高速化）と公開鍵暗号（鍵の安全な共有）を組み合わせた「ハイブリッド暗号方式」を採用している。", "etymology": "Transport Layer Security / Secure Sockets Layer の略。SSLは旧称だが、今でも総称して「SSL/TLS」と呼ばれることが多い。", "exam": "セキュリティ分野で超頻出。\n「HTTPと組み合わせたものがHTTPS（ポート443）」「ハイブリッド暗号方式を採用している」「サーバー証明書で相手の真正性を確認する」といった特徴が問われます。", "def30": "共通鍵と公開鍵を組み合わせ、Web通信を暗号化するプロトコル。（31文字）"}, {"id": 103, "term": "FIDO\n(Fast IDentity Online)", "summary": "・パスワードを使わず、指紋や顔などの生体認証（またはPIN）と公開鍵暗号技術を用いて、安全かつシンプルにオンライン認証を行う国際規格。", "keywords": "・パスワードレス認証\n・生体認証（バイオメトリクス）\n・公開鍵暗号方式\n・秘密鍵は端末内\n・フィッシングに強い", "analogy": "「スマホの指紋認証でWebサイトにログインする仕組み」です。\nパスワードをネットに流さないので盗まれる心配がなく、指紋データ自体も自分のスマホの安全な領域から外に出ません。", "details": "パスワードへの依存を減らすために策定された認証規格。ユーザーの端末側で生体認証等を行い、その結果を「公開鍵暗号方式」の署名を用いてサーバーに送信することで、安全なパスワードレス認証を実現する。", "etymology": "Fast IDentity Online（素早くオンラインで身元確認する）。", "exam": "セキュリティの認証分野のトレンド用語。「パスワードレス認証」「生体情報はサーバーに送信せず、端末側（セキュアエレメント）に保存し、公開鍵暗号を用いて認証局（サーバー）とやり取りする」のが最大の特徴です。", "def30": "生体認証と公開鍵暗号を用い、安全なパスワードレス認証を実現する国際規格。（36文字）"}, {"id": 104, "term": "ファイアウォール\n(パケットフィルタリング)", "summary": "・ネットワークの境界に置き、送信元/宛先IPアドレスやポート番号を元に通すか止めるかを判定するセキュリティ装置。", "keywords": "・パケットフィルタリング\n・ステートフルインスペクション\n・IPアドレス\n・ポート番号\n・DMZ\n・WAFとの違い", "analogy": "「マンションの入り口のオートロック門番」です。\n「住人（許可されたIP）」や「特定の配達員（許可ポート）」だけを通し、不審者は門の前で追い払います。", "details": "外部ネットワークからの不正アクセスを防ぐセキュリティ機器。通信のパケットヘッダー（IP・ポート・送信方向）を検査し、あらかじめ定めたルールに基づき通過・遮断を判定する。", "etymology": "Firewall（防火壁）。火災の延焼を防ぐ壁のイメージ。", "exam": "ネットワーク構成問題で頻出。「IPアドレスとポート番号で通過制御を行う＝パケットフィルタリング」「Webアプリの攻撃（SQL文等）は防げない（WAFが必要）」という役割限界も重要。", "def30": "IPやポート番号に基づきパケットの通過・遮断を判定する防御装置。（32文字）"}, {"id": 105, "term": "WAF\n(Web Application Firewall)", "summary": "・Webアプリケーション層（L7）への攻撃（SQLインジェクションやXSS等）を専門に検知・遮断するファイアウォール。\n・通常のFirewallやIPSでは防げないWeb特有の攻撃を防ぐ。", "keywords": "・Webアプリ層（L7）\n・SQLインジェクション対策\n・XSS対策\n・シグネチャ\n・HTTP/HTTPSペイロード検査", "analogy": "「Webサイトの入り口専用の特殊な警備員」です。\n建物の入り口（通常のFW）を通過した後の「Webフォームの入力欄」をじーっと見張り、怪しい文字列（SQL文や`<script>`タグ）が入っていないかチェックして追い払います。", "details": "Webアプリケーション（HTTP/HTTPS通信の中身・ペイロード）を監視し、SQLインジェクションやXSSなどのWeb特有の脆弱性を突いた攻撃を検知・遮断するセキュリティ製品。", "etymology": "Web Application Firewall の略。\nWebアプリケーションに特化した Firewall（防火壁）。", "exam": "セキュリティ製品の役割分担問題で頻出。\n「ネットワーク層を防ぐ＝FW」「OS/ネットワークの不正侵入を防ぐ＝IDS/IPS」「Webアプリ層（SQLインジェクション等）を防ぐ＝WAF」というレイヤーの違いが問われます。", "def30": "Webアプリ特有の攻撃（SQL文注入やXSS等）を防ぐ防御装置。（32文字）"}, {"id": 106, "term": "IDS / IPS\n(侵入検知 / 防御システム)", "summary": "・ネットワークやサーバーへの不正なアクセスや攻撃を監視するシステム。\n・「検知・通知のみ」を行う方式と、「検知して通信の遮断（防御）」まで行う方式がある。", "keywords": "・シグネチャ検知\n・アノマリ（異常）検知\n・ネットワーク型（NIDS）\n・ホスト型（HIDS）\n・FWとの違い", "analogy": "「監視カメラ（IDS）」と「自動シャッター（IPS）」の違いです。\nFW（入り口のドア）を通過してしまった不審者に対し、IDSはアラームを鳴らすだけですが、IPSは自動的にシャッターを下ろして捕まえます。", "details": "・IDS (Intrusion Detection System)：不正侵入を検知し、管理者に通知するシステム。\n・IPS (Intrusion Prevention System)：不正侵入を検知した際、その通信を動的に遮断して防御するシステム。", "etymology": "Intrusion（侵入） Detection（検知） / Prevention（防御） System。", "exam": "セキュリティ製品の役割として頻出。ファイアウォール（IPやポートで制限）を通過した通信の中身を見て、攻撃のパターン（シグネチャ）と一致すれば通知・遮断します。", "def30": "不正侵入を監視・通知するシステム（IDS）と通信を遮断するシステム（IPS）。（39文字）"}, {"id": 107, "term": "EDR\n(Endpoint Detection and Response)", "summary": "・PCやスマホ（エンドポイント）の動作を常時監視し、マルウェア感染「後」の迅速な検知と対応（隔離や調査）を支援するソフトウェア。", "keywords": "・エンドポイント\n・感染後の対応\n・不審な挙動の検知（振る舞い検知）\n・ログ収集・分析\n・マルウェア隔離", "analogy": "「PCの中に入り込んだスパイを見つける防諜部隊」です。\n従来のウイルス対策ソフトが「入り口で防ぐ」のに対し、EDRは「侵入された前提」で、怪しい動きをしているプログラムを見つけて即座に隔離・調査します。", "details": "パソコンやサーバーなどのエンドポイント（末端端末）におけるOSのプロセスや通信のログを収集・監視し、サイバー攻撃（マルウェアの潜伏など）を早期検知して初動対応（ネットワーク遮断等）を支援するソリューション。", "etymology": "Endpoint（末端端末） Detection and Response（検知と対応）。", "exam": "ゼロトラストやランサムウェア対策のトレンド用語として近年超頻出！「エンドポイントのログを収集」「侵入されることを前提とし、感染後の迅速な検知・対応を行う」がキーワードです。", "def30": "端末の動作を常時監視し、マルウェア侵入後の早期検知と対応を行うソフト。（35文字）"}, {"id": 108, "term": "SIEM\n(Security Information and Event Management)", "summary": "・FWやプロキシ、サーバーなど複数の機器のセキュリティログを一元的に集約し、相関分析によって高度なサイバー攻撃の予兆を検知するシステム。", "keywords": "・ログの集約・一元管理\n・相関分析\n・攻撃の予兆検知\n・SOCでの活用\n・リアルタイム分析", "analogy": "「様々な監視カメラの映像を集めて名探偵が推理するシステム」です。\n「FWのアクセス遮断」と「DBサーバーのログイン失敗」という別々のログを掛け合わせて分析し、「これは標的型攻撃の前兆だ！」と見抜きます。", "details": "ネットワーク機器やサーバー、アプリケーションから出力されるログを一元的に収集し、相関分析（複数のイベントの組み合わせ分析）を行うことで、単一の機器では見抜けない高度なサイバー攻撃を検知するシステム。", "etymology": "Security Information and Event Management（セキュリティ情報とイベントの管理）。", "exam": "セキュリティ運用（SOC）の文脈で頻出。「複数の機器のログを集約・相関分析する」というキーワードが出たら、SIEMを選んでください。", "def30": "複数機器のログを一元集約・相関分析し、高度な攻撃の予兆を検知するシステム。（37文字）"}, {"id": 109, "term": "セキュアブート\n(Secure Boot)", "summary": "・PCの起動時に、OSやブートローダのデジタル署名を検証するUEFIの機能。\n・改ざんされたソフトの実行を防ぎ、OS起動前に感染するマルウェア（ルートキット等）をブロックする。", "keywords": "・UEFI\n・デジタル署名の検証\n・OS起動前\n・マルウェア実行防止\n・ルートキット", "analogy": "「オフィスの入り口の入館証チェック」です。\n会社（PC）が稼働し始める時、偽物の社員（マルウェア）が紛れ込まないように、入り口のガードマン（UEFI）が「社長のハンコ（デジタル署名）」が押された本物の入館証を持っているかチェックしてから中に入れます。", "details": "PCの起動時に、実行されるソフトウェア（ブートローダやOSカーネル等）の「デジタル署名」を検証し、正当なソフトウェアだけを実行するUEFIのセキュリティ機能。", "etymology": "Secure（安全な）＋ Boot（起動）。\nPCの電源を入れてからOSが立ち上がるまでのプロセス（ブート）を安全に行う仕組み。", "exam": "セキュリティ分野で出題。\n「OS起動前」に感染する「ルートキット」などの悪質なマルウェアを防ぐための仕組みとして問われます。問題文に「UEFI」「デジタル署名の検証」とあればセキュアブートが正解です。", "def30": "起動時にデジタル署名を検証し、不正なOSの実行を防ぐ機能。（29文字）"}, {"id": 110, "term": "ゼロトラスト\n(Zero Trust)", "summary": "・「社内ネットワークだから安全」という境界型防御を捨て、「すべてのアクセスを一切信用せず毎回認証・検証する」という最新のセキュリティ概念。", "keywords": "・「何も信用しない（Never Trust\n・Always Verify）」\n・境界型防御の限界\n・アイデンティティ検証\n・テレワーク普及\n・CASB/EDR", "analogy": "「社内の人間であっても、部屋に入るたびに毎回顔認証とIDチェックをする厳重なオフィス」です。\n昔は「社内（境界の内側）に入れば安全」でしたが、どこからでも侵入され得る現代では「誰も信用せず毎回確認」します。", "details": "社内と社外の「境界」で防ぐ従来の境界型セキュリティに対し、社内ネットワーク内部からのアクセスであっても信用せず、すべての通信・デバイス・ユーザーを常に認証・検証するセキュリティ考え方。", "etymology": "Zero（ゼロ）＋ Trust（信頼）。\n信用（Trust）をゼロ（Zero）にして、常に疑って検証するという意味。", "exam": "近年の応用情報・情報処理安全確保支援士で出題が急増しているトレンド用語。\n「テレワークの普及」「クラウド利用」「境界型防御の限界」「Never Trust, Always Verify（決して信用せず、常に検証せよ）」が合言葉です。", "def30": "社内外を問わずすべてのアクセスを信用せず毎回検証するセキュリティ思想。（35文字）"}, {"id": 111, "term": "SPF\n(Sender Policy Framework)", "summary": "・電子メールの送信元ドメインのなりすましを防ぐ送信ドメイン認証技術。\n・DNSのTXTレコードに送信許可IPアドレスを登録しておく。", "keywords": "・送信ドメイン認証\n・なりすましメール対策\n・DNS TXTレコード\n・送信元IPアドレス確認\n・DKIM/DMARC", "analogy": "「差出人の住所印鑑登録」です。\n『このメールアドレスからは、このIPアドレスのサーバーからしか送りません』と役所（DNS）に登録しておき、受取人が照合します。", "details": "電子メールの差出人アドレスの偽装（なりすまし）を防止する認証技術。ドメインの所有者がDNSサーバーに正当なメールサーバーのIPアドレスを登録（SPFレコード）しておき、受信側が照合する。", "etymology": "Sender Policy Framework（送信者ポリシー枠組み）。", "exam": "メールセキュリティの超超頻出！「送信元IPアドレスとDNSに登録されたIPアドレスを比較してなりすましを検知する技術＝SPF」「メール本体に電子署名を付与する＝DKIM」。", "def30": "送信元IPアドレスをDNSに登録し電子メールのなりすましを防ぐ認証技術。（36文字）"}, {"id": 112, "term": "デジタルフォレンジック", "summary": "・サイバー犯罪や不正行為が起きた際、PCやスマホ等のデジタル機器から法的証拠となるデータを保全・抽出・分析する技術。", "keywords": "・証拠保全\n・データの復元\n・ログ解析\n・ハッシュ値による同一性証明\n・インシデント調査", "analogy": "「サイバー空間の鑑識（科捜研）」です。\n犯罪者が消去したファイルや検索履歴を復元したり、改ざんされていないことをハッシュ値で証明しながら、法廷で使えるデジタル証拠を集めます。", "details": "情報セキュリティインシデントや犯罪が発生した際に、原因究明や法的証拠を確保するために、コンピュータやネットワークの記録（ログ、ディスクの残留データなど）を正当な手順で収集・解析する一連の技術と手続き。", "etymology": "Digital（デジタルの）＋ Forensics（法医学、科学捜査）。", "exam": "インシデント対応の分野で出題。「法的証拠能力を保つためにデータをそのままコピー（保全）する」「消去されたデータを復元・解析する技術」という説明が問われます。", "def30": "サイバー犯罪調査のため、デジタル機器から法的証拠を保全・解析する技術。（35文字）"}, {"id": 113, "term": "CC\n(コモンクライテリア・ISO/IEC 15408)", "summary": "・IT関連製品やシステムのセキュリティ妥当性を、客観的に評価・認証するための国際標準規格（ISO/IEC 15408）。", "keywords": "・ISO/IEC 15408\n・セキュリティ評価基準\n・ST（評価対象セキュリティターゲット）\n・PP（プロテクションプロファイル）\n・EAL（評価保証レベル）", "analogy": "「セキュリティ製品の国際安全格付け証明書」です。\n「この防犯カメラ（製品）のセキュリティは世界基準レベルで安全です」と第三者機関が認証するための統一基準です。", "details": "IT製品やシステムのセキュリティ評価に関する国際標準規格（ISO/IEC 15408）。調達者が求めるセキュリティ要件（PP）や開発者の評価対象（ST）に基づき、第三者機関が保証レベル（EAL）を認定する。", "etymology": "Common Criteria（共通評価基準）。", "exam": "セキュリティ評価の分野で出題。「IT製品やシステムのセキュリティ機能を第三者機関が国際標準（ISO/IEC 15408）に基づき評価・認証する基準＝コモンクライテリア（CC）」。", "def30": "IT製品やシステムのセキュリティ機能を客観的に評価・認証する国際標準規格。（37文字）"}, {"id": 114, "term": "SBOM\n(Software Bill of Materials)", "summary": "・ソフトウェアを構成するコンポーネント（ライブラリやオープンソース）の名称、バージョン、依存関係、ライセンス等を一覧化した「ソフトウェア成分表」。", "keywords": "・ソフトウェア部品表\n・オープンソース（OSS）管理\n・脆弱性管理（Log4j等）\n・サプライチェーンセキュリティ\n・透明性", "analogy": "「食品の原材料・アレルギー表示（成分表）」です。\n『加工食品（アプリ）』の中にどんな材料（ライブラリ）が入っているか明記しておくことで、毒（脆弱性）が見つかった時にすぐ対処できます。", "details": "ソフトウェアを構成するサードパーティ製ライブラリやオープンソースソフトウェア（OSS）の名称、バージョン、発行者、依存関係などの情報を明記した成分表ドキュメント。サプライチェーン全体の脆弱性把握に活用される。", "etymology": "Software Bill of Materials（ソフトウェアの材料一覧表）。", "exam": "最新のセキュリティ・ソフトウェア管理トレンド問題！「ソフトウェアに含まれるOSSやライブラリの情報をリスト化し、脆弱性やライセンスリスクを管理する構成表＝SBOM」がキーワードです。", "def30": "ソフトウェアを構成する部品やライブラリの名称・依存関係を明記した成分表。（36文字）"}, {"id": 115, "term": "ISMS\n(情報セキュリティマネジメントシステム)", "summary": "・組織が情報セキュリティ（機密性・完全性・可用性）を管理し、継続的に改善（PDCA）するための仕組み。\n・ISO/IEC 27001が基準。", "keywords": "・PDCAサイクル\n・機密性・完全性・可用性\n・ISO/IEC 27001\n・リスクアセスメント\n・トップマネジメントの責任", "analogy": "「会社のセキュリティルールブックの運用体制」です。\nルールを作って終わりではなく、計画（P）→実行（D）→点検（C）→改善（A）のサイクルを回して、常に安全な状態をアップデートし続けます。", "details": "組織が保護すべき情報資産について、「機密性（漏らさない）」「完全性（改ざんされない）」「可用性（いつでも使える）」の3要素をバランス良く維持・改善するための包括的な管理体制。ISO/IEC 27001として標準化されている。", "etymology": "Information Security Management System。", "exam": "マネジメント分野で頻出！「PDCAサイクルによる継続的改善」「機密性・完全性・可用性の維持」「適合性評価制度（JIS Q 27001）」がキーワードです。", "def30": "情報の機密性・完全性・可用性を維持し、PDCAで継続改善する管理体制。（35文字）"}, {"id": 116, "term": "リスク特定", "summary": "・情報資産に対する脅威と脆弱性を洗い出し、リスクを発見する最初のステップ。\n・「どんな危険（何が起きる可能性）があるか」をリストアップする作業。", "keywords": "・情報資産の洗い出し\n・脅威と脆弱性\n・発見\n・認識\n・記述", "analogy": "「家にどんな泥棒（脅威）が入る可能性があるか」「鍵が壊れている窓（脆弱性）はないか」をリストアップすることです。「何が起きる可能性があるか」を見つけ出します。", "details": "組織が持つ「情報資産」を洗い出し、それに対する「脅威（攻撃や災害）」と「脆弱性（弱点）」を認識して、どのようなリスクが存在するかを発見・記述するプロセス。", "etymology": "Risk Identification（リスクを見分ける、特定する）。\n組織にどんなリスクが存在するかを見つけ出す最初のステップ。", "exam": "リスクアセスメントの「最初のプロセス」として問われます。リスクを構成する「情報資産」「脅威」「脆弱性」の3要素を漏れなく洗い出すことが重要です。", "def30": "資産への脅威と脆弱性を洗い出し、リスクを見つけ出すプロセス。（30文字）"}, {"id": 117, "term": "リスク分析", "summary": "・特定されたリスクの「発生確率」と「影響度」を算出し、大きさを測るステップ。\n・リスクレベル（危険度のスコア）を決定し、次の「リスク評価」につなげる。", "keywords": "・発生確率（可能性）\n・影響度（被害の大きさ）\n・リスクレベルの決定\n・定量的・定性的", "analogy": "リストアップした泥棒の危険について、「その窓から泥棒が入る確率は何％か」「盗まれたら何万円の損害になるか」を計算し、危険度のスコアを出すことです。", "details": "「リスク特定」で見つかったリスクに対して、それが実際に発生する可能性（確率）と、発生した際の影響の大きさ（被害額など）を算出し、リスクの大きさ（リスクレベル）を決定するプロセス。", "etymology": "Risk Analysis（リスクを分析・解剖する）。\n特定されたリスクについて、その性質を理解し、大きさを測るステップ。", "exam": "リスク特定の後に行われます。「影響度 × 発生確率」でリスクレベルを算出する計算問題や、数値化する「定量的分析」、ランク付けする「定性的分析」の手法が問われます。", "def30": "発生確率と影響度を分析して、リスクレベルを決定するプロセス。（30文字）"}, {"id": 118, "term": "CSIRT・SOC", "summary": "・CSIRTはセキュリティインシデント発生時の「対応・収束」を担う組織。\n・SOCは24時間365日ログ監視と「検知」を専門に行う組織。", "keywords": "・CSIRT（インシデント対応チーム）\n・SOC（24時間ログ監視）\n・報告・復旧\n・ログ分析\n・セキュリティ組織", "analogy": "「警察と警備会社監視ルームの違い」です。\nSOCは防犯カメラを24時間監視して「異常発見！」と報知する監視室。CSIRTは事件発生時に現場へ急行して犯人対応や被害拡大防止を行う対策本部です。", "details": "・CSIRT（シーサート）：セキュリティ事故（インシデント）が発生した際に、状況把握・原因究明・被害拡大防止を行う専門チーム。\n・SOC（ソック）：ネットワークや機器のログを24時間体制で監視し、攻撃を早期検知する専門組織。", "etymology": "Computer Security Incident Response Team（CSIRT） / Security Operations Center（SOC）。", "exam": "セキュリティ管理・組織の分野で出題。\n「インシデント発生時の対応・連絡・復旧＝CSIRT」「24時間365日のログ監視・検知＝SOC」という役割の分担の違いを問う問題が頻出です。", "def30": "SOCは24時間監視で検知し、CSIRTは事故発生時に対応する組織。（34文字）"}, {"id": 119, "term": "BCP・BCM\n(事業継続計画)", "summary": "・BCPはテロや災害時に事業を中断させず継続（または早期復旧）するための「計画」。\n・BCMはその計画を運用・改善していく「管理活動（マネジメント）」。", "keywords": "・BCP（事業継続計画）\n・BCM（事業継続管理）\n・RTO（目標復旧時間）\n・RLO（目標復旧レベル）\n・中核事業の継続", "analogy": "「大地震が起きた時の会社生き残りマニュアル（BCP）と、それを毎年訓練して改訂する活動（BCM）」です。\n非常時でも大切な事業を止めないための準備です。", "details": "自然災害やサイバー攻撃などの緊急事態において、重要事業の中断を防ぎ、万一中断した場合でも目標時間内（RTO）に復旧させるための計画（BCP）と、それを策定・運用・改善する一連の管理プロセス（BCM）。", "etymology": "Business Continuity Plan（計画） / Business Continuity Management（管理）。", "exam": "マネジメント・ストラテジ分野で頻出。\n「RTO（目標復旧時間：いつまでに直すか）」「RPO（目標復旧時点：いつのデータまで戻すか）」という専門用語や、BCP（計画）とBCM（管理活動）の違いが問われます。", "def30": "災害時等に重要事業を中断させず早期復旧させる計画と管理活動。（30文字）"}, {"id": 120, "term": "システム開発工程\n(ウォーターフォール)", "summary": "・要件定義→外部設計→内部設計→実装→テストの順に進める開発の基本手順。\n・外部設計はユーザー向け（画面等）、内部設計は開発者向け（処理等）の設計を行う。", "keywords": "・要件定義\n・外部設計(基本設計)\n・内部設計(詳細設計)\n・実装\n・テスト\n・V字モデル", "analogy": "「家づくり」と同じです。\n・要件定義：3LDKで対面キッチンがいいと要望をまとめる。\n・外部設計：間取りや外観図を作る（施主が見る）。\n・内部設計：壁の中の配管や骨組みを設計する（大工が見る）。\n・実装：実際に家を建てる。", "details": "システム構築における一連の手順。\n1.要件定義（何を作るか）\n2.外部設計（外から見える画面等の設計）\n3.内部設計（中の処理の設計）\n4.実装（プログラミング）\n5.テスト（動作確認）", "etymology": "System Development Life Cycle (SDLC) / Waterfall.\n水が滝（ウォーターフォール）を落ちるように、要件定義→設計→実装→テストと順番に後戻りせず進める手法。", "exam": "システム開発分野で頻出。\n「ユーザーの要件をまとめるのはどの工程か？」といった役割のほか、テスト工程との対応関係を示す「V字モデル（例：内部設計の検証は単体テストで行う）」が超頻出。", "def30": "要件定義から設計、実装、テストへと順番に進める開発の手順。（29文字）"}, {"id": 121, "term": "アジャイル開発\n(スクラム)", "summary": "・短期間の開発サイクル（イテレーション/スプリント）を繰り返し、仕様変更に柔軟に対応する開発手法。\n・スクラムではデイリースクラムやプロダクトバックログを用いる。", "keywords": "・イテレーション（スプリント）\n・仕様変更に柔軟\n・スクラム\n・プロダクトバックログ\n・ウォーターフォールとの違い", "analogy": "「小さな試作（プロトタイプ）を1〜2週間ごとに何度も作って見せる開発スタイル」です。\n最初に仕様を固めず、作りながらユーザーの要望を聞いてどんどん良いものに改良していきます。", "details": "システムを小さく機能単位に分け、1週間〜1ヶ月程度の短い期間（イテレーション）で設計・開発・テスト・リリースを繰り返す開発手法。途中の要求変更に強い。", "etymology": "Agile（素早い、機敏な）。\n環境やユーザー要望の変化に素早く（アジャイルに）適応して開発を進める手法。", "exam": "システム開発技術の分野で超頻出。\n従来のウォーターフォール開発（計画重視・後戻り不能）との比較や、アジャイルの代表的フレームワークである「スクラム（プロダクトオーナー、スクラムマスター、デイリースクラム等）」の役割が問われます。", "def30": "短いサイクルを繰り返し、仕様変更に柔軟に対応する開発手法。（29文字）"}, {"id": 122, "term": "エピック・ユーザーストーリー\n(アジャイル要件)", "summary": "・アジャイル開発における要求の単位表現。\n・ユーザーストーリー（ユーザー視点での簡潔な機能要望）と、それをまとめた大きな機能群（エピック）。", "keywords": "・アジャイル開発\n・プロダクトバックログ\n・ユーザーストーリー（Who/What/Why）\n・エピック（大テーマ）\n・スプリント", "analogy": "「旅行の全体目標と個別プラン」です。\n『ハワイ旅行を楽しむ』という大きな目標（エピック）と、『海でサーフィンがしたい』『美味しいパンケーキが食べたい』という具体的なお願い（ユーザーストーリー）の関係です。", "details": "アジャイル開発における要件定義の単位。\n・ユーザーストーリー：「＜誰が＞＜何をしたい＞＜なぜなら＞」の形式で記述されるエンドユーザー視点の要望。\n・エピック：複数のユーザーストーリーを統合した大きな機能のかたまり。", "etymology": "Epic（叙事詩、大作） ＋ User Story。", "exam": "アジャイル開発の要件管理で出題。「ユーザー視点での価値を表す短い要望文＝ユーザーストーリー」「それを束ねた大きなテーマ＝エピック」。", "def30": "アジャイルでの大きな機能単位(エピック)とユーザー視点の具体要望(ストーリー)。（40文字）"}, {"id": 123, "term": "インセプションデッキ", "summary": "・アジャイル開発の立ち上げ時に、プロジェクトの目的、背景、課題、トレードオフ等をチーム全員で共有するために作成する10の質問・回答シート。", "keywords": "・アジャイルプロジェクト開始時\n・10の問い\n・プロジェクトのビジョン共有\n・トレードオフのスライダー\n・エレベーターピッチ", "analogy": "「プロジェクトの航海前チェックシート」です。\n船出の前に「なぜこの旅をするのか」「嵐が来たら何を優先するか（予算か納期か）」を10枚の紙（デッキ）にまとめて全員で意思統一します。", "details": "アジャイル開発（スクラム等）の初期段階で、プロジェクトの目的・全体像・チームの合意事項を明確にするために作成するドキュメント（10個の問いと答え）。エレベーターピッチや「夜も眠れない問題」等を含む。", "etymology": "Inception Deck（開始時のカードデッキ）。", "exam": "アジャイル開発のマネジメント手法で出題。「プロジェクトの目的やトレードオフの優先順位をチーム全員で視覚化・共有するツール＝インセプションデッキ」。", "def30": "アジャイル開始時にプロジェクトの目的や優先順位をチームで共有する10の課題。（38文字）"}, {"id": 124, "term": "テスト駆動開発\n(TDD)", "summary": "・プログラムを書く「前」に、まずテストコード（期待される動作）を書き、そのテストに合格するように実装を行っていく開発手法。", "keywords": "・テストファースト\n・アジャイル開発\n・XP（エクストリームプログラミング）\n・リファクタリング", "analogy": "「ゴールテープを先に引いてから走り出す」開発です。\n「1+1を入れたら2が返ってくる」というテストを先に作り、最初はエラーになるのを確認してから、2が返ってくるようにプログラムの中身を作ります。", "details": "アジャイル開発（XPなど）で推奨される手法。テストケースの作成 → テストが失敗することの確認 → テストを通る最小限のコードの実装 → リファクタリング、という短いサイクルを繰り返す。", "etymology": "Test-Driven Development（テストによって駆動・先導される開発）。", "exam": "開発手法の分野で出題。「実装を行う前にテストコードを記述する」「テストファースト」というキーワードが出たらTDDです。アジャイル開発と関連付けられます。", "def30": "プログラムを記述する前にテストコードを作成し、それに合格するよう実装する手法。（39文字）"}, {"id": 125, "term": "リバースエンジニアリング", "summary": "・既存のプログラム（完成品）を解析して、そこから仕様書や設計図を導き出す技術。\n・フォワードエンジニアリングはその逆（設計図からプログラム作成）。", "keywords": "・ソースコード解析\n・仕様書の復元\n・フォワードエンジニアリング（逆のプロセス）\n・既存システムの解析", "analogy": "「完成した料理を食べて、レシピを逆算して書き起こす」作業です。\n昔作られて仕様書が失われたシステムの中身を読み解き、どういう仕組みで動いているかを文書化します。", "details": "ソフトウェア開発ツール等を用い、既存の実行可能なプログラムやソースコードを解析し、システムの構造や仕様、設計情報を抽出する手法。保守やレガシーシステムの移行時に用いられる。", "etymology": "Reverse（逆方向の） Engineering（工学）。", "exam": "開発技術分野で出題。「既存プログラムを解析して仕様を導出する＝リバース」「リバースで得た仕様を元に新しいシステムを構築する＝フォワード」というプロセスが問われます。", "def30": "既存の完成したプログラムを解析し、設計図や仕様書を逆算して導き出す手法。（36文字）"}, {"id": 126, "term": "モジュール結合度・モジュール強度", "summary": "・良いプログラム設計の指標。「結合度は弱く（疎結合）」「強度は強く（高凝集）」するのが理想。\n・結合度はモジュール間の関係の強さ、強度はモジュール内部の機能的まとまり。", "keywords": "・結合度（データ結合が最良\n・内容結合が最悪）\n・強度（暗合的強度が最悪\n・機能的強度が最良）\n・独立性の向上", "analogy": "「理想の会社組織」です。\n・結合度が弱い：部署間のやり取りがシンプルで、他部署の変更に影響されない（良い）。\n・強度が強い：1つの部署が「営業だけ」など専門的でまとまっている（良い）。", "details": "ソフトウェアのモジュール（部品）の独立性を測る指標。モジュール間のデータの受け渡しが少ないほど「結合度が弱い（疎結合）」、モジュール内部の機能が一つの目的のみに集中しているほど「強度が強い（高凝集）」とされ、保守性が高まる。", "etymology": "Module Coupling（結合度） / Module Cohesion（凝集度・強度）。", "exam": "ソフトウェア設計分野で超頻出！「モジュール結合度は『弱く』、モジュール強度は『強く』設計する」という原則と、最強/最弱の組み合わせ（データ結合が一番良い、機能的強度が一番良い）が問われます。", "def30": "部品間の依存を減らし（結合度を弱く）、内部の目的を一つに絞る（強度を強く）設計。（40文字）"}, {"term": "モジュール結合度の受渡レベル\n(データ結合〜内容結合)", "summary": "・モジュール間でのデータや制御の受け渡し方式（結合度）を強度順に並べた6段階の分類。\n・値のみを渡す「データ結合（最良）」を目指し、内部を直接参照する「内容結合（最悪）」を避ける。", "keywords": "・データ結合（最良：値のみ受渡し）\n・スタンプ結合（構造体受渡し）\n・制御結合（フラグ受渡し）\n・外部結合 / 共通結合（共有変数・メモリ）\n・内容結合（最悪：内部直接参照）", "analogy": "「他人に作業を頼む時の情報の渡し方」です。\n・データ結合：『住所（値だけ）』を渡す（最高）\n・スタンプ結合：『手帳（構造体）ごと』渡すが読むのは住所だけ（少し無駄）\n・制御結合：『YES/NO（フラグ）』で相手の指示を制御する\n・内容結合：相手の部屋（内部領域）に勝手に入って作業する（最悪）", "details": "プログラムの独立性を評価する指標。受渡す情報が限定的であるほど結合度が弱く（疎結合）なり、システムの変更による影響が他モジュールに及びにくいため、保守性や再利用性が大幅に向上する。", "etymology": "Module Coupling（モジュールの結合・引っ掛かり）。\n「モジュール同士がどのレベル（値・構造体・制御・メモリ）で繋がっているか」を示す。", "exam": "ソフトウェア設計・モジュール分割分野で超頻出！\n・6つの結合度の順番（データ ＞ スタンプ ＞ 制御 ＞ 外部 ＞ 共通 ＞ 内容）の暗記\n・「最も独立性が高く変更に強い結合度はどれか（答え：データ結合）」\n・「構造体データを受け渡す結合度はどれか（答え：スタンプ結合）」\n・「処理を制御するフラグを受け渡す結合度はどれか（答え：制御結合）」", "def30": "データの受渡レベルで6段階に分類され、データ結合が最も良い。（30文字）", "id": 127}, {"id": 128, "term": "ソフトウェアの分析・設計技法", "summary": "・要求仕様を分析し、拡張性・保守性の高いソフトウェア構造へ落とし込む一連の手法（構造化技法・オブジェクト指向など）。\n・プロセス中心（DFD）、データ中心（E-R図）、オブジェクト指向（UML）などのアプローチに分類される。", "keywords": "・構造化分析・設計技法（DFD、モジュール分割）\n・データ中心アプローチ（DOA・E-R図）\n・オブジェクト指向分析・設計（OOA/OOD・UML）\n・モジュール独立性（結合度は弱く、強度は強く）\n・アーキテクチャパターン（MVC等）", "analogy": "「家を建てる際の『要望整理（分析）』と『設計図作成（設計）』の手順・ルール」です。\nいきなり家を建て始めるのではなく、「住人が何をしたいか（要求分析）」を整理し、「部屋や配管をどう配置するか（モジュール分割）」を共通の図法やルールを使って設計するノウハウ集です。", "details": "ユーザーの曖昧な要求を整理・モデル化する「分析」と、それに基づきプログラムの構成・モジュール分割・インターフェースを定義する「設計」の技法群。代表的なアプローチとして、プロセス中心（DFD）、データ中心（E-R図）、オブジェクト指向（UML）が存在する。", "etymology": "Software Analysis & Design Techniques。Analysis（分解し分析する）とDesign（目的の形に設計する）技法。", "exam": "ソフトウェア工学分野で頻出！\n・手法とツールの対応（構造化＝DFD、データ中心＝E-R図、オブジェクト指向＝UML）\n・モジュール評価基準（結合度は弱く、強度は強く）\n・体系理解問題として問われます。", "def30": "要求を分析し保守性や拡張性の高いソフトウェア構造を設計する手法。（33文字）"}, {"term": "DOA\n(データ中心アプローチ)", "summary": "・業務プロセス（処理）ではなく「データ（データ構造）」を中心にシステムを設計する手法。\n・データの構造は処理に比べて変化しにくいため、システムの保守性や拡張性が高くなる。", "keywords": "・データ構造のモデル化\n・E-R図（実体関連図）\n・データの一元管理・重複排除\n・プロセス中心アプローチ（POA/DFD）との対比", "analogy": "「家を建てる際の『柱や土台（データ）』から設計するやり方」です。\n部屋の使い方や家族の動き（業務処理）は時代とともに変わりますが、しっかりした土台（データ構造）を最初に作っておけば、後から部屋の模様替え（処理の変更）がとても簡単にできます。", "details": "対象領域に存在するデータとその関係性（実体と関連）に着目し、概念データモデル（E-R図など）を構築してから、それを操作する業務プロセス（処理）を設計するアプローチ。業務変更に伴うシステム改修を最小限に抑える効果がある。", "etymology": "Data（データ）＋ Oriented（指向の・中心にした）＋ Approach（手法）。\n「処理よりもデータを第一中心に考えてシステム設計を行う手法」という意味。", "exam": "システム開発技術・データベース設計分野で出題されます。\n・従来の「プロセス中心アプローチ（POA：DFDなどを用いる）」との比較問題\n・概念設計フェーズで「E-R図」を作成し正規化を行う一連の流れ\n・業務データの標準化・重複排除によるシステム保守性の向上", "def30": "業務のデータ構造に着目し保守性の高いシステムを設計する手法。（30文字）", "id": 129}, {"id": 130, "term": "ソフトウェアアーキテクチャパターン\n(MVC・レイヤード)", "summary": "・ソフトウェアの全体構造における典型的な設計パターン。\n・MVC（Model:データ, View:画面, Controller:制御）やレイヤード層構造など。", "keywords": "・MVCパターン（Model-View-Controller）\n・レイヤードアーキテクチャ\n・コンポーネント分離\n・再利用性・保守性向上", "analogy": "「レストランの役割分担」です。\n・Model：厨房（料理・データ作成）\n・View：メニューや料理の見た目（画面）\n・Controller：注文を取るウェイター（制御）", "details": "大規模なソフトウェア開発において、保守性・拡張性を高めるために検証されたシステム構造のひな型。\n・MVC：データ処理（Model）、ユーザー表示（View）、全体制御（Controller）の3つに明確に分離する手法。", "etymology": "Software Architecture Pattern。", "exam": "ソフトウェア設計で出題。「画面表示、ビジネスロジック、データ制御を分離して開発する構造パターン＝MVCパターン」が代表例。", "def30": "システム構造のひな型。MVCパターン等、画面・処理・制御を分離し設計する。（37文字）"}, {"id": 131, "term": "EJB\n(Enterprise JavaBeans)", "summary": "・Java EE（現 Jakarta EE）でサーバー側の業務処理を部品化する標準規格。\n・トランザクション制御やセキュリティ管理などをEJBコンテナに自動任せできる。", "keywords": "・Java EE / Jakarta EE\n・コンポーネント化（部品化）\n・セッションビーン（Stateless / Stateful）\n・宣言的トランザクション制御 (CMT)", "analogy": "「ホテルの各種専門サービスを提供する裏方システム」です。\nシェフ（開発者）は料理の味（ビジネスロジック）作りにだけ集中し、会計・清掃・警備などの面倒な管理業務はすべてホテル（EJBコンテナ）が自動で引き受けてくれる仕組みです。", "details": "企業向けシステムにおいて、データベース接続、トランザクション制御、分散処理、マルチスレッド管理などの複雑なインフラ処理を隠蔽し、業務ロジックの再利用性と安全性を高めるサーバーサイドコンポーネント仕様。", "etymology": "Enterprise（企業用の・大規模な）＋ Java ＋ Beans（再利用可能な部品）。\n「企業の大規模システムで使い回せるJavaプログラムの部品」という意味。", "exam": "ソフトウェア開発・システムアーキテクチャ分野で出題。\n・状態を保持しないStateless Session Beanの軽量性・スケール性の特徴\n・コンテナが自動でコミット/ロールバックを行う宣言的トランザクション制御\n・Spring FrameworkやJPAへの移行といった歴史的背景", "def30": "サーバー側の業務処理を部品化し、自動管理するJavaの標準規格。（32文字）"}, {"id": 132, "term": "ユースケース図\n(Use Case Diagram)", "summary": "・利用者（アクター）の視点から、システムが提供する機能を示すUML図。\n・システムの要件定義（要求分析）の初期段階で作成され、何ができるかを明確にする。", "keywords": "・利用者からの視点\n・システムが提供する機能\n・アクター\n・要求分析", "analogy": "「ATMの機能紹介ポスター」です。\n「利用客（棒人間）」から線が伸びていて、「引き出し」「残高照会」という丸印と結ばれているような、誰が何をするシステムなのかが一目でわかる図です。", "details": "「ユーザー（アクター）」がシステムを使って「何ができるか」を外側からの視点で示す図。システムの要件定義（要求分析）で作成される。", "etymology": "Use Case（利用事例・使い道）＋ Diagram（図）。\nユーザーがそのシステムを「どう利用するか（使い道）」を示す図。", "exam": "ソフトウェア開発の「UML」分野で出題。\n「システムの利用者の視点」「要求をモデル化」というキーワードが出たらユースケース図です。外部の利用者を「アクター」と呼ぶことも問われます。", "def30": "利用者の視点から、システムが提供する機能や要件を示す図。（28文字）"}, {"id": 133, "term": "クラス図\n(Class Diagram)", "summary": "・システム内のモノ（クラス）が持つ属性・操作と、クラス間の静的な関係を示すUML図。\n・オブジェクト指向設計における最も基本かつ重要な図である。", "keywords": "・オブジェクト指向\n・概念モデル\n・属性と操作\n・関係（関連・集約・汎化）", "analogy": "「動物図鑑の分類表」です。\n「動物」という大分類（クラス）があり、そこに「犬」「猫」という小分類がぶら下がるような、システム内のデータの種類と関係性を定義した図です。", "details": "システムに登場するモノや概念（クラス）が持つデータ（属性）や振る舞い（操作）、およびクラス間の静的な関係（親子関係など）を示す図。", "etymology": "Class（分類・階級・種類）＋ Diagram（図）。\nシステムに登場するモノや概念を「種類（クラス）」ごとに分類し、構造を示す図。", "exam": "ソフトウェア開発の「UML」分野で超頻出。\n「属性と操作」「静的な構造」「オブジェクト指向の概念モデリング」というキーワードが出たら一発でクラス図です。", "def30": "クラスが持つ属性・操作と、クラス間の静的な関係を示す図。（28文字）"}, {"id": 134, "term": "シーケンス図\n(Sequence Diagram)", "summary": "・オブジェクト間のメッセージのやり取りを「時系列（上から下）」に表現する動的なUML図。\n・ライフライン（破線）や実行指定（長方形）を用いる。", "keywords": "・時系列（時間経過）\n・オブジェクト間のメッセージ\n・動的モデル\n・ライフライン\n・同期/非同期通信", "analogy": "「映画の台本（タイムスケジュール）」です。\n「ユーザー」が「画面」のボタンを押し、画面が「サーバー」にデータを送り、サーバーが「DB」に書き込む…という時間の流れに沿ったメッセージのキャッチボールを描きます。", "details": "UMLにおける動的モデリング図の一つ。オブジェクト同士が時間経過に伴ってどのようなメッセージを相互に送信・受信するかを、縦軸の時系列に沿って視覚的に表現する。", "etymology": "Sequence（順序、配列、時系列）＋ Diagram（図）。\n処理の順序（シーケンス）を時間の流れに沿って表す図。", "exam": "UML分野で「クラス図」と並ぶ超頻出項目！\n「時間の経過に伴うメッセージのやり取り」「動的な挙動を表す」「ライフライン」という説明があれば、一発でシーケンス図が正解です。", "def30": "オブジェクト間のメッセージのやり取りを時系列に表す動的UML図。（32文字）"}, {"id": 135, "term": "コンポーネント図\n(Component Diagram)", "summary": "・ソフトウェアの部品（コンポーネント）同士の依存関係や接続を示すUML図。\n・ハードウェアを示す配置図とは異なり、ソフトウェア内部の静的な構造を表す。", "keywords": "・ソフトウェアの部品\n・モジュール間の依存関係\n・インターフェース\n・実装", "analogy": "「家を建てる時の建材の組み合わせ図」です。\n「壁パネル」と「窓枠」という部品（ソフトのモジュール）が、どういう規格（インターフェース）でくっつくかを示します。", "details": "システムを構成するソフトウェアの部品（コンポーネント）同士が、どのように依存し合い、接続されているかを示す静的な構造図。", "etymology": "Component（部品・構成要素）＋ Diagram（図）。\nシステムを構成するソフトウェアの「部品」のつながりを示す図。", "exam": "ソフトウェア開発の「UML」分野で出題。\n「配置図」との違いがよく問われます。「物理的なハードウェア」なら配置図、「ソフトウェアの部品同士の依存関係」ならコンポーネント図です。", "def30": "ソフトウェアの部品同士の依存関係や接続を示す静的な構造図。（29文字）"}, {"id": 136, "term": "配置図\n(Deployment Diagram)", "summary": "・ソフトウェア（コンポーネント）を、どのハードウェア（ノード）に配置するかを示すUML図。\n・システムの物理的な構成や、ハードウェア間のネットワーク接続状況を表現する。", "keywords": "・実行環境に割り付ける\n・ハードウェア構成\n・物理的な配置\n・ノード", "analogy": "「システムの引っ越し・家具の配置図」です。\n「このWebアプリ（ソフト）は、クラウドのWebサーバー（ハード）に置く」「データベース（ソフト）は、社内のDBサーバー（ハード）に置く」といった、ソフトとハードの紐付けを設計図にしたものです。", "details": "システムを構成するハードウェア（ノード）と、その上で稼働するソフトウェア（コンポーネント）の物理的な配置関係や接続状況をモデル化するUML図。", "etymology": "Deployment（配置、展開）＋ Diagram（図）。\n完成したソフトウェア（コンポーネント）を、実際に稼働させるハードウェア（サーバーやPC）に「配置・展開」する様子を示す図。", "exam": "ソフトウェア開発の「UML」分野で出題。\n問題文に「稼働するコンポーネントを実行環境に割り付ける」「ハードウェアの物理的な構成」というキーワードが出たら、「配置図」が正解です。（コンポーネント図やクラス図との引っかけに注意）", "def30": "ソフトウェアを実行するハードウェアの物理的な配置を示す図。（29文字）"}, {"id": 137, "term": "帳票設計", "summary": "・システムが入出力する画面やレポート（請求書等）のレイアウトを設計する作業。\n・ユーザーの目に直接触れる部分のため、「外部設計（基本設計）」の段階で行われる。", "keywords": "・外部設計（基本設計）\n・ヒューマンインターフェース\n・出力フォーマット\n・ユーザビリティ", "analogy": "「レシートや注文用紙のデザイン決め」です。\nどの位置に合計金額を大きく出すか、店員の入力画面のボタンをどう配置すれば押しやすいか等、使う人（人間）がわかりやすいように見た目を設計します。", "details": "ユーザーが直接見て操作する画面や、システムから印刷・出力されるレポート（請求書、レシートなど）のレイアウト、印字項目、文字サイズなどを決定する。", "etymology": "Report Design / Form Design。\n帳票とは「帳簿（台帳など）」と「伝票（注文票など）」の総称。システムに入出力される画面や紙のレイアウトを設計すること。", "exam": "システム開発工程の中で「いつ行われるか」が頻繁に問われます。\nプログラマ向けの「内部設計」ではなく、ユーザーに向けた「外部設計（基本設計）」で行われるという点が最大のポイントです。", "def30": "画面や帳票の入出力レイアウトを外部設計の段階で定義する作業。（30文字）"}, {"id": 138, "term": "デザインレビュー", "summary": "・各設計工程の終了時に、設計書の内容について専門家や関係者が集まってレビュー（審査）を行い、品質や要件満足度を評価・承認する手続き。", "keywords": "・設計審査\n・DR\n・要件適合性検証\n・欠陥の早期検出\n・審査会\n・成果物評価", "analogy": "「建築前の設計図の最終チェック会議」です。\n大工、施主、建築士が集まり、「強度は大丈夫か」「住人の要望通りか」を設計図の段階でくまなく審査して判を押します。", "details": "システム開発の各設計フェーズ（基本設計、詳細設計等）の完了時に、設計内容がユーザー要件を満たしているか、技術的妥当性や安全性が確保されているかを、関係者（設計者・顧客・第三者）が多角的に検証・承認する機会。", "etymology": "Design Review（設計の審査）。", "exam": "品質管理・開発プロセスで頻出。「後工程での後戻りを防ぐため、各設計フェーズの終わりに設計内容の妥当性を審査・承認する活動＝デザインレビュー（DR）」。", "def30": "設計フェーズ完了時に、設計成果物が要件を満たすか関係者で審査・承認する活動。（38文字）"}, {"id": 139, "term": "ブラックボックステスト", "summary": "・内部構造を無視し、仕様書通りに「正しい入力に対して正しい出力が出るか」を確認するテスト。\n・代表的な手法に同値分割法や限界値分析がある。", "keywords": "・仕様書ベース\n・入出力の確認\n・内部構造を意識しない\n・同値分割法\n・限界値分析", "analogy": "「自販機の一般客のテスト」です。\n「100円入れてボタンを押せばジュースが出るか」だけを確認し、中の機械の動きは気にしません。", "details": "プログラムの内部構造は考慮せず、仕様書通りに正しい出力が得られるか（入力と出力の関係）を検証するテスト手法。", "etymology": "Black Box（中が見えない黒い箱）。\nシステムを「中身が見えない黒い箱」と見立てて、外側（入力と出力）だけをテストすること。", "exam": "ソフトウェアテスト分野で頻出。\n「内部構造を考慮しない」というキーワードが正解のサイン。以前まとめた「同値分割法」や「限界値分析」は、このブラックボックステストの代表手法としてセットで問われます。", "def30": "内部構造を考慮せず、仕様書に基づく入出力を検証するテスト。（29文字）"}, {"id": 140, "term": "同値分割\n(同値分割法)", "summary": "・入力データを同じ結果になるグループに分け、代表値だけをテストする手法。\n・ブラックボックステストの一種で、境界を狙う「限界値分析」とセットで問われる。", "keywords": "・ブラックボックステスト\n・代表値\n・有効同値クラス\n・無効同値クラス\n・限界値分析との違い", "analogy": "遊園地の料金（0-5歳無料、6-12歳半額、13歳〜通常料金）のテストです。\n0歳,1歳,2歳…と全員分試すのではなく、「3歳（無料グループの代表）」「10歳（半額の代表）」「25歳（通常の代表）」の3パターンだけを効率よくテストするやり方です。", "details": "システムの入力データを「同じ処理結果になるグループ（同値クラス）」に分け、各グループから代表的な値を1つずつ選んでテストする手法。\nテスト回数を減らしつつ、効率的にバグを発見できる。", "etymology": "Equivalence Partitioning（等価分割）。\nEquivalence（同値、等価なもの）に Partitioning（分割する）こと。同じ結果になるはずのデータの集まりごとに分けるテスト手法。", "exam": "ソフトウェアテスト（ブラックボックステスト）の分野で出題。\n「限界値分析（境界値分析）」とセットで出題されます。\nグループの**「代表値（真ん中らへん）」**を選ぶのが同値分割、グループの**「境界・境目（端っこ）」**を選ぶのが限界値分析、という対比が頻出です。", "def30": "入力データを同値なグループに分け、代表値でテストする手法。（29文字）"}, {"id": 141, "term": "ホワイトボックステスト", "summary": "・プログラムの内部構造や論理ルートが正しく動くかを確認するテスト。\n・どれだけルートを通ったか（網羅率・カバレッジ）を基準にする。", "keywords": "・内部構造\n・論理ルート\n・カバレッジ（網羅率）\n・命令網羅\n・分岐網羅", "analogy": "「自販機の修理業者のテスト」です。\n「この配線は繋がっているか」「条件によって歯車が切り替わるか」など、中の仕組みを隅々までチェックします。", "details": "プログラムの内部構造や論理的な処理の流れ（if文の分岐など）が正しく作られているかを検証するテスト手法。", "etymology": "White Box（中が透けて見える透明な箱）。\nプログラムの内部（ロジック）を透明な箱のように隅々まで見通してテストすること。", "exam": "ソフトウェアテスト分野で頻出。\n「内部構造や論理を〜」とあればホワイトボックステスト。どれくらいルートを通ったかを示す「網羅率（カバレッジ）」や「命令網羅」「分岐網羅」などの手法と関連付けて出題されます。", "def30": "プログラムの内部構造や論理的な処理のルートを検証するテスト。（30文字）"}, {"id": 142, "term": "カバレッジ\n(C0・C1・C2)", "summary": "・ホワイトボックステストにおいて、プログラムの内部構造をどれだけ網羅（カバー）してテストしたかを示す指標。\n・命令網羅(C0), 分岐網羅(C1), 条件網羅(C2)がある。", "keywords": "・ホワイトボックステスト\n・網羅率\n・命令網羅（C0）\n・分岐網羅（C1：判定条件網羅）\n・条件網羅（C2）", "analogy": "「迷路の探索度合い」です。\n・命令網羅(C0)：すべての「道」を最低1回は通る。\n・分岐網羅(C1)：すべての「交差点の右折・左折」を最低1回ずつ試す。\n（分岐網羅の方がテスト基準として厳しい）", "details": "・命令網羅（Statement Coverage/C0）：すべての命令文を少なくとも1回は実行する。\n・分岐網羅（Branch Coverage/C1）：すべての分岐（IF文の真・偽）を少なくとも1回は実行する。\n・条件網羅（Condition Coverage/C2）：分岐内の複数の条件の組み合わせを網羅する。", "etymology": "Coverage（カバー範囲、網羅率）。", "exam": "ホワイトボックステストの計算・図表問題で超頻出。「すべての分岐の真と偽を1回以上実行する＝分岐網羅（判定条件網羅）」という定義や、テストケースの必要数を問われます。", "def30": "ホワイトボックステストで、命令や分岐をどれだけ漏れなく実行したかを示す網羅率。（39文字）"}, {"id": 143, "term": "トップダウン/ボトムアップテスト\n(スタブ・ドライバ)", "summary": "・結合テストの手法。\n・上位モジュールから行う際は下位の代役（スタブ）を使い、下位モジュールから行う際は上位の代役（ドライバ）を使う。", "keywords": "・結合テスト\n・トップダウンテスト（スタブ）\n・ボトムアップテスト（ドライバ）\n・モジュール結合", "analogy": "「車の組み立てテスト」です。\n・トップダウン：ハンドル（上位）からテスト。タイヤ（下位）がないので、代わりの台車「スタブ」を履かせる。\n・ボトムアップ：タイヤ（下位）からテスト。ハンドルがないので、代わりの操作機「ドライバ」を繋ぐ。", "details": "モジュール同士を繋ぐ結合テストの手法。\n・トップダウン：上位モジュールからテストする。未完成の下位モジュールを呼び出す代役として「スタブ」を用いる。\n・ボトムアップ：下位モジュールからテストする。未完成の上位モジュールの代役として「ドライバ」を用いる。", "etymology": "Top-down（上から下へ） / Bottom-up（下から上へ）。Stub（切り株、半券） / Driver（操縦者）。", "exam": "ソフトウェアテスト分野で超頻出！「下位モジュールの代わり＝スタブ（トップダウン用）」「上位モジュールの代わり＝ドライバ（ボトムアップ用）」の組み合わせが絶対に出ます。", "def30": "結合テストにて、上位からのテストには「スタブ」、下位からは「ドライバ」を用いる。（40文字）"}, {"id": 144, "term": "単体/結合/総合/運用テスト", "summary": "・テスト工程の段階。\n・部品単体、モジュール連携、システム全体（要件確認）、実際の業務環境の順に検証を進める。", "keywords": "・V字モデル\n・単体テスト（内部設計）\n・結合テスト（外部設計）\n・システムテスト（要件定義）\n・運用テスト（業務要件）", "analogy": "「オーケストラの練習」です。\n・単体：個人練習（音が出るか）\n・結合：パート練習（バイオリン同士が合うか）\n・総合：全体リハーサル（曲として成立するか）\n・運用：本番のホールでのゲハーサル（客席に響くか）", "details": "ウォーターフォール開発におけるテスト工程。\n1.単体テスト：モジュール単体の動作確認（ホワイトボックス）。\n2.結合テスト：モジュール間のインターフェース確認。\n3.システム(総合)テスト：要件定義を満たすかの全体確認。\n4.運用テスト：ユーザー部門による本番環境でのテスト。", "etymology": "Unit Test / Integration Test / System Test / Operation Test。", "exam": "前述の「システム開発工程」のV字モデル対応として頻出。「運用テストは実際の利用部門（ユーザー）が主体となって行う」という点もよく問われます。", "def30": "部品単体、連携、システム全体、本番環境の順にシステムが要件を満たすか検証する。（39文字）"}, {"id": 145, "term": "アサーションチェッカ", "summary": "・プログラム実行時に、変数の値や条件式が「開発者の意図通り（真）になっているか」を論理式（アサーション）で自動検証・テストするデバッグ用ツール。", "keywords": "・アサーション（表明）\n・論理式検証\n・前提条件・事後条件\n・プログラム検証\n・動的テスト", "analogy": "「プログラムの中の自動抜き打ち検査員」です。\nコードの中に『ここで変数xは絶対にプラスの値であるはず！』という誓い（アサーション）を書いておき、違反した瞬間にエラーを鳴らして知らせます。", "details": "プログラムの特定の箇所で満たされるべき論理条件（表明/アサーション）をコード内に記述し、プログラム実行時にその条件が成立しているかを自動的に検証するテスト・デバッグ支援ツール。", "etymology": "Assertion Checker（表明確認ツール）。", "exam": "ソフトウェアテスト・品質管理で出題。「プログラムの実行時に指定された条件（表明）が成り立っているかを自動検証するテストツール＝アサーションチェッカ」。", "def30": "プログラム実行時に変数値や条件が論理式通りか自動検証するテスト工具。（34文字）"}, {"id": 146, "term": "ファジング\n(Fuzzing)", "summary": "・ソフトウェアに対し、予測不能な問題のある大量のデータ（ファズ/問題データ）を入力し、エラーやクラッシュの発生から未知の脆弱性を発見するテスト手法。", "keywords": "・未知の脆弱性検出\n・問題データ（ファズ）\n・自動テスト\n・クラッシュ検知\n・セキュリティテスト", "analogy": "「自販機にありとあらゆる異物を突っ込む乱暴なテスト」です。\n正規のコインだけでなく、おもちゃのコインや長すぎる紐（ランダムなデータ）を投げ込んで、機械が壊れたり変な挙動をしないかテストします。", "details": "ソフトウェアのセキュリティテスト手法。プログラムの入力値として、意図的に加工された無効なデータや予測不能なランダムデータ（Fuzz）を大量に与え、例外処理の漏れやメモリ破壊（クラッシュ）から脆弱性を検出する。", "etymology": "Fuzzing（Fuzz＝毛羽立ち、予測不能なゴミデータを与えること）。", "exam": "セキュリティテストの最新・超頻出用語！「想定外の乱数や無効なデータを大量に入力してプログラムのクラッシュを起こし、未知の脆弱性を検出する＝ファジング」が正解です。", "def30": "意図的に無効なデータ(ファズ)を大量入力し未知の脆弱性を検出するテスト。（36文字）"}, {"id": 147, "term": "リグレッションテスト\n(回帰テスト / 退行テスト)", "summary": "・プログラムの改修・機能追加時に、他の既存機能に「不具合（先祖返り）」が生じていないか確認する再テスト。\n・変更の影響範囲を特定し、自動テストツールを活用して繰り返し実施することが重要。", "keywords": "・既存機能への影響確認\n・先祖返り（デグレード）の検知\n・プログラム改修・保守フェーズ\n・テストの自動化（CI/CD）", "analogy": "「改修後の『ブレーキとライトの点検』」です。\n車のエンジンを修理した（一部コードを変更した）後、関係なさそうなブレーキやライト（既存機能）が壊れていないか、念のため全体を点検するテストです。", "details": "プログラムの修正や機能追加、OS/ライブラリのバージョンアップ等を行った際、その変更によって今まで正しく動作していた既存の機能に予期せぬ不具合や影響（退行/デグレード）が発生していないか検証するテスト。CI/CDパイプライン等で自動化して繰り返し実行されることが多い。", "etymology": "Regression Test。\nRegression（退行、後戻り、逆戻り）。「修正したことで、システムが以前の悪い状態に後戻り（Regression）していないか」を確かめるテスト。", "exam": "ソフトウェアテスト・システム保守分野で超超頻出！\n「プログラムの変更や修正後に、他の正常な部分に悪影響が出ていないかを試すテスト＝リグレッションテスト（回帰テスト/退行テスト）」が正解キーワード。「先祖返り・デグレード」という言葉とも結びつきます。", "def30": "プログラム改修後に既存機能への影響や不具合の有無を検証する再テスト。（35文字）"}, {"id": 148, "term": "キー値\n(ソート・検索)", "summary": "・データの中から特定のレコードを識別したり、ソート（並び替え）や検索の基準として利用されるデータ項目（値）。", "keywords": "・主キー（Primary Key）\n・検索キー\n・ソートキー\n・ハッシュキー\n・一体性・識別性", "analogy": "「出席番号や社員番号」です。\nクラスで生徒を並び替えたり、個人を特定したりする際に基準となる「番号（キーの値）」のことです。", "details": "データベースやアルゴリズムにおいて、レコードの特定（検索）や順序付け（ソート）の基準となるデータフィールドの値。RDBでは主キーとして一意性を保証するために用いられる。", "etymology": "Key Value（鍵となる値）。", "exam": "アルゴリズムやDBの基本概念。「ソートの基準となる値をキー値と呼ぶ」「ハッシュ関数に入力してアドレスを得る対象の値をキー値と呼ぶ」などで登場します。", "def30": "検索やソート、レコードの特定を行う際に基準となるデータ項目の値。（32文字）"}, {"id": 149, "term": "安定ソート vs 不安定ソート", "summary": "・ソートアルゴリズムの性質の分類。\n・同順位のキー値を持つデータ同士の「元の前後関係（順序）」が、ソート後も保存されるのが「安定ソート」。", "keywords": "・順序の保存\n・バブルソート/挿入ソート（安定）\n・クイックソート/ヒープソート（不安定）\n・キー値の重複", "analogy": "「テストの同点者の順番維持」です。\n元々『1番目に提出したA君』と『2番目に提出したB君』が同じ80点だった時、ソート後もA君が先に来るのが「安定ソート」です。", "details": "・安定ソート：同じキー値を持つ複数のデータが存在する場合、ソート前とソート後でそれらの相対的な位置関係が変わらないアルゴリズム（バブルソート、挿入ソート、マージソート等）。\n・不安定ソート：順序が入れ替わる可能性がある（クイックソート、ヒープソート等）。", "etymology": "Stable Sort / Unstable Sort。", "exam": "アルゴリズム分野で出題。「同等キー値の元の順序が維持される＝安定ソート」「マージソートやバブルソートは安定、クイックソートは不安定」を押さえましょう。", "def30": "同等キー値のデータの元順序が維持されるアルゴリズムを安定ソートという。（35文字）"}, {"id": 150, "term": "ハッシュ探索法\n(シノニム・オープンアドレス)", "summary": "・データから計算した「ハッシュ値」をそのまま保存場所（アドレス）にするため、データ量が増えても検索時間が変わらない（超高速な）探索アルゴリズム。", "keywords": "・検索時間がO(1)\n・ハッシュ値の衝突（シノニム）\n・オープンアドレス法（再ハッシュ）\n・シノニムレコード\n・連鎖法", "analogy": "「社員番号がそのまま下駄箱の番号になるシステム」です。\n社員番号105番の人は105番の下駄箱を探せば一瞬で見つかります。もし別の人がすでに使っていたら（シノニム/衝突）、ルールに従って隣の空きを探します（オープンアドレス法）。", "details": "データのキー値に関数（ハッシュ関数）を適用して求めた値を配列の添字（格納アドレス）とし、目的のデータを1回の計算で直接検索する手法。検索時間はデータ量に依存しない。異なるキーで同じ値になる「衝突（シノニム）」の解決策が重要。", "etymology": "Hash（細切れにする、寄せ集める）を用いた検索手法。Synonym（同義語、衝突）。", "exam": "アルゴリズム分野で頻出。「データ量に関わらず検索時間が一定」「衝突（シノニム）が発生した際、別のハッシュ関数を使って空き領域を探す解決法＝オープンアドレス法」が問われます。", "def30": "ハッシュ値を用いて格納場所を直接計算し、データ量に関わらず高速に検索する手法。（39文字）"}, {"id": 151, "term": "バブルソート\n(単純交換法)", "summary": "・隣り合う要素の大きさを比較し、順序が逆なら入れ替える処理を繰り返す単純なソート。\n・計算量は O(n^2) で、同等キーの順序が保たれる「安定ソート」。", "keywords": "・隣接要素の比較・交換\n・計算量 O(n^2)\n・安定ソート\n・単純交換法", "analogy": "「背の順で隣の人と背比べ」です。\n隣同士で比べ「右の人の方が小さければ交代」を右端まで繰り返すと、一番背の高い人が右端に確定（泡のように浮き上がる）します。", "details": "配列の端から隣接する2つの要素を比較・交換し、最悪・平均計算量 O(n^2) で整列する。データ数が少ない場合に実装が容易だが、大量データには不向き。", "etymology": "Bubble Sort。要素が水中の気泡（バブル）のように末尾へ浮き上がっていく様子から命名。", "exam": "アルゴリズム分野で出題。「隣接要素を比較・交換する」「安定ソートである」「計算量が O(n^2)」がキーワード。", "def30": "隣り合う要素を比較・交換し整列する安定な単純アルゴリズム。（30文字）"}, {"id": 152, "term": "単純挿入ソート\n(基本挿入法)", "summary": "・整列済みの列に対して、未整列のデータを適切な位置へ「割り込ませて挿入」するソート。\n・計算量は O(n^2) で、ほぼ整列済みのデータに対して高速に動く「安定ソート」。", "keywords": "・未整列要素の挿入\n・ほぼ整列済みデータで高速\n・計算量 O(n^2)\n・安定ソート\n・基本挿入法", "analogy": "「手札のトランプの並べ替え」です。\n配られたカード（未整列）を1枚ずつ手に取り、すでに順番通り並んでいる手札（整列済み）の正しい隙間にサッと挟み込みます。", "details": "ソート済み部分と未ソート部分に分け、未ソート部分の先頭要素をソート済み部分の適切な位置に挿入する。データが初期状態でほぼ整列している場合は O(n) に近くなり極めて高速。", "etymology": "Insertion Sort。適切な位置へ挿入（Insert）することから。", "exam": "アルゴリズム分野で頻出。「整列済み部分の適切な位置へ挿入する」「ほぼ整列しているデータに高速」「シェルソートのベース」という特徴が問われます。", "def30": "未整列の要素を整列済み列の適切な位置に挿入して並べ替える手法。（32文字）"}, {"id": 153, "term": "単純選択ソート\n(基本選択法)", "summary": "・未整列のデータの中から「最小値（最大値）」を探し出し、未整列の先頭と入れ替えるソート。\n・データ状態に関わらず計算量は常に O(n^2) で、「不安定ソート」。", "keywords": "・最小値（最大値）の選択\n・交換回数が少ない\n・計算量 O(n^2)\n・不安定ソート\n・基本選択法", "analogy": "「バラバラのカードから一番小さい数字を探す」作業です。\n全体を見て最小の「1」を探して左端に置き、次に残りから最小の「2」を探して2番目に置くのを繰り返します。", "details": "未整列領域から最小値（または最大値）をスキャンして発見し、未整列領域の先頭要素と交換する。データの初期状態に依存せず比較回数は常に n(n-1)/2 回。", "etymology": "Selection Sort。最小値を選択（Select）することから。", "exam": "アルゴリズム分野で出題。「未整列領域から最小値を選択する」「初期状態に関わらず計算量が O(n^2)」「データ交換回数が最高でも n-1 回と少ない」が特徴。", "def30": "未整列範囲から最小値を選択し先頭と交換することを繰り返す手法。（32文字）"}, {"id": 154, "term": "クイックソート", "summary": "・基準値（ピボット）を決め、それより小さいグループと大きいグループに分割を繰り返すソート。\n・平均計算量は O(n log n) で一般に最速だが、同等キー順序が崩れる「不安定ソート」。", "keywords": "・基準値（ピボット）\n・分割統治法\n・平均計算量 O(n log n)\n・最悪計算量 O(n^2)\n・不安定ソート", "analogy": "「基準身長でクラスを2組に分ける」作業です。\n「160cmより高い人・低い人」に分け、分けた2グループの中でさらに「170cm」「150cm」と基準を決めて分け続けることで一気に整列させます。", "details": "分割統治法（Divide and Conquer）に基づくアルゴリズム。ピボット（基準値）を選び、ピボット未満と以上の2子配列に分割する処理を再帰的に適用する。内部メモリで処理が完結し非常に高速。", "etymology": "Quick Sort（速いソート）。実用上最も高速に動作することから命名。", "exam": "アルゴリズム分野で超超頻出！「ピボット（基準値）を用いる」「平均計算量が O(n log n)」「最悪計算量（ピボット選択が最悪の場合）は O(n^2)」「不安定ソート」が問われます。", "def30": "基準値との高低で配列を再帰的に2分割し高速整列する分割統治法。（32文字）"}, {"id": 155, "term": "マージソート", "summary": "・データを1要素になるまで細かく分割し、整列させながら合体（マージ）していくソート。\n・最悪でも常に計算量は O(n log n) で安定しているが、作業用メモリが必要。「安定ソート」。", "keywords": "・分割と併合（マージ）\n・最悪計算量 O(n log n)\n・作業用領域が必要\n・安定ソート\n・分割統治法", "analogy": "「細かく分けてからトーナメントで合体する」作業です。\n全員をバラバラにしてから、2人ずつ・4人ずつと整列順を保ったままガッチャンコ（併合）していきます。", "details": "データを半分ずつ再帰的に分割し、1要素になった段階から2つのソート済み部分配列を比較して1つのソート済み配列へと併合（マージ）する。安定ソートであり外部メモリソートにも適する。", "etymology": "Merge Sort。併合（Merge）することから。", "exam": "アルゴリズム分野で頻出！「2つの整列済み配列を併合する」「最悪の場合でも計算量が O(n log n) を保証する」「追加の作業領域（メモリ）が必要」「安定ソート」がポイント。", "def30": "データを細分化後、整列させつつ併合(マージ)を繰り返す安定手法。（33文字）"}, {"id": 156, "term": "ヒープソート", "summary": "・未整列データを「ヒープ構造（完全二分木）」に構成し、根にある最大値を取り出す処理を繰り返すソート。\n・最悪でも計算量は O(n log n) で追加メモリ不要だが、「不安定ソート」。", "keywords": "・完全二分木\n・親>=子（ヒープ構造）\n・最大値（根）の抽出\n・計算量 O(n log n)\n・追加メモリ不要\n・不安定ソート", "analogy": "「ピラミッド型の構造（ヒープ）」です。\n常にピラミッドの頂点に一番大きい数が来る仕組みを作り、頂点から順に取っていき、ピラミッドを崩さず再構築することを繰り返します。", "details": "配列を完全二分木（ヒープ）と見なし、親要素 >= 子要素（または親 <= 子）の関係を構築する。根（最大値）を取り出して末尾と交換し、ヒープを再構築（Heapify）する処理を繰り返す。", "etymology": "Heap Sort。山・積み上げ（Heap）というデータ構造を利用することから。", "exam": "アルゴリズム分野で頻出！「完全二分木を用いる」「親のキー値が子のキー値以上」「計算量が常に O(n log n)」「追加の作業領域が不要（内部ソート）」が問われます。", "def30": "完全二分木(ヒープ)を構築し根の最大値を抽出・再構築する手法。（32文字）"}, {"id": 157, "term": "シェルソート", "summary": "・一定の間隔（ギャップ）離れた要素同士を「単純挿入ソート」で整列させ、間隔を狭めていくソート。\n・単純挿入ソートの弱点（遠くへの移動）を克服した高速手法で、「不安定ソート」。", "keywords": "・間隔（ギャップ）を設定\n・グループ分け\n・単純挿入ソートの改良\n・計算量 O(n^1.25)等\n・不安定ソート", "analogy": "「粗めのくし（櫛）から徐々に細かいコームにしていく髪とかし」です。\n最初は遠く離れたデータ同士で大雑把に並べ替え、最後に隣同士（間隔1）で仕上げの挿入ソートを行います。", "details": "一定の間隔 h ごとにグループ化し、各グループ内で単純挿入ソートを行う。h を順次小さくして最終的に h=1（通常の単純挿入ソート）で仕上げる。「ほぼ整列したデータには単純挿入ソートが極めて高速」という特性を活用。", "etymology": "Shell Sort。考案者ドナルド・シェル (Donald Shell) の名前に由来。", "exam": "アルゴリズム分野で頻出！「一定間隔おきの要素グループに対して単純挿入ソートを適用する」「間隔を狭めていく」「単純挿入ソートの改良手法」という定義がそのまま問われます。", "def30": "一定間隔離れた要素群に単純挿入ソートを適用し段階的に整列する手法。（34文字）"}, {"id": 158, "term": "機械学習\n(教師あり・教師なし・強化学習)", "summary": "・AI（人工知能）にデータから規則性を学習させる技術。\n・正解データを与える「教師あり」、正解を与えず分類させる「教師なし」、報酬を与えて試行錯誤させる「強化学習」に分かれる。", "keywords": "・教師あり学習（回帰・分類）\n・教師なし学習（クラスタリング・主成分分析）\n・強化学習（報酬最大化・Q学習）", "analogy": "・教師あり：猫の画像と「これは猫」という正解（ラベル）をセットで教える。\n・教師なし：大量の動物の画像を渡し「似た者同士でグループ分けして」と指示する。\n・強化学習：ゲームで「得点（報酬）」が上がる行動をAI自身に試行錯誤で見つけさせる。", "details": "・教師あり学習：入力データと正解ラベルのペアから特徴を学習し、未知のデータを予測・分類する。\n・教師なし学習：正解ラベルのないデータから隠れた構造や規則性（クラスタリング等）を見出す。\n・強化学習：環境のなかで行動を選択し、得られる報酬が最大になるような方策を学習する。", "etymology": "Machine Learning（機械学習） / Supervised Learning（監督・指導された学習）。", "exam": "AI・最新技術分野で頻出！「正解データを与えて分類・回帰を行う＝教師あり」「データ群を似たものに分けるクラスタリング＝教師なし」「報酬が最大になる行動を学習する＝強化学習」の対応付けが問われます。", "def30": "AIの学習手法。正解を与える(教師あり)、与えず分類(教師なし)、報酬で試行錯誤(強化学習)。（47文字）"}, {"id": 159, "term": "ディープラーニング / ニューラルネットワーク", "summary": "・人間の脳の神経回路を模した「ニューラルネットワーク」を多層化し、AIがデータの特徴を自ら抽出・学習できるようにした高度な機械学習技術。", "keywords": "・深層学習\n・多層化\n・特徴量の自動抽出\n・人間の脳神経モデル\n・画像認識・自然言語処理", "analogy": "従来のAIは人間が「猫は耳が三角で…」と特徴を教える必要がありましたが、ディープラーニングは脳を模した複雑なネットワーク（多層）により、AIが自ら「猫の特徴はこれだ」と勝手に気づいて学習します。", "details": "人間の脳神経系モデル（ニューロン）を数学的に表現した「ニューラルネットワーク」の中間層（隠れ層）を多層化（深く）することで、複雑なパターンの認識や特徴量の自動抽出を可能にした機械学習の一分野。", "etymology": "Deep Learning（深い学習） / Neural Network（神経回路網）。", "exam": "AI分野で超頻出。「人間の脳神経回路を模倣したモデル＝ニューラルネットワーク」「それを多層化して、対象の特徴量をシステム自身が抽出する＝ディープラーニング（深層学習）」がキーワードです。", "def30": "脳の神経回路モデルを多層化し、データの特徴をAI自ら自動抽出して学習する技術。（39文字）"}, {"id": 160, "term": "IoT / エッジコンピューティング", "summary": "・あらゆる「モノ」がインターネットに接続され、相互に情報交換する技術。\n・端末に近い場所でデータ処理を行い、クラウドの回線負荷や遅延を抑える分散処理技術。", "keywords": "・Internet of Things\n・エッジコンピューティング\n・クラウドの負荷軽減\n・リアルタイム処理\n・遅延（レイテンシ）の低減", "analogy": "「自動運転車とクラウドの関係」です。\n車のカメラ（IoT）が捉えた「目の前の子供」のデータを、遠くのクラウドに送って判断を待つと事故になります。だから車に近い場所（エッジ）で即座に処理（エッジコンピューティング）します。", "details": "・IoT：家電、自動車、センサー等の「モノ」がネットに接続しデータをやり取りする概念。\n・エッジコンピューティング：IoT端末やそのすぐ近くのサーバー（エッジ）でデータ処理を行い、クラウドへの通信遅延や回線負荷を削減する分散処理アーキテクチャ。", "etymology": "Internet of Things（モノのインターネット） / Edge Computing（端っこでの計算処理）。", "exam": "テクノロジ分野のトレンドとして頻出。「IoT端末が増大しクラウドに負荷がかかる」「端末に近い場所で一次処理を行い、応答速度を上げ通信遅延を防ぐ手法」＝エッジコンピューティングが正解の定番です。", "def30": "端末(モノ)がネットに繋がるIoTと、端末近くで処理し通信遅延を防ぐエッジ技術。（40文字）"}, {"id": 161, "term": "RFID / NFC", "summary": "・電波や電磁波を用いて、非接触でICタグのデータを読み書きする技術。\n・Suicaなどの交通系ICや、ユニクロのセルフレジなどに使われる。", "keywords": "・ICタグ\n・非接触通信\n・NFC（近距離無線通信）\n・Suica/おサイフケータイ\n・複数同時読み取り", "analogy": "・NFC：スマホやSuicaなど「数センチの近距離」でピッとタッチする通信。\n・RFID（UHF帯）：ユニクロのレジのように、カゴに入れた複数のタグ（ICチップ）を「電波で一瞬にして一括読み取り」する技術。", "details": "・RFID (Radio Frequency Identification)：電波を用いてICタグ（RFタグ）のデータを非接触で読み書きする技術システム全体の総称。バーコードと違い汚れに強く、一括読み取りが可能。\n・NFC (Near Field Communication)：RFIDのうち、10cm程度の近距離で通信する国際規格。", "etymology": "Radio Frequency（無線周波数） Identification（識別）。", "exam": "バーコードとの比較や事例で頻出。「非接触で複数のタグを同時に読み取れる」「箱の中に入ったままでも電波が届けば読み取れる（汚れにも強い）」という特徴からRFIDを選ばせる問題が出ます。", "def30": "電波を用い、非接触でICタグのデータを一括で読み書きできる自動識別技術。（36文字）"}, {"id": 162, "term": "QRコード / JANコード", "summary": "・横方向のみに情報を持つ商品識別用1次元コード（バーコード）と、縦横2次元で大容量情報を持つコードの比較。\n・2次元コードは切り出しシンボル（四角）と誤り訂正機能が特徴。", "keywords": "・2次元コード\n・切り出しシンボル\n・誤り訂正機能\n・大容量データ\n・JANコード（1次元バーコード・POS）", "analogy": "スーパーの商品の裏にある縦線のシマシマが「JANコード（バーコード）」。スマホ決済等で使う、四角い模様で角に3つの目玉マークがあるのが「QRコード」です。", "details": "・JANコード：日本の共通商品コードとして使われる1次元バーコード。POSシステムで利用。\n・QRコード：日本のデンソーウェーブが開発した2次元マトリックスコード。3つの角にある「切り出しシンボル」で高速読み取りと回転対応を実現し、一部が汚れていても復元できる「誤り訂正機能」を持つ。", "etymology": "Quick Response Code（素早く読み取れるコード） / Japanese Article Number（日本の商品番号）。", "exam": "ストラテジ・システム構成で出題。「3つの角に切り出しシンボルがある」「縦横の2次元で情報を持ち大容量」「誤り訂正機能がある」という特徴があればQRコードです（JANコード等の1次元バーコードとの違い）。", "def30": "縦横2次元で大容量データを持ち、切り出しシンボルや誤り訂正機能を持つコード。（38文字）"}, {"id": 163, "term": "ドップラー効果\n(レーダー・通信)", "summary": "・波源（送信者）や観測者（受信者）が移動することで、音や電波などの周波数（波長）が変化して観測される物理現象。速度計測等に利用。", "keywords": "・周波数変化\n・波長の伸縮\n・移動速度の計測\n・スピードレーダー\n・ドップラーシフト", "analogy": "「救急車のサイレンの音の変化」です。\n近づいてくると音（周波数）が高く聞こえ、走り去ると低く聞こえる現象を利用して、相手のスピードや動きを割り出します。", "details": "音波や電波の送信元と受信者が相対的に移動している際、接近時には周波数が高く（波長が短く）、遠ざかる時には周波数が低く観測される現象。速度計測（ドップラーレーダー）や通信の周波数補正で用いられる。", "etymology": "Doppler Effect（発見者クリスチャン・ドップラーの名に由来）。", "exam": "テクノロジ・センサー技術で出題。「電波の周波数の変化（ドップラーシフト）を検出して、対象物の移動速度や接近を測定する現象＝ドップラー効果」。", "def30": "波源と観測者の相対的移動により音波や電波の周波数が変化して見える物理現象。（37文字）"}, {"term": "アクティブシャッタ方式\n(Active Shutter)", "summary": "・3D映像技術の一つで、左右の映像を交互に高速表示し、同期する専用メガネのシャッターを交互に開閉して立体に見せる方式。\n・解像度を落とさずに高画質な3D映像を表示できるが、メガネに電池や制御回路が必要で重く高価になる。", "keywords": "・フレームシーケンシャル方式\n・液晶シャッターメガネ\n・3D表示技術\n・パッシブ方式（偏光メガネ方式）との対比\n・同期信号（赤外線・Bluetooth）", "analogy": "「超高速で左右の目を交互にウインクさせる魔法のメガネ」です。\nテレビ画面が「右目用・左目用」の映像を1秒間に120回など超高速で交互に切り替え、メガネ側もそれに合わせて右と左のレンズを交互に真っ黒（遮光）にして、それぞれの目に正しい映像だけを届ける仕組みです。", "details": "ディスプレイ側で左右それぞれの目に対応した画像を時分割（フレームシーケンシャル）で交互に表示し、それに合わせて液晶メガネの左右の透過率（明るさと遮光）を信号で同期させて切り替える3D表示技術。画面の縦解像度を損なわずにフルHDなどの高画質を維持できる。", "etymology": "Active（能動的な・自ら動く）＋ Shutter（光を遮る板）。\nメガネ自体が電池や電子回路を積み、能動的（Active）にレンズの開閉（Shutter）を行うことから命名された。", "exam": "マルチメディア・ディスプレイ技術分野で出題されます。\n・時分割（フレームシーケンシャル）で交互表示する仕組みの理解\n・パッシブ方式（偏光メガネ方式）との比較（パッシブはメガネが軽くて安いが画面解像度が半分になりやすい／アクティブは高画質だがメガネが高価で重い）", "def30": "左右の映像を交互表示し同期メガネで遮光制御する3D技術。（28文字）", "id": 164}, {"term": "偏光フィルター方式\n(Polarized 3D)", "summary": "・左右の目にそれぞれ異なる振動方向の「偏光光」を照射し、専用の偏光メガネでそれぞれの画像だけを分離して立体視を行う3D技術。\n・メガネが軽量・安価（電池不要）でチラつきがないが、画面の走査線を交互に使うため縦の解像度が半分になりやすい。", "keywords": "・パッシブ方式（受動型）\n・偏光方向（直線偏光 / 円偏光）\n・解像度の半減（ライン交互表示）\n・アクティブシャッタ方式との対比\n・映画館の3Dメガネ", "analogy": "「縦シマと横シマの窓格子（フィルター）を使ったメガネ」です。\nテレビ画面の偶数ライン（右目用）と奇数ライン（左目用）で光の波の向き（偏光）を変えて同時に出し、メガネ側で『縦の波だけ通すレンズ』『横の波だけ通すレンズ』を配置することで、左右それぞれの目に違う映像を届けます。", "details": "ディスプレイの走査線（ライン）ごとに右目用・左目用の画像を交互に配置し、それぞれのラインに異なる方向の偏光フィルターを施すことで、同一画面上に左右の画像を同時に表示する3D技術。鑑賞側は偏光フィルムを貼ったメガネを着用するだけでよいため、メガネが非常に軽く安価で、フリッカー（画面のチラつき）も起きにくい。", "etymology": "Polarized（偏光された・波の向きが揃った）＋ Filter（フィルター・ろ過器）。\n特定方向に振動する光だけを通過させる「偏光フィルター」を利用することから命名。", "exam": "マルチメディア・ディスプレイ技術分野で出題されます。\n・3D表示技術の分類（アクティブシャッタ/偏光/アナグリフ）における特徴比較\n・アクティブシャッタ方式との対比が最頻出：偏光方式は「メガネが安く軽量（電池不要）でチラつき（フリッカー）がない」が「走査線を分けるため垂直解像度が半分になる」という特徴が問われます。", "def30": "偏光の異なる左右映像を専用メガネで分離し立体視する3D技術。（28文字）", "id": 165}, {"term": "アナグリフ方式\n(Anaglyph)", "summary": "・左右の目を模した映像を「赤と青（または緑）」などの補色関係で重ねて表示し、専用のカラーメガネで色分離して立体感を生み出す3D技術。\n・印刷物や通常のモニターでもそのまま利用でき安価だが、本来の色彩が失われやすく目が疲れやすい。", "keywords": "・色分離方式（赤青メガネ）\n・補色関係（赤とシアン/青）\n・3D立体視技術\n・両眼視差\n・アクティブシャッタ方式/偏光メガネ方式との対比", "analogy": "「赤と青のフィルムで作った紙メガネで見る昭和レトロな立体写真」です。\n右目には青いフィルター（赤色カット）、左目には赤色のフィルター（青色カット）を重ねたメガネを通すことで、左右の目にそれぞれ違う角度の映像だけを届けて脳の中で飛び出させます。", "details": "補色関係にある2つの色（一般に赤とシアン）を用いて左右の眼用映像を同一画面に重ねて合成し、左右に異なる色フィルターを配置したメガネで観賞することで、左右の目に異なる画像（視差画像）を入力させる3D表示技術。特殊なディスプレイ装置を必要とせず、紙の印刷物や一般的なディスプレイでも立体視を実現できる。", "etymology": "ギリシャ語の ana（再び・上へ）＋ glyph（彫刻・浮き彫り）。\n「平面の上に再び浮き彫りのように像を浮かび上がらせる手法」が語源。", "exam": "マルチメディア・画像処理分野で出題されます。\n・3D表示技術の分類（アナグリフ/色分離、アクティブシャッタ/時分割、偏光/偏光分離）における、最も簡易で低コストな手法としての特徴\n・補色を利用して左右の画像を分離する仕組みと、色再現性の低下というデメリットの把握", "def30": "赤と青の補色画像を重ね専用メガネで色分離する3D技術。（27文字）", "id": 166}, {"term": "パララックスバリア方式\n(Parallax Barrier)", "summary": "・画面の前に細いスリット状の遮光帯（バリア）を置き、左右の目に異なる映像を光の角度で届ける裸眼3D技術。\n・専用メガネが不要で手軽だが、立体的に見える位置（視認角度・距離）が狭く、水平解像度が半分になる。", "keywords": "・裸眼3D技術\n・視差バリア（スリット状の格子）\n・スイートスポット（最適視認位置）\n・レンチキュラーレンズ方式との対比\n・両眼視差", "analogy": "「ブラインドの隙間から交互に覗く仕組み」です。\nテレビやゲーム機（ニンテンドー3DSなど）の画面の前に縦シマの細い柵（バリア）を置き、左目からは左目用の画像、右目からは右目用の画像しか見えないように角度を調節することで、メガネをかけずに立体に見せます。", "details": "ディスプレイ表面に細い縦縞状の光遮断膜（パララックスバリア）を配置し、液晶の画素から出る光の進行方向を左右の目ごとに制限する技術。特別なメガネをかけずに裸眼で3D映像を鑑賞できるが、画面の水平解像度が実質半分になり、特定の視認位置（スイートスポット）から外れると正常に立体視できない。", "etymology": "Parallax（視差：左右の目の位置の違いによるズレ）＋ Barrier（障害物・遮断板）。\n「目のズレ（視差）を意図的に作り出すための遮断板」という意味。", "exam": "マルチメディア・ディスプレイ技術分野で出題されます。\n・3D技術の中で「専用メガネを必要としない（裸眼方式）」グループに分類される点の理解\n・レンチキュラーレンズ方式（蒲鉾状のレンズを使う方式）との比較や、「解像度が落ちる」「見られる角度が限定される」という特徴の把握", "def30": "画面前の細い格子で左右の光を振り分け、裸眼で立体視させる技術。（29文字）", "id": 167}, {"id": 168, "term": "クリティカルパス\n(アローダイアグラム)", "summary": "・プロジェクトのアローダイアグラム（PERT図）において、最も時間がかかる（余裕時間ゼロの）最長経路のこと。\n・この経路上の作業が遅れると、プロジェクト全体が遅延する。", "keywords": "・アローダイアグラム（PERT図）\n・最長経路\n・余裕時間ゼロ\n・プロジェクト全体の所要日数\n・早期着手サイズ", "analogy": "「全作業の中で、絶対に遅れてはいけない一番カツカツな作業ルート」です。\n料理で言えば「お米を炊く40分（並行して味噌汁を作る）」の場合、お米を炊くルートが遅れると全体の完成が遅れるため、ここがクリティカルパスになります。", "details": "プロジェクトの各作業の関係を矢印で表したアローダイアグラムにおいて、開始から終了までを結ぶ経路のうち「最も所要日数が長い経路」。この経路上の作業の猶予時間（フロート）はゼロとなる。", "etymology": "Critical Path（決定的な・危機的な経路）。\nプロジェクト全体の完了日数を左右する一番クリティカル（重要）な一本道のこと。", "exam": "プロジェクトマネジメント分野の計算問題として超頻出！\n図（アローダイアグラム）を見て「プロジェクトの最短完了日数は何日か（＝クリティカルパスの合計日数）」を計算させる問題が頻繁に出題されます。", "def30": "アローダイアグラムにおいて最も所要日数が長い余裕ゼロの最長経路。（32文字）"}, {"id": 169, "term": "EVM\n(アーンドバリューマネジメント)", "summary": "・コストと進捗（スケジュール）を「金額（価値）」という共通の単位に換算して客観的に管理する手法。\n・PV, EV, AC や、CPI（コスト効率）, SPI（進捗効率）を用いる。", "keywords": "・PV（計画価値）\n・EV（出来高）\n・AC（実績コスト）\n・CPI（EV/AC）\n・SPI（EV/PV）\n・進捗とコストの定量管理", "analogy": "「10万円分の作業予定（PV）に対し、実際は8万円分の作業（EV）しか終わっておらず、しかも9万円使った（AC）」のように、進捗の遅れとお金の使いすぎをすべて金額で判定する手法です。", "details": "プロジェクトの進捗状況を、達成された作業の価値（出来高/EV）、予定されていた価値（PV）、実際にかかったコスト（AC）という「貨幣価値（金額）」で定量的に評価・管理するプロジェクト管理手法。", "etymology": "Earned Value Management の略。\nEarned Value（獲得した価値/出来高）によってプロジェクトを管理（Management）すること。", "exam": "プロジェクトマネジメント分野で頻出。\n・`CPI = EV ÷ AC`（1未満なら予算オーバー）\n・`SPI = EV ÷ PV`（1未満ならスケジュール遅延）\nという計算式や意味を問う問題が非常によく出ます。", "def30": "進捗とコストを「金額（出来高）」に換算して定量評価する管理手法。（32文字）"}, {"id": 170, "term": "SLA・ITIL\n(サービスレベル管理)", "summary": "・SLAはサービス提供者と顧客間で結ぶ「サービス品質（稼働率等）の合意書」。\n・ITILはITサービスマネジメントの成功事例を集めた「ベストプラクティス集（教科書）」。", "keywords": "・SLA（サービスレベル合意書）\n・SLM（サービスレベル管理）\n・ITIL（ベストプラクティス集）\n・稼働率99.9%\n・ITSM", "analogy": "「お店と客の約束事（SLA）」と「接客の伝説の指導マニュアル（ITIL）」です。\n「システム稼働率99.9%を保証します」と約束するのがSLAで、それを実現するための最高の運用ノウハウ本がITILです。", "details": "・SLA（Service Level Agreement）：ITサービスの提供者と利用者の間で、サービス内容や品質（稼働率、復旧時間等）について合意・定義した契約文書。\n・ITIL（IT Infrastructure Library）：ITサービスマネジメントの運用・管理における成功事例（ベストプラクティス）を体系化した書籍群。", "etymology": "SLA＝Service Level Agreement（取り決め）。ITIL＝IT Infrastructure Library（図書ライブラリ）。", "exam": "サービスマネジメント分野で超頻出！\n「稼働率や応答時間などの品質目標を明記した合意書＝SLA」「IT運用管理のベストプラクティス（成功事例）を集めたフレームワーク＝ITIL」という説明を選択させる問題が確実にでます。", "def30": "SLAはサービス品質の合意書、ITILはIT運用の成功事例集。（31文字）"}, {"id": 171, "term": "システム監査\n(監査調書・監査証拠)", "summary": "・独立した第三者が、情報システムのリスクやコントロールが適切かを客観的に評価し助言する活動。\n・作業記録（調書）や裏付けデータ（証拠）に基づき、結果を経営者に報告する。", "keywords": "・独立性・客観性\n・システム監査人\n・監査証拠（裏付けデータ）\n・監査調書（作業記録）\n・経営者への報告", "analogy": "「外部の専門家によるシステムの健康診断」です。\n社内のしがらみがない監査人が「セキュリティは万全か」「投資効果はあるか」を証拠を集めてチェックし、社長に「ここを改善した方がいいですよ」とアドバイスします。", "details": "組織の情報システムについて、信頼性・安全性・効率性などの観点から、独立かつ客観的な立場のシステム監査人が点検・評価し、改善勧告を行う一連の活動。発見事項は「監査証拠」に基づき「監査調書」に記録する。", "etymology": "System Audit。", "exam": "システム監査のプロセスや原則が問われます。「監査人は対象システムから独立した立場であるべき」「問題点を見つけたら、監査証拠を添えて監査報告書にまとめ、依頼者（経営者）に報告する」が頻出ポイント。", "def30": "独立した第三者がシステムの安全性や効率性を客観的に評価・助言する活動。（35文字）"}, {"id": 172, "term": "内部統制 / コーポレートガバナンス", "summary": "・「業務が適正に行われるための社内ルールや監視体制」と「経営者を監視し企業価値を高める企業統治」。\n・組織の健全性と透明性を確保する2つの仕組み。", "keywords": "・ITへの対応（IT統制）\n・J-SOX法\n・財務報告の信頼性\n・コンプライアンス（法令遵守）\n・ステークホルダー", "analogy": "内部統制は「社員が不正をしない仕組み作り」、コーポレートガバナンスは「社長が暴走しないよう株主等が監視する仕組み」です。どちらも健全な会社経営に不可欠です。", "details": "・内部統制：業務の有効性・効率性、財務報告の信頼性、法令遵守等の目的を達成するために組織内部に構築されるプロセス（J-SOX法など）。\n・コーポレートガバナンス：株主等のステークホルダーの利益を保護するための「企業統治」の仕組み。", "etymology": "Internal Control / Corporate Governance。", "exam": "ストラテジ（企業活動）分野で出題。内部統制の4つの目的や、ITを利用した統制（IT全般統制・IT業務統制）の概念、そしてガバナンス（企業統治）という言葉の意味そのものが問われます。", "def30": "業務を適正に行う社内体制(内部統制)と、経営を監視する企業統治(ガバナンス)。（39文字）"}, {"id": 173, "term": "ROI\n(投資利益率)", "summary": "・IT投資などの「投資額」に対して、どれだけの「利益」が得られたかを示す費用対効果の指標。\n・数値が高いほど投資効率が良い。", "keywords": "・投資利益率\n・費用対効果\n・IT投資評価\n・ROI ＝ 利益 ÷ 投資額 × 100", "analogy": "「コスパの良さ」です。\n100万円のシステム（投資）を入れて、年間150万円の人件費削減（利益）になったなら、ROIは150%（投資した金額の1.5倍のリターン）で「大成功の投資」と評価できます。", "details": "投資した資本に対して得られた利益の割合を示す財務指標。計算式は「(利益 ÷ 投資額) × 100」。IT投資案件の優先順位決定や、実施後の効果測定（IT投資評価）において客観的な基準となる。", "etymology": "Return On Investment（投資に対する見返り）。", "exam": "ストラテジ・IT投資評価の分野で頻出。計算問題として出題されるほか、「IT投資の費用対効果を評価する定量的な指標はどれか」という問題で正解になります。", "def30": "投資額に対してどれだけの利益が得られたかを示す、費用対効果（コスパ）の指標。（38文字）"}, {"id": 174, "term": "プロダクトライフサイクル\n(PLC)", "summary": "・製品が市場に投入されてから姿を消すまでの経過（導入期 → 成長期 → 成熟期 → 衰退期）。\n・時期に応じた最適なマーケティング戦略が問われる。", "keywords": "・導入期（認知向上）\n・成長期（シェア拡大）\n・成熟期（利益最大化・製品差別化）\n・衰退期（撤退/維持）\n・売上と利益のカーブ", "analogy": "「流行りものの寿命のストーリー」です。\n1.発売直後（導入期：広告を打つ） → 2.大ヒット（成長期：競合参入） → 3.定番化（成熟期：値引き合戦） → 4.ブーム去る（衰退期）。", "details": "製品が市場に発売されてから排除されるまでの普及過程を時間の経過に沿って4つの段階（導入期・成長期・成熟期・衰退期）に分け、各段階で取るべき戦略を分析する理論。", "etymology": "Product Life Cycle（製品の生涯）。", "exam": "ストラテジ・マーケティング分野で頻出！「売上は伸びるが利益はまだ低い＝導入期」「売上・利益ともに急増し競合が参入する＝成長期」「売上は頭打ちだが利益が最も出る＝成熟期」という各期の特徴を選ばせる問題が出ます。", "def30": "製品の普及過程を導入期・成長期・成熟期・衰退期に分け戦略を練る。（32文字）"}, {"id": 175, "term": "ポートフォリオ・リスク分散", "summary": "・単一の投資先や事業に集中せず、複数の異なるリスク特性を持つ資産へ分散してリスクを軽減する考え方。\n・「卵は一つのカゴに盛るな」の原則。", "keywords": "・分散投資\n・リスク軽減\n・資産配分\n・相関関係\n・リスクとリターン", "analogy": "「卵をいくつかのカゴに分けて持つ」ことです。\nカゴを1つ落としても他のカゴの卵は割れないように、投資先や事業を分けておけば、どれか1つがダメになっても全滅を避けられます。", "details": "複数の異なる銘柄や資産（株式、債券、不動産等）に資金を分散して運用することで、市場の変動リスクを抑えつつ安全に収益を目指す投資・事業管理の概念。", "etymology": "Portfolio（書類挟み、資産の組み合わせ）。", "exam": "ストラテジ・経営分野で出題。「相関係数がマイナスの資産同士を組み合わせるとリスク軽減効果が高まる」「投資リスクを分散させる」という説明が問われます。", "def30": "複数の資産や事業に分散して投資し全体のリスクを低減させる考え方。（32文字）"}, {"id": 176, "term": "ロングテール / フリーミアム", "summary": "・「ニッチ商品の積もり積もった売上がヒット作を超える」法則と、「基本機能は無料、高度機能は課金」とするビジネスモデル。", "keywords": "・ロングテール（ニッチ商品の集積\n・ネット通販）\n・パレートの法則の逆\n・フリーミアム（基本無料・プレミアム課金）\n・サブスクリプション", "analogy": "・ロングテール：実店舗では置けないマニアックな本も、Amazonなら無限に置けて全国から少しずつ売れるため、塵も積もって大ベストセラーの売上を超えます。\n・フリーミアム：スマホアプリによくある「基本プレイ無料、強いガチャは課金」の仕組みです。", "details": "・ロングテール：販売機会の少ないニッチな商品の売上合計が、少数のヒット商品の売上合計を上回る現象（ネット通販特有）。\n・フリーミアム：基本的なサービスを無料で提供して多数のユーザーを獲得し、一部のユーザーからプレミアム機能の料金を徴収して収益を上げるビジネスモデル。", "etymology": "Long Tail（恐竜の長い尻尾のようにグラフが伸びる形）。Free（無料）＋ Premium（割増料金）。", "exam": "経営戦略のビジネスモデル問題で頻出。「販売機会の少ない商品群の売上合計が全体の大半を占める＝ロングテール」「基本的なサービスを無料で提供し、高度な機能で課金する＝フリーミアム」。", "def30": "ニッチ商品の売上合算が全体を支える法則(ロングテール)と基本無料モデル(フリーミアム)。（44文字）"}, {"id": 177, "term": "BPR\n(ビジネスプロセス・リエンジニアリング)", "summary": "・企業の目標（売上増、コスト削減等）を達成するために、既存の業務プロセスを「根本的」に見直し、再設計（リエンジニアリング）すること。", "keywords": "・業務プロセスの抜本的見直し\n・根本的な再設計\n・BPM（継続的改善）\n・ITの積極活用", "analogy": "「手書き伝票をExcelにする（改善）」のではなく、「伝票という制度自体をなくして、スマホアプリで直結させる（BPR）」ような、仕事のやり方そのものをゼロベースで作り直す大改革です。", "details": "コスト、品質、サービス、スピードなどの劇的な改善を達成するために、既存の組織構造や業務プロセスを白紙に戻し、情報技術（IT）を活用して抜本的に再設計・再構築する経営手法。", "etymology": "Business Process（業務の手順） Re-engineering（再構築する）。", "exam": "ストラテジ分野で出題。「漸進的（少しずつ）な改善」ではなく、「抜本的・根本的な見直し・再設計」という強めのキーワードがあればBPRが正解です。", "def30": "既存の業務プロセスを白紙に戻し、ITを活用して根本的に再設計・再構築する経営手法。（41文字）"}, {"id": 178, "term": "ERP / SCM / CRM / SFA", "summary": "・企業の業務を効率化する主要ITシステム群。\n・経営資源の統合管理、供給網（サプライチェーン）の最適化、顧客関係の管理、営業活動の支援を行う。", "keywords": "・ERP（統合業務/資源一元化）\n・SCM（サプライチェーン/納期短縮・在庫最適化）\n・CRM（顧客関係/LTV向上）\n・SFA（営業支援/日報・案件管理）", "analogy": "・ERP：会社の「人・モノ・金」を一つのシステムで一元管理する。\n・SCM：部品調達から販売までの「モノの流れ」を最適化し在庫を減らす。\n・CRM：「常連客」を大切にして売上を伸ばす顧客管理。\n・SFA：営業マンの「営業ノウハウ」をチームで共有する。", "details": "・ERP：Enterprise Resource Planning。企業の経営資源を統合的に管理する。\n・SCM：Supply Chain Management。調達・製造・物流・販売の供給網全体を最適化する。\n・CRM：Customer Relationship Management。顧客情報を管理し顧客満足度を高める。\n・SFA：Sales Force Automation。営業活動を支援・効率化する。", "etymology": "Enterprise Resource Planning / Supply Chain Management / Customer Relationship Management / Sales Force Automation。", "exam": "ストラテジ分野で頻出のアルファベット略語。「供給網全体の最適化による在庫削減＝SCM」「顧客との長期的な関係構築＝CRM」「営業担当者のスケジュールや商談履歴の共有＝SFA」がキーワード。", "def30": "経営資源統合(ERP)、供給網最適化(SCM)、顧客管理(CRM)、営業支援(SFA)を行うシステム。（51文字）"}, {"term": "EDI\n(Electronic Data Interchange)", "summary": "・企業間で発注書、納品書、請求書などの商取引データを、標準的なフォーマットに従って電子的に交換する仕組み。\n・ペーパーレス化や事務作業の高速化・自動化を実現する。", "keywords": "・企業間電子データ交換\n・標準フォーマット（JCA手順、CII、流通BMS等）\n・ペーパーレス / 自動化\n・Web EDI / インターネットEDI", "analogy": "「企業と企業を直結するデジタルFAX」です。\nFAXで紙の注文書を送って手入力し直すのではなく、お互いのPC同士が決められたフォーマット（電子データ）で直接注文書をやり取りし、受注処理まで自動で終わらせます。", "details": "受発注、出荷、請求などの企業間取引データを、人手を介さずに専用回線やインターネット経由で相互のコンピュータへ自動送信・処理する仕組み。フォーマットや識別コード、通信手順の標準化（標準プロトコル）が不可欠。", "etymology": "Electronic（電子的な）＋ Data（データ）＋ Interchange（相互交換）。\n「電子データによる企業間取引のやり取り」という意味。", "exam": "企業活動・電子商取引（EC）分野で超頻出！\n・【社内】統合のEAIに対し、【企業間】の電子取引を指す相違点\n・データフォーマットや通信手順の標準化が不可欠であること\n・従来の電話回線（INSネット等）からインターネットEDIへの移行", "def30": "企業間で注文書や請求書等の取引データを電子交換する仕組み。（29文字）", "id": 179}, {"id": 180, "term": "DX\n(デジタルトランスフォーメーション)", "summary": "・IT技術を活用してビジネスモデルや業務、組織文化を根本から変革し、競争上の優位性を確立すること。\n・単なる「IT化（レガシー脱却）」を超えた変革。", "keywords": "・ビジネスモデル変革\n・レガシーシステム脱却\n・競争優位性の確立\n・デジタル技術活用\n・2025年の崖", "analogy": "「紙の帳票をExcelに変える（単なるIT化）」ではなく、「データを使って誰も思いつかなかった新しいビジネスを始める（DX）」という根本的な変革のことです。", "details": "単なる業務の効率化（IT化）にとどまらず、データとデジタル技術を活用して、顧客や社会のニーズを基に、製品やサービス、ビジネスモデル、業務プロセス、組織変革を行うこと。", "etymology": "Digital Transformation の略（TransをXと略す慣習からDX）。", "exam": "ストラテジ分野の最新トレンド問題！「単なる業務のデジタル化（デジタイザシオン）ではなく、顧客価値やビジネスモデルそのものを変革すること」「老朽化した既存システムの刷新（2025年の崖）」がキーワードです。", "def30": "デジタル技術を活用し、ビジネスモデルや組織を根本から変革する。（31文字）"}, {"id": 181, "term": "QC7つ道具\n(パレート図・特性要因図など)", "summary": "・品質管理（QC）でデータ分析や原因追及に用いる7つの図表手法。\n・パレート図（ABC分析/重点項目発見）と特性要因図（フィッシュボーン図/原因特定）が特に頻出。", "keywords": "・パレート図（棒グラフ＋折れ線）\n・特性要因図（フィッシュボーン・原因と結果）\n・散布図（相関関係）\n・管理図（上方・下方管理限界線）", "analogy": "・パレート図：「売上の8割は2割のヒット商品で作られる」のような、重点的に対策すべき項目を見つけるグラフ。\n・特性要因図：「なぜケーキが焦げたのか？」を魚の骨のように原因（オーブン、温度、時間等）に分解して探る図。", "details": "品質管理のためのツール群。\n1.パレート図（項目を降順に並べた棒と累積比率の折れ線）\n2.特性要因図（結果と原因の関連を魚の骨状に表す）\n3.散布図（2変数の相関）\n4.管理図（時系列のばらつき異常検知）\n等を含む。", "etymology": "Quality Control（品質管理） 7 Tools。", "exam": "マネジメント分野で毎回必ず1問は出る図表識別問題！「累積相対度数の折れ線グラフを重ねて重要項目を把握する＝パレート図」「原因と結果の関連を魚の骨のように描く＝特性要因図」は絶対暗記です。", "def30": "品質管理において、重点項目の発見（パレート図）や原因分析（特性要因図）に使う図表。（41文字）"}, {"id": 182, "term": "RFI / RFP\n(提案依頼書)", "summary": "・外注先に対し、技術情報（実績・カタログ）の提供依頼や、具体的なシステム提案書・見積りの提出を依頼する手続き。", "keywords": "・RFI（情報提供依頼書）\n・RFP（提案依頼書）\n・システム調達\n・ベンダー選定\n・要件定義後", "analogy": "・RFI：「こんなシステムを作りたいんだけど、御社はどんな技術や実績を持ってるか教えて（カタログ請求）」。\n・RFP：「こういう要件で作るから、具体的なスケジュールと金額の提案書を出して（見積・提案要求）」。", "details": "・RFI (Request for Information)：発注先候補に対し、実績や技術などの一般的な情報の提供を依頼する文書。\n・RFP (Request for Proposal)：発注先候補に対し、システムの具体的な要件や調達条件を示し、提案書や見積書の提出を依頼する文書。", "etymology": "Request for Information / Request for Proposal。", "exam": "システム企画・調達分野で頻出。順番として「RFI（情報収集）」→「RFP（具体的な提案要求）」の順に進むことと、それぞれの役割の違いが問われます。", "def30": "外注先に対し、技術情報の提供（RFI）や、具体的なシステム提案と見積り（RFP）を依頼する。（46文字）"}, {"id": 183, "term": "SoC\n(System on a Chip)", "summary": "・CPUやメモリ等のシステム構成要素を1つの半導体チップ上に集積する技術。\n・部品の小型化や省電力化・低コスト化を実現し、スマホやIoT機器等に採用される。", "keywords": "・CPU\n・メモリ\n・周辺回路\n・ワンチップ化\n・小型化・省電力化\n・組み込みシステム\n・スマホ", "analogy": "「全部入りのオールインワン・チップ」です。\nPCのようにCPUやメモリを別々のパーツとして基板に並べるのではなく、1枚の小さなチップの中にすべての回路を凝縮して焼き付けます。", "details": "ひとつの半導体チップ上に、CPU、GPU、メモリインタフェース、通信機能など、システムの動作に必要な主要機能を統合した集積回路。実装面積の縮小、バス遅延の低減、省電力化を実現する。", "etymology": "System on a Chip の略。\nシステム（System）全体の機能を、ひとつの（a）チップ（Chip）の上（on）に集積させたもの。", "exam": "ハードウェア・組み込みシステム分野で頻出。\n「システムの構成要素を1つの半導体チップ上に集積する」「実装面積の縮小や省電力化」「スマホや組み込み機器に採用」という記述が正解のポイントです。", "def30": "システムに必要な複数の機能を一枚のチップに集積する技術。（28文字）"}, {"id": 184, "term": "アクチュエータ\n(Actuator)", "summary": "・電気信号等を機械的な「物理運動（回転・伸縮など）」に変換する駆動装置。\n・IoTや組み込みシステムにおいて、センサーと対で機能する「筋肉」の役割。", "keywords": "・駆動装置\n・電気信号を物理運動に変換\n・モータ/ソレノイド/シリンダ\n・IoT\n・組み込みシステム\n・制御対象", "analogy": "「ロボットや家電の『筋肉』」です。\nセンサー（目や耳）が検知した命令を受けて、実際にモーターを回したり腕を伸ばしたりして「物理的な動き」を作ります。", "details": "制御装置からの電気・油圧・空圧などの信号を受け取り、それを直線運動や回転運動などの物理的な機械運動に変換して対象を駆動する装置。モータ、ソレノイド、油圧シリンダ等が代表例。", "etymology": "Actuator（作動させるもの）。\nAct（動作する、作用する）＋ -or（〜するもの）。信号を受けて実際に動作を起こす機器。", "exam": "組み込みシステム・IoT・ハードウェア分野で超頻出！\n「物理現象を電気信号に変換＝センサ」「電気信号を物理的な運動に変換＝アクチュエータ」という対比が確実に出ます。", "def30": "電気信号等を物理的な運動や力に変換して対象を駆動する装置。（32文字）"}, {"id": 185, "term": "TCO\n(Total Cost of Ownership)", "summary": "・ITシステムの導入費用（初期コスト）だけでなく、運用・管理・保守・教育費用などの「総保有コスト」のこと。\n・隠れたコストを可視化する。", "keywords": "・初期導入コスト（イニシャルコスト）\n・運用保守コスト（ランニングコスト）\n・総所有コスト\n・IT投資評価", "analogy": "「車の『車体価格＋ガソリン代・車検代・駐車場代』の合計」です。\n安く車（システム）を買えても、毎月のガソリン代や維持費（ランニングコスト）が高いと、全体の出費（TCO）は膨れ上がります。", "details": "コンピュータシステムの導入から運用、保守、廃棄に至るまでに必要なすべての費用（総保有コスト）の合計。ハード/ソフトの購入費（直接コスト）だけでなく、管理人件費や障害対応費、教育費（間接コスト）も含まれる。", "etymology": "Total Cost of Ownership（所有にかかる総コスト）。", "exam": "ストラテジ・IT投資評価で超頻出！「システムの導入費用だけでなく、運用・保守・人件費を含めた全体の総コスト＝TCO」「TCOを削減することがIT管理の目標となる」。", "def30": "システムの初期導入費から運用・保守・人件費まで含めた総保有コスト。（33文字）"}, {"id": 186, "term": "TCP/IP\n(3ウェイハンドシェイク)", "summary": "・インターネットの標準プロトコル。信頼性重視（コネクション型）と速度重視（コネクションレス型）がある。\n・接続確立には「SYN → SYN-ACK → ACK」の手順を使う。", "keywords": "・信頼性重視\n・3ウェイハンドシェイク\n・SYN/ACK\n・UDPとの違い\n・コネクション型", "analogy": "「電話をかける時の『もしもし』『はい』『今いいですか』の確認」です。\nお互いに「聞こえますか？」「はい聞こえます、そちらは？」「大丈夫です！」と3ステップ（3ウェイ）で確認し合ってから、本題のデータを話し始めます。", "details": "インターネットで広く使われる標準通信プロトコル。TCPはコネクション型の信頼性の高い通信を提供し、送信前に「3ウェイハンドシェイク」によって接続を確立する。", "etymology": "Transmission Control Protocol / Internet Protocol の略。\n通信を制御（Control）する手順と、インターネット上の住所（IP）を定めた規格。", "exam": "ネットワーク分野で超頻出。\nTCP（信頼性・コネクション型）とUDP（高速性・コネクションレス型・動画配信向け）の対比や、接続手順である「SYN $\rightarrow$ SYN-ACK $\rightarrow$ ACK」の順番がそのまま問われます。", "def30": "3ウェイハンドシェイクにより信頼性の高い通信を行う標準規格。（30文字）"}, {"id": 187, "term": "ペトリネット", "summary": "・並行して動作するシステムや制御の流れを「プレース（丸）」「トランジション（四角）」「トークン（黒点）」で視覚的にモデル化する数学的ツール。", "keywords": "・プレース（状態/丸）\n・トランジション（発火/四角）\n・トークン（トークン移動）\n・並行処理モデル\n・同期制御", "analogy": "「トークン（コイン）が移動するゲーム盤」です。\n条件が揃うと四角（トランジション）が発火して、コイン（トークン）が次の丸（プレース）へ移り、複雑な並行作業の動きをシミュレーションします。", "details": "並行処理や分散システムの状態遷移を表現するグラフィカルな数学モデル。状態を表すプレース、事象を表すトランジション、状態の成立を示すトークンからなり、トークンの移動で動作を表現する。", "etymology": "Petri Net（提唱者カール・アダム・ペトリの名に由来）。", "exam": "ソフトウェア工学・システム評価で出題。「プレース、トランジション、トークンを用いて並行動作するシステムをモデル化する＝ペトリネット」が正解キーワード。", "def30": "丸・四角・黒点を用いて並行システムの動作や同期を表現するモデル。（32文字）"}, {"id": 188, "term": "ヒューリスティック評価法", "summary": "・ユーザビリティ評価手法の一つ。\n・複数のUI/UX専門家が「既知の経験則（ガイドライン）」に基づいてシステムを操作し、使いやすさの問題点を発見・評価する手法。", "keywords": "・ユーザビリティ評価\n・経験則\n・UI/UX専門家\n・ニールセンの原理\n・定性評価\n・ユーザーテストとの違い", "analogy": "「プロのインテリアデザイナーによるお部屋チェック」です。\n実際の住人（ユーザー）に試してもらうのではなく、プロの知識（経験則）に基づいて「この導線は歩きにくい」とチェックしてもらいます。", "details": "ヤコブ・ニールセンらが提唱したUI/UXの評価手法。複数の専門家が、あらかじめ定められたデザイン上の経験則（ヒューリスティックス）に照らし合わせて画面を評価し、問題点を洗い出す。", "etymology": "Heuristic（発見的な、経験則の）。", "exam": "人間工学・UIデザイン分野で出題。「専門家が既知の経験則に基づいてユーザビリティを評価する＝ヒューリスティック評価」「実際の被験者に操作してもらう＝思考発話法・ユーザーテスト」。", "def30": "UI専門家が経験則に基づき画面を操作し、ユーザビリティ上の問題を評価する。（37文字）"}, {"id": 189, "term": "IDE\n(統合開発環境)", "summary": "・テキストエディタ、コンパイラ、デバッガ、ビルドツール等を1つの画面に統合したソフトウェア開発支援ツール（VS CodeやEclipse等）。", "keywords": "・エディタ\n・コンパイラ\n・デバッガ\n・開発効率化\n・Eclipse\n・VS Code\n・GUI環境", "analogy": "「プログラマのための万能文房具セット」です。\nペン（エディタ）、消しゴム（デバッガ）、製本機（コンパイラ）が全部デスクの上に揃っていて、ボタン1つでプログラムを作成・テストできます。", "details": "ソフトウェア開発に必要な各種ツール（コードエディタ、コンパイラ、リンカ、デバッガ、GUI構築ツール等）を単一のユーザーインターフェース上に統合し、開発作業を一元化・効率化する環境。", "etymology": "Integrated Development Environment（統合開発環境）。", "exam": "システム開発のツール環境問題で出題。「エディタやデバッガ等の開発ツールを一元化して操作できるソフトウェア＝IDE（統合開発環境）」。", "def30": "エディタやコンパイラ、デバッガ等を一元化し開発作業を支援するツール。（34文字）"}, {"id": 190, "term": "CAP定理", "summary": "・分散データベース（NoSQL等）において、「一貫性（Consistency）」「可用性（Availability）」「分断耐性（Partition tolerance）」の3つを「同時には2つまでしか満たせない」という理論。", "keywords": "・Consistency（一貫性）\n・Availability（可用性）\n・Partition Tolerance（分断耐性）\n・2つしか選択できない\n・NoSQLの設計指針", "analogy": "「三者択一のトレードオフ」です。\n『絶対正確なデータ（C）』『いつでも応答（A）』『途中の回線が切れても動く（P）』の3つのうち、同時に実現できるのは最大2つまでという限界を示します。", "details": "エリック・ブリュワーズが提唱した分散システムの基本定理。1.Consistency（データの一貫性）、2.Availability（サービスの可用性）、3.Partition tolerance（ネットワーク分断への耐性）の3つの保証を、分散DBは同時に最大2つしか提供できないとする法則。", "etymology": "CAP Theorem (Consistency, Availability, Partition tolerance)。", "exam": "NoSQLや分散DBの理論問題で頻出。「CAP定理において分散システムが同時に満たせる要素は最大何個か（答え：2つ）」「NoSQLの多くはAP（可用性と分断耐性）を重視する」。", "def30": "分散DBで一貫性・可用性・分断耐性の3つのうち同時に2つしか満たせない理論。（38文字）"}, {"id": 191, "term": "SOA\n(サービス指向アーキテクチャ)", "summary": "・大規模なシステムを「独立したサービス」という単位で構築し、それらを組み合わせることでシステム全体を再構築しやすくする設計思想。", "keywords": "・サービス単位\n・再利用性\n・ESB（エンタープライズサービスバス）\n・ビジネスプロセスの柔軟性\n・Webサービス", "analogy": "「レゴブロックで家を建てる」考え方です。\n「会員認証」「決済」「メール送信」という独立したブロック（サービス）を作っておき、必要な組み合わせで家（新しいシステム）を組み立てます。", "details": "業務上の1機能（例: 信用照会、在庫引き当て等）を「独立したサービス」として定義し、これらを標準的なインターフェース（Webサービス等）で連携させてシステム全体を構築するアーキテクチャ思想。", "etymology": "Service-Oriented Architecture（サービス指向の構造）。", "exam": "ストラテジ・システム設計分野で出題。「業務機能を独立したサービスとして構築し、それらを組み合わせてシステムを柔軟に再構築する設計思想＝SOA」。", "def30": "業務機能を独立したサービスとして定義し、柔軟に連携・再構築する設計思想。（36文字）"}, {"id": 192, "term": "FTA\n(故障木解析)", "summary": "・システムで発生し得る最悪の事故（トップイベント）を出発点とし、その原因となる事象をロジックゲート（AND/OR）で樹木状に下位へ分解・分析する手法。", "keywords": "・トップダウン解析\n・トップイベント\n・ロジックゲート（AND/OR）\n・発生確率の試算\n・信頼性解析", "analogy": "「なぜ事故が起きたのかの逆引きツリー」です。\n『飛行機が墜落した』という最悪の事故を頂点に置き、「エンジン故障」かつ（AND）「予備電源不作動」のように論理記号で原因を根本へ掘り下げて分析します。", "details": "システムの不具合や重大事故（トップイベント）を最上部に置き、その発生要因となる機器の故障や人的ミスなどの一次事象を論理ゲート（AND/OR）を用いて木構造（ツリー状）に分解・解析し、発生確率を評価する信頼性解析手法。", "etymology": "Fault Tree Analysis（故障の木解析）。", "exam": "信頼性工学・リスク管理で出題。「発生した事故から論理ゲート（AND/OR）を用いて原因を樹木状に下位へ追跡・分析する手法＝FTA（故障木解析）」が正解。", "def30": "重大事故を頂点とし、原因となる不具合を論理ゲートで樹木状に分解・解析する手法。（39文字）"}, {"id": 193, "term": "有限オートマトン\n(DFA / NFA)", "summary": "・有限個の状態を持ち、入力信号に応じて状態を遷移させながら処理を行う計算モデル。\n・次の状態が一意に決まる決定性（DFA）と複数の遷移先を持ち得る非決定性（NFA）がある。", "keywords": "・状態遷移図 / 状態遷移表\n・初期状態・受理状態（終了状態）\n・決定性有限オートマトン（DFA）\n・非決定性有限オートマトン（NFA）\n・正規表現（正則表現）", "analogy": "「自動販売機のコイン受付ロジック」です。\n『待機状態（0円）』に『100円投入』という入力が入ると『100円保持状態』へ遷移し、『ボタン押下』で『商品排出＋初期状態』へ戻るというような「状態の変化ルール」を数理モデルにしたものです。", "details": "有限個の状態、初期状態、受理（終了）状態、および入力記号による遷移規則で定義される理論上の計算機。コンパイラの字句解析や文字列のパターンマッチング、通信プロトコルの状態管理などに広く応用される。非決定性有限オートマトン（NFA）は、アルゴリズムによって必ず等価な決定性有限オートマトン（DFA）に変換できる。", "etymology": "Finite Automaton（FSM: Finite State Machine）。\nFinite（有限の）＋ Automaton（自動人形、からくり）。「状態の数が有限である自動機械」という意味。", "exam": "テクノロジ系（基礎理論）で頻出！\n・提示された「状態遷移図（または表）」を見て、「どの文字列を入力したときに受理状態に到達するか」を答える識別問題\n・「0と1が交互に並ぶ文字列を受理するオートマトンはどれか」といったパターン判定問題\n・正規表現（プログラミングの検索パターン）との相互変換問題", "def30": "有限個の状態を持ち、入力に応じ状態を遷移させ処理を行うモデル。（31文字）"}] ;
